INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40601854635', 'Kit Bíblia Sagrada ACF | Leão Judá Rosa + Bíblia Sagrada NVI | Leão Judá', 'Bíblia Sagrada ACF | Leão Judá Rosa | Capa Dura Descubra a Bíblia Almeida Corrigida e Fiel (ACF): Fidelidade e Precisão nas Escrituras Explore a riqueza das Escrituras com a Almeida Corrigida e Fiel (ACF), uma tradução que se destaca pela fidelidade rigorosa aos textos originais em hebraico e grego. Elaborada por João Ferreira de Almeida, renomado tradutor bíblico, a ACF é a escolha ideal para quem busca uma abordagem mais literal e precisa na leitura da Palavra de Deus. Bíblia Sagrada | NVI | Leão Judá | Capa Dura Descubra a Bíblia Sagrada NVI Explore as Escrituras de maneira clara e acessível com a Nova Versão Internacional (NVI) da Bíblia! Publicada pela Sociedade Bíblica Internacional, a NVI é uma tradução moderna que mantém a fidelidade aos textos originais, oferecendo uma leitura envolvente e compreensível.', 49.9, 49.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma35f8jh6wjdac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F40601854635', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254081260', 'Par Pistões Amortecedor Tampa Do Vidro Kia Sportage 2005 A 2010', 'Par Amortecedor Tampa Do Vidro Kia Sportage 2005 A 2010 Produto novo, de alta qualidade e excelente durabilidade. Fabricado com materiais de primeira linha, garantindo resistência, acabamento superior e funcionamento perfeito da Tampa Do Vidro. Compatível com todas as versões do Kia Sportage 2005 A 2010. Instalação fácil, com fixação por encaixe, sem necessidade de adaptação. Garantia de 3 meses contra defeitos de fabricação. Envio imediato e atendimento especializado. A melhor opção para quem busca qualidade, durabilidade e ótimo custo-benefício. OBSERVAÇÕES IMPORTANTES: • A mola a gás só irá encolher após a instalação no veículo. • Recomendamos conferir as medidas antes da instalação para assegurar compatibilidade total. CARACTERÍSTICAS PRINCIPAIS: • Veículo compatível: Kia Sportage 2005 A 2010 • Quantidade: Par (2 unidades) • Aplicação: Tampa Do Vidro • Comprimento estendido: 480 mm (48 cm) • Comprimento comprimido: 300 mm (30 cm) • Tipo de fixação: Encaixe rápido (sem necessidade de adaptação) • Material: Aço com pintura protetiva • Garantia: 3 meses contra defeitos de fabricação • Instalação: Simples e prática, podendo ser feita sem ferramentas especiais • Envio: Imediato após confirmação da compra', 109.9, 109.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-8261h-mjyl4lk20v7l91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F687222661%2F58254081260', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499247133', 'Guarda Roupa Casal 100% MDF 8 Portas 4 Gavetas Jatobá Yescasa Cinamomo/Off White Cinamomo/Off White', 'Transforme seu quarto em um oásis de organização e estilo com o Guarda-Roupa Casal Jatobá da Yescasa. Projetado para quem precisa de máxima capacidade de armazenamento sem abrir mão da elegância, este móvel combina um design moderno com uma estrutura robusta e durável. Com imponentes 226 cm de largura e 199 cm de altura, este guarda-roupa oferece uma solução definitiva para organizar os pertences do casal. Sua estrutura é inteiramente fabricada em MDF, um material reconhecido pela sua resistência e excelente acabamento, garantindo um móvel para muitos anos. Organização Interna Completa O grande diferencial do modelo Jatobá é sua divisão interna inteligente, pensada para facilitar a rotina: • 8 Portas de Bater: Oferecem acesso total e visualização completa do interior. Os puxadores externos em MDF garantem uma pegada firme e complementam o design sofisticado. • 4 Gavetas Internas: Posicionadas centralmente, as gavetas possuem corrediças metálicas que proporcionam um deslizar suave e seguro. São ideais para armazenar roupas íntimas, pijamas e acessórios de forma discreta e ordenada. • Amplas Prateleiras: Diversas prateleiras internas criam nichos perfeitos para guardar roupas dobradas, caixas organizadoras, sapatos e roupa de cama. • Cabideiro Resistente: Um cabideiro espaçoso permite pendurar roupas, camisas e casacos, mantendo-os sem amassados e sempre prontos para o uso. Importante: o produto não inclui itens decorativos ou acessórios mostrados nas imagens. Confira o título e a ficha técnica completa para garantir que sua compra seja exatamente o que você espera! Garanta o encaixe perfeito! Planeje seu ambiente com cuidado comparando as medidas do produto com o espaço disponível e reserve uma folga de até 2 cm para posicioná-lo com conforto. Estilo: Moderno Modular: Não Peso (kg): 117 Garantia: 03 Meses Altura (cm): 199 Largura (cm): 226 Possui Pés: Não Possui Gancho: Não Possui Nichos: Não Possui Portas: Sim Tipo de Porta: Bater Porta Janelada: Sim Possui Gavetas: Sim Tipo de Gaveta: Interna Possui Espelhos: Não Profundidade (cm): 47 Possui Calceiros: Não Possui Capelinha: Não Possui Sapateira: Não Material da Porta: MDF Origem do Produto: Nacional Possui Cabideiros: Sim Possui Iluminação: Não Ambiente Principal: Quarto Material da Gaveta: MDF Material Principal: MDF Necessita Montagem: Sim Possui Penteadeira: Não Possui Prateleiras: Sim Nicho com Cabideiro: Não Tipo de Guarda-roupa: Casal Espessura do Fundo (mm): 3 Material da Prateleira: MDF Possui Espelho Interno: Não Quantidade de Espelhos: Não possui Espessura das Portas (mm): 12 Complexidade da Montagem: Alta: deve ser montado por um montador especializado Tipo de Puxador da Porta: Externo Espessura da Estrutura (mm): 12 Tipo de Puxador da Gaveta: Não Possui Peso Máximo por Prateleira: 5 Tipo de Corrediça da Gaveta: Metálica Simples Espessura das Prateleiras (mm): 12 Material do Puxador da Porta: MDF Possui Organizador de Gaveta: Não Espessura do Fundo das Gavetas (mm): 3 Possui Espaço para Vestidos Longos: Não Tipo de Dobradiça/Corrediça da Porta: Metálica Marca: Yescasa Cor: Cinamomo/Off White Cor do Produto: Cinamomo/ Off White Itens Inclusos: 1 Guarda-Roupa, Kit Ferragem e Manual de Montagem Linha ou Coleção: Yescasa Cor do Puxador: Marrom Quantidade de Cabideiros: 01 Cabideiro Quantidade de Prateleiras: 06 Prateleiras Quantidade de Portas: 8 Portas Quantidade de Portas com Espelhos: Nenhuma', 1158.09, 1047.2, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-8257y-mqx1w7zbsemk7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F21499247133', NULL, NULL, '2026-07-28T02:11:31.70