INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699300690', 'Painel Ripado de PVC 6 Barras de 2,70MX15CM (2,43m²) Bariri Cerejeira', 'Painel Ripado de Pvc 2,70 X 0,15 cm acabamento Cerejeira, combina com qualquer ambiente, para ser usado com efeito decorativo, composição Pvc, alta durabilidade e resistência , prova d''água, dispensa pintura, não propaga chamas, é imune a cupins, umidade, fungos e corrosão. Produzido com maior expessura, sendo o mais rigido e forte do mercado. Fácil instalação, acabamento de alta qualidade, estética natural , economia de 80% em sua obra, aplicação em parede e teto... Normatizado laudo anti chama NBR 14.285, Densidade Óptica fumaça ASTM E 662 , Indice Propagação de Chamas NBR 9442. Embalagem com 06 unidades. Para saber quantas unidades comprar, basta dividir a largura da parede pela largura do ripado. EX: Parede 3,00m dividir por 0,150m (ripado) = 20 barras Garantia: 12 Meses Altura (cm): 270 Largura (cm): 15 Área Indicada: Interna Escala de Brilho: Fosco Área de Cobertura: 0.405 Emissão de Ruídos: (1) Baixo Tipo de Painel Ripado: Barra Material Principal Construção e Acabamento: PVC Marca: Bariri Cor: Cerejeira Cor do Produto: Cerejeira Quantidade do Produto: 6', 455.75, 374.83, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/sg-11134201-824gk-mpwgmn9v9lhp60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F20699300690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093645962', 'Escrivaninha Mesa Escritório com Estrutura Flexível, Nomad 4 Nichos 1 Porta 114cm Cinamomo e Off White Marrom', 'Escrivaninha Nomad: O Móvel Perfeito para o Seu Estilo de Vida Dinâmico. A Escrivaninha Nomad é a solução inteligente para quem busca flexibilidade e elegância. Com seu design multifuncional, ela pode ser configurada em L, reta ou até mesmo fechada, graças ao seu tampo rotativo de 360°, oferecendo total liberdade para adaptar o espaço conforme suas necessidades. Seus cantos arredondados garantem um visual moderno e maior segurança. Além disso, conta com 4 nichos organizadores e uma porta de correr para armazenar tudo de forma prática e organizada. Compacta e versátil, a Nomad é a peça ideal para otimizar qualquer ambiente com estilo. Peso (kg): 21 Garantia: 03 Meses Altura (cm): 73.5 Largura (cm): 114 Profundidade (cm): 92 Escala de Brilho: Fosco Origem do Produto: Nacional Ambiente Principal: Escritório Espessura do Tampo (mm): 15 Material Principal: MDF Necessita Montagem: Sim Formato da Escrivaninha: Em L Marca: Artely Cor do Produto: Cinamomo /Off White Itens Inclusos: 1 Escrivaninha para Escritório Cor Predominante: Marrom Linha ou Coleção: Nomad', 427.98, 427.98, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-825a5-mqjlovith9n042', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F23093645962', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
