INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894657100', 'Serra Sabre a Bateria 12v com Gatilho de Velocidade Variável Acompanha Maleta SSV122 Vonder', 'Compacta, leve e eficiente, possui cabo com revestimento emborrachado, proporcionando maior conforto ao operador. Conta ainda com trava de segurança do gatilho, o que garante maior segurança na operação. Além disso, possui gatilho com velocidade variável, LEDs indicadores de nível de carga da bateria e sistema de troca rápida de acessórios, que facilitam e agilizam os trabalhos. Indicada para serrar madeira, plástico, metal, sempre usando a lâmina apropriada. Conteúdo da Embalagem: 1 Serra sabre. Acompanha: 1 maleta, 1 lâmina, 1 apoio de corte, 1 bateria e 1 fonte de carregamento bivolt automático e 1 base para bateria. Detalhes Técnicos : • Modelo: SSV 122 • Bateria:12 V - Íons de lítio • Tensão do carregador de bateria:110 V~ - 240 V~ - Bivolt automático • Golpes por minuto (gpm):0 - 2.700/min • Comprimento do golpe:20 mm • Capacidade máxima da serra sabre:Madeira: 80 mm / Plástico: 50 mm / Metal: 2 mm • Aceleração transmitida nas mãos - braços do operador - ah:7,84 m/s² • Incerteza da aceleração transmitida nas mãos - braços do operador - k:1,5 m/s² • Massa aproximada (peso):1,4 kg', 661.34, 519.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lg-moieburtup6tc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F22894657100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
