INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200602425', 'Conjunto 3 Banqueta Allegra Alta Master Empilhavel Preta Cozinha Americana Balcão Polipropileno', 'Conjunto 3 Banqueta Allegra Alta Master Empilhavel Preta Cozinha Americana Balcão Polipropileno Modelo: Banqueta Allegra Master Com design moderno a banqueta allegra é ideal para decorar qualquer ambiente. A banqueta possui encosto vazado e descanso para os pés, prática e confortável. Ideal para deixar a sua bancada de alimentação ou bar mais moderna. Garantia de 3 meses por defeito de fabricação. Altura Total: 109 cm Altura do Chão Até o Assento: 76 cm Profundidade Interna do Assento: 40 cm Largura Interna do Assento: 36 cm Peso Máx. Recomendado: 120 kgs Peso unitário: 4,6 kgs Não Giratória Não Dobrável Empilhavel Indicações de Uso: - Não utilizar produtos químicos e abrasivos para limpeza - Limpar com pano umedecido e sabão neutro para melhor conservação - Deve ser evitada exposição dos produtos ao sol pois podem apresentar pequenas mudanças em sua coloração. Observações importantes: - Produto NÃO necessita de montagem - Pode haver alguma diferença de tonalidade entre a imagem e o produto real, por conta do tratamento de imagens e a calibração de cores do seu monitor. - Ao receber a mercadoria, o cliente deve verificar as condições da embalagem, caso haja alguma avaria não assine o comprovante de recebimento. Produto indicado para bancadas acima de 110cm, para bancadas abaixo de 110 cm compre o modelo banquetas médias com 66cm do chão ao assento. *** **NÃO USAR AS BANQUETAS ANTES DE FIXAR OS DESCANSA PÉS**', 795.8, 795.8, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxz-mctax4l8722oa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F58200602425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16918641415', 'Disco Cogumelo para Caderno Inteligente Glitter Colorido Mimo - 24 mm - 20 Unids', 'Discos para Caderno Inteligente Mimo O Disco Cogumelo para Caderno Inteligente Mimo é ideal para personalizar cadernos inteligentes de até 100 papéis de 75g/m. Ele é glitter colorido, tem 24 mm de diâmetro e vem com 20 unidades. Ele é o material ideal para você criar e personalizar planners, agendas, cadernos de anotações e muito mais! O resultado fica incrível e super diferenciado! Discos para Caderno Infinito Mimo Crafts - Linha Completa A Mimo Crafts possui uma linha completa com 22 Discos Cogumelos diferentes para você encadernar e personalizar qualquer cadeno infinito com a máxima qualidade e o melhor visual! Eles estão disponíveis em 2 tamanhos de diâmetro: 24 mm e 35 mm. Além disso, cada um desses tamanhos possui 11 opções de cores para você escolher e arrasar nas produções de artesanato: Branco, Preto, Amarelo Candy, Rosa Chiclete, Rosa Candy, Lilás, Azul Água, Glitter Colorido, Glitter Iridescente, Glitter Ouro e Transparente. Informações Técnicas: Produto: Disco Cogumelo para Caderno Inteligente Glitter Colorido Mimo - 24 mm - 20 Unids Quantidade: 20 Unidades Cor: Glitter Colorido Diâmetro: 24 mm Capacidade de Encadernação: Até 100 Papéis de 75g/m Marca: Mimo Crafts Código de Fábrica (SKU): 6372', 58.15, 58.15, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/br-11134207-820m4-mpdpy1fez66d1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F660248852%2F16918641415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298564349', 'Colchão Light D28 – Casal (138x188x14) - Ortobom', 'Colchão Light D28 Casal (138x188x14) O Colchão Light D28 Ortobom foi criado para proporcionar conforto agradável e relaxante, ideal para quem busca noites de sono leves e revigorantes. Confeccionado 100% em Espuma D28 Pró Aditivada de Alta Performance, oferece suporte para até 80 kg por pessoa. O bordado em matelassê proporciona um toque agradável, enquanto o tecido resistente possui tratamento antiácaro e antialérgico garante um ambiente de descanso mais saudável e protegido. O Colchão Light D28 Ortobom é perfeito para quem busca conforto suave, qualidade e bem-estar, tornando cada noite mais leve e relaxante.', 824.9, 725.91, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-825zu-mk9kfuw3thc0ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1537615778%2F22298564349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
