INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14827054922', 'Jogo Aneis Motor Medida Std Para Elba Fiorino Palio Premio', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Jogo Aneis Motor Medida Std TAKAO APLICAÇÃO FIAT Elba 1.5 8v Fiasa De 1992 A 1996 Fiorino 1.5 8v Fiasa 1992 A 2004 Palio 1.0 8v Fiasa De 1996 A 2003 Palio 1.5 8v Fiasa De 1996 A 2003 Palio Weekend 1.5 8v Fiasa De 1996 A 2004 Premio 1.5 8v Fiasa De 1992 A 1994 Siena 1.0 8v Fiasa De 1999 A 2002 Siena 1.5 8v Fiasa De 2002 A 2004 Strada 1.5 8v Fiasa De 1998 A 2003 Uno 1.5 8v Fiasa De De 1993 A 1996 Uno 1.5 8v Fiasa De De 1996 A 2002 Uno 1.0 8v Fiasa De 1992 A 2001 OBS: JOGO ANEIS MOTOR MEDIDA STD CODIGO DO FABRICANTE TAKAO ASFI10STD CONTEÚDO DA EMBALAGEM 01 Jogo Aneis De Motor QUALIDADE Produto Novo GARANTIA 03 Meses De Garantia NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 164.9, 164.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcm3yrjrht0ye6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2F