INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200186665', 'Depurador Fogatti Compact New Embutir Inox 60Cm Inox 220V', 'Depurador Fogatti Compact New Embutir Inox 60Cm Inox 220V Deixe sua cozinha mais moderna com o Depurador de Embutir da Fogatti. alem de pratico e bonito, possui toda a base em inox escovado e acompanha filtro de aluminio e filtro de carvao ativado. O depurador pode ser instalado de dois modos distintos, como depurador ou como exaustor. Com design diferenciado, iluminacao com lampadas de led e tres velocidades. Traga mais versatilidade para sua cozinha. Para Fogao cooktop de 4 bocas e indicado depurador de 60ou 70cm Para Fogao cooktop de 5 bocas e indicado depurador de 75, 80ou 90cm Para Fogao cooktop de 6 bocas e indicado depurador de 90cm ou mais Observacao importante, sempre observar a largura do seu fogao, para que a largura do seu depurador seja sempre um pouco maior que o fogao cooktop Instalacao apenas de Embutir Observacao, este modelo deve ser embutido em armario aereo, acima do cooktop fogao, o depurador e fixado por parafusos no proprio movel Atencao verifique a voltagem escolhida antes de finalizar sua compra Caracteristicas Funcao depurador ou exaustor Filtro interno de carvao ativado Filtro externo metalico em aluminio e lavavel Painel de funcoes Easy Touch com 3 velocidades Iluminacao com lampadas de Led Succao 550m³h Kit parafusos para instalacao no movel ja acompanham a coifa Especificacoes Tecnicas Frequencia 60Hz Ruido 65 dB Potencia do motor 140W Potencia total 142 W Velocidades 3 Potencia lampada 1 W cada uma Consumo 0,142 kWh Dimensoes Altura da base 4cm Largura 60cm Profundidade 33,5cm Peso 6,00kg Dimensoes da Caixa do motor A 25,2cm x L 23cm x P 22cm, sendo que a Caixa do motor ficara embutida no movel Garantia de Fabrica 12 meses Instalacao por conta do cliente Imagens meramente ilustrativas Atencao, o tubo sanfonado para exaustao, NAO acompanha o produto, Vendemos o tubo separadamente. O diametro de saida para o mesmo e de 127 mm de circunferencia Seu depurador ja vai pronto para utilizar na funcao depurador pois ja possui internamente filtro de carvao ativado e e necessario uma abertura no proprio movel para ventilacao do ar, favor verificar o desenho de instalacao disponivel junto com as fotos do anuncio. Caso deseje utilizar como exaustor com saida de ar externa, onde sera necessario fazer uma abertura na parede, apenas precisara comprar e instalar o tubo sanfonado de aluminio flexivel que temos disponivel para venda.', 553.61, 553.61, NULL, 'Home Appliances > Kitchen Appliances > Hoods', 'https://cf.shopee.com.br/file/sg-11134201-821ev-mggw843jb2fhdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F58200186665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
