INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298710306', 'Protetor Solar Facial Episol Antiox FPS 60 - 60mL', 'Episol Antiox FPD 60 é um protetor solar para o rosto, pescoço, colo e mãos, sendo ideal para todos os tipos de pele, possui muito alta proteção UVA e UVB. Sua formulação contém ácido hialurônico e vitamina C nanoencapsulada que proporcionam uma ação comprovada de antienvelhecimento. Reduz rugas e linhas de expressão, melhora a firmeza, maciez e elasticidade da pele, trazendo uma aparência radiante e iluminada. Oferece ação antioxidante e hidratante. Preserva o colágeno através de uma tecnologia inovadora que minimiza os danos mais profundos na pele causados pelos raios infravermelhos, devido à ação antioxidante do produto. O uso regular auxilia na prevenção do câncer de pele e de outros efeitos danosos causados pelo sol, como o envelhecimento precoce. Sua textura leve, não oleosa, possui toque seco, é fácil de aplicar e espalhar, sendo rapidamente absorvida e sem deixar a pele pegajosa. É não comedogênico (não provoca cravos), dermatologicamente e oftalmologicamente testado, desenvolvido para pele extremamente sensível à queimadura solar.', 109.9, 109.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqc2rvbkc8wc0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392870796%2F22298710306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
