INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23496467744', 'Avène Cleanance Gel Facial de Limpeza 150g', 'Cleanance Gel de limpeza purificante possui a combinação exclusiva de ativos que eliminam a oleosidade, regulam a produção do sebo e reduzem as bactérias causadoras da acne. Indicado para limpeza diária das peles sensíveis, mistas e oleosas . Cleanance Gel limpa sem ressecar a pele, tem ação antibacteriana e calmante de alta tolerância, graças ao uso dos ativos Monolaurina e C.S. de Zinco, garantindo redução de 90% da oleosidade e 82% dos cravos. Sua fórmula sem sabão respeita a sensibilidade da pele deixando a pele limpa, fresca e purificada. * RESULTADO: Deixa a pele limpa, fresca e purificada. * SUGESTÕES DE USO: 1.Umedecer a pele e aplicar o gel de manhã e à noite ou conforme recomendação dermatológica. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Avène Cleanance Gel Facial de Limpeza 150g', 98.9, 65.9, NULL, 'Beauty > Bath & Body Care > Body Oil', 'https://cf.shopee.com.br/file/sg-11134201-7qvev-ljyf3s68gc6v9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F23496467744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
