INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398659194', 'Par De Adesivos Mitsubishi Friso Lateral Para Pajero Tr4', 'IMAGENS PUBLICADAS MERAMENTE ILUSTRATIVAS Os emblemas automotivos que comercializamos, são compatíveis com cada modelo de veículo, personalizam e protegem a pintura. Os adesivos são produzidos em poliéster automotivo autocolante importado, dispensando a utilização de produtos para a fixação. Par De Adesivos Mitsubishi Friso Lateral Para Pajero Tr4 Texturizado - GenéricoCores Disponíveis: Preto, Cinza e GrafiteItens Inclusos:2 Adesivos / Fabricado em Vinil Texturizado / Dimensões: 47,4 x 2 cmObservações:Material autocolante.Resistente à chuva e raios UV.Embalagem segura para o transporte.Vinil importado. Instruções Para Aplicação:1 - Limpe e remova qualquer impureza na área de aplicação do produto.2 - Limpe as mãos e remova o protetor do liner.Procure ter o mínimo de contato com a face adesiva.3 - Centralize o produto no local da aplicação. Após esse posicionamento,pressione o produto gradativamente, sempre do centro para as bordas.Procure retirar todas as bolhas.4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,pois isso danificará o produto. OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo.Recomendamos que a aplicação seja feita por um profissional.', 25.0, 22.75, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7rasv-mb55u2thv3o1ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F22398659194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
