INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209674555', 'Desodorante Colônia Kriska Drama Feminino 100 ml', 'Kriska Drama: Uma Fragrância Ousada e FemininaKriska Drama é uma fragrância intensa e envolvente, perfeita para mulheres que gostam de marcar presença. com uma combinação de notas florais e adocicadas, este desodorante colônia reflete uma personalidade forte e dramática, ideal para ocasiões especiais.Intensidade e drama em uma fragrância floral e adocicadaKriska Drama é a fragrância que particulariza a essência da mulher forte e dramática. O equilíbrio perfeito entre a intensidade das flores e a doçura das notas de fundo, esta fragrância é ideal para mulheres que desejam expressar sua força e elegância, deixando uma verdadeira marca por onde passam.Kriska é referência na perfumaria com suas criações adocicadas, um convite para mergulhar na intensidade, alegria e graça que alicerçam o universo feminino, seu portfólio traz facetas elaboradas que se encaixam perfeitamente ao dia a dia. GOTA OLFATIVA:Família olfativa: adocicadoNotas de topo: mandarina, nectarina, maçã pink, pera-vermelha, frutas vermelhas.Notas de corpo: acorde praliné, peônia, osmanthus, jasmim,floral branco.Notas de fundo: patchouli, âmbar, cedro, sândalo, musk, favatonka, caramelo, baunilha.Ocasião: dia-a-dia, para sairDICAS DE USO:Aplique Kriska Natura nos pontos de maiorpulsação, como pescoço e pulsos, para prolongar aintensidade da fragrância e garantir uma presençamarcante.', 169.9, 169.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-820ni-mnk669y4q6ma98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58209674555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
