INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898707793', 'Lapiseira 0.5mm Super Grip Vermelha Neon H-185 com 1 unidade Pilot', 'A Lapiseira Super Grip Neon 0.5 destaca-se por seu corpo translúcido arredondado em tons neon vibrantes, oferecendo uma seleção única de cores para atender ao gosto pessoal de cada usuário. Seu grip em borracha macia proporciona uma experiência de escrita confortável e precisa, mantendo a qualidade e a praticidade da linha Super Grip. A anatomia cuidadosamente projetada da lapiseira visa proporcionar maior conforto durante o uso, enquanto o protetor de grafite retrátil em metal contribui para prevenir quebras indesejadas. Detalhes: - Ponta 0.5mm - Grip emborrachado - Com borracha na extremidade - Compatível com minas de grafite da linha PPL PILOT 0.5 de graduação 2B e HB.', 29.94, 29.94, NULL, 'Stationery > Writing & Correction > Pencils', 'https://cf.shopee.com.br/file/sg-11134201-7rdx8-mc85mxcnr3z454', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23898707793', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
