INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11206821786', 'Tinta para Tecido 6 cores 15ml 04106 Acrilex', 'Tinta p/ tecido 6 cores 15ml 04106 Acrilex Para aplicação a pincel, esponja ou carimbo em tecidos de algodão sem goma (não sintéticos). Tinta à base de resina acrílica. Não tóxica. Solúvel em água. Resistente a lavagens. Detalhes: - Para tecidos de algodão e sem goma - Super resistente à lavagens - Não tóxica CORES: Branco Amarelo Vermelho Verde Azul Preto', 27.36, 23.26, NULL, 'Stationery > Art Supplies > Water & Poster Colours', 'https://cf.shopee.com.br/file/sg-11134201-823ql-motrbzyqcl4w89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F11206821786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200023771', 'Caneta esferográfica 4 cores e 2 canetas Cristal Matte Stranger Things Bic', 'INMETRO 006991/2022 Este kit inclui a icônica Caneta 4 Cores com corpo decorado com ícones de Stranger Things, dando um ar enigmático e cheio de personalidade para essa caneta tão icônica da BIC. Além disso, o kit conta com duas canetas esferográficas Cristal Efeito Matte exclusivas nas cores vermelha (tinta azul) e preta (tinta preta), proporcionando uma escrita suave e precisa. Uma delas possui escrita azul e a outra preta, garantindo funcionalidade e sofisticação em qualquer ocasião. Detalhes: - Blister com 3 unidades; - O kit contém: 2 Canetas Esferográficas Cristal Efeito Matte (vermelha, com tinta azul e preta, com tinta preta) 1 Caneta 4 Cores com corpo decorado com ícones de Stranger Things; - Cores clássicas (vermelho, azul, preto e verde); - Escrita média com ponta de 1.0mm e largura de linha de 0.32mm;', 49.08, 41.23, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/sg-11134201-81ztx-midfcpa6h9fsfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F58200023771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19624169469', 'A Arte de Viver - Epiteto - Edição Bílingue', 'Epicteto não deixou escritos próprios, mas seus ensinamentos foram preservados por seu discípulo Flávio Arriano, que transcreveu suas palestras nos Discursos. Originalmente em oito livros, apenas quatro chegaram até nós. Suas ideias sobre virtude, resiliência e autodisciplina influenciaram A Arte de Viver, uma obra que traduz seus princípios estoicos em lições práticas para o dia a dia. DESCRIÇÃO Editora: Editora Camelot Edição: 1, 2022 Autor: Epiteto Idioma: Português/Inglês Páginas: 80 Dimensões: A 23.00 x L 15.10 x E 0.50 Encadernação: Brochura ISBN: 9786587817644', 29.9, 19.95, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/5f0228b0095ddbd5f2d29a961be7aaea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F19624169469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
