INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204587944', 'Camomila Bebê Granado Eau de Cologne - Perfume Infantil', 'Perfume infantil unissex. Camomila Bebê Granado é uma fragrância que combina toda a sutileza da flor com notas frescas. Camomila Bebê Granado estimula um sono mais tranquilo e deixa o seu filho relaxado. É Seguro para ser usado diretamente na pele de crianças de todas as idades, inclusive recém-nascidos. Uma combinação deliciosa que mantém seu pequeno perfumado o dia todo. Livre de corantes, parabenos, álcool etílico e ingredientes de origem animal. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 76.9, 76.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8260x-mka20jdz4x6t2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204587944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
