INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097369841', 'Caixa de Som Philco Extreme Ex Bass 650W PCX6700', 'Aumente o volume e sinta a batida com a Caixa de Som Philco Extreme PCX6700. Com 650W de potência e tecnologia Ex Bass, ela entrega graves intensos e um som envolvente que transforma qualquer ambiente. Ideal para festas, encontros ou momentos de lazer. Aqui, a música é protagonista. Com até 18 horas de bateria, a diversão não precisa parar. Leve sua playlist para onde quiser e aproveite cada momento sem preocupação com a Caixa de Som PCX6700. A conexão Bluetooth 5.0 garante praticidade e liberdade para tocar suas músicas favoritas. É só conectar e curtir. A experiência vai além do som com os efeitos de iluminação Flash Lights, que criam o clima perfeito para qualquer ocasião. E com a função TWS, você pode conectar duas Caixas de Som Philco Extreme PCX6700 e potencializar ainda mais o som. Tudo pensado para elevar sua experiência musical. Versátil e completa, a Caixa de Som Philco Extreme permite conectar microfone, guitarra e outros dispositivos com facilidade. Ajuste o som do seu jeito e até grave suas performances com a função REC. Com design portátil e moderno, a Caixa de Som PCX6700 acompanha você em todos os momentos, com duas opções de alça (móvel e fixa). Prepare-se para viver o som de forma intensa 650W de potência Reforço de graves Ex Bass 2 woofers de 6,5” + tweeter Bateria com duração de até 18 horas Bluetooth 5.0 com alcance de até 10 metros Função TWS (conexão entre duas caixas PCX6700) Flash Lights Entradas: USB, P2, P10 (microfone e guitarra) Ajuste independente de graves e agudos Função REC para gravação de microfone Alça para transporte + controle remoto', 799.9, 799.9, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/sg-11134201-82587-mqdf031fm3uof0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F23097369841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
