INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10642336749', 'Lixadeira manual aço 08x21cm - Castor', 'Possui uma base de borracha que auxilia na fixação e ajuste da lixa, garantindo deslizamentos equilibrados e uniformes, o que torna perfeito o resultado da sua pré-pintura. CARACTERÍSTICAS Aspectos: base revestida com borracha de alta qualidade para melhor acomodação da lixa, que é ajustada por cantoneiras de alumínio. Seu cabo com formato anatômico a deixa mais leve e fácil de manusear. Uso indicado: lixamento e preparação de superfícies para pré-pintura, seja em alvenaria, madeira ou metais. Também pode ser usada com lixas d''água, massa, madeiras ou lixas para ferro. Material da chapa: Aço. Cabo: Plástico. Medidas: 8 cm x 21 cm Código do fabricante: 230 Acompanha 1 lixa. Limpeza e Conservação: Remover a lixa utilizada e limpar a base da lixadeira. Guardar em local seco e arejado. FERRAMENTAS QUE COMPLEMENTAM Para você que precisa de produtos especiais para ajudar a pintura a render mais, além de otimizar o tempo do trabalho, a Castor tem a solução! A linha de Especiais para Pintura oferece tudo que você precisa para conseguir um resultado profissional em todos os seus trabalhos. SEGURANÇA Compre com segurança! Nossa equipe de suporte sempre estará à disposição caso tenha algum problema ou dúvida. Aguardamos seu pedido!', 35.95, 35.95, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/4b7c6197b2507bba78fe6c7098e919e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F10642336749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
