INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493747194', 'Cabo Vela VW VOYAGE 1.6 8v AP 1987 Ate 1995 - 84879 - VW02', 'Cabo Vela VW VOYAGE 1.6 8v AP 1987 Ate 1995 1.6/1.8 8v APConduz a alta tensão produzida pela bobina (ou transformador) até as velas de ignição, sem permitir fugas de corrente, garantindo uma ignição sem falhas. Reduz de interferências eletromagnéticas, que podem prejudicar o funcionamento dos componentes eletrônicos do veículo, unidades de comando eletrônico e etc. Cabos resistivos - com o resistor instalado dentro dos terminais. Cabos supressivos - com o supressor instalado dentro do próprio cabo e sua resistividade depende do seu comprimento.', 49.2, 49.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-m6uoo5snaa63f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23493747194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
