INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299241148', 'Mangueira Respiro Óleo Ford Mondeo 1997 a 2001 - 146958 - 8316', 'Mangueira Respiro Óleo Ford Mondeo 1997 a 2001 146958 8316 Ventilação Carter 2.0 Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 17.88, 17.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd55-lufi00kl479nf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20299241148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
