INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294539609', 'Energel Outdoors - 10 Unidades Morango Silvestre - BodyAction', 'Energel Outdoors é indicado para atletas de todas as modalidades esportivas que necessitam de uma boa fonte de energia para otimizar a performance durante o treinamento ou competição. Por estar na forma de gel, favorece uma absorção equilibrada, evitando o desconforto que pode ser causado pela sensação de estômago pesado. Energel Outdoors é composto por um mix completo de carboidratos em suas diferentes formas, que garantem o aporte energético ideal para antes, durante e depois das atividades físicas. Sua absorção de forma gradual e contínua retarda a fadiga precoce e é composto por um mix completo de carboidratos Adicionado de eletrólitos, mantém o equilíbrio isotônico garantindo um melhor desempenho e recuperação. - Sais minerais e eletrólitos para o equilíbrio isotônico. - Carboidratos complexos para manter os níveis ideais de glicemia (taxa de açúcar no sangue) e de glicogênio muscular, proporcionando boa performance. - Carboidratos simples e complexos mesclando a explosão necessária com a liberação de energia gradativa. - Vitaminas (importantes no combate aos radicais livres.) - Agentes redutores da fadiga muscular que minimizam a produção de ácido láctico nos músculos (responsável pela sensação de dor) - Proporciona maior intensidade nos treinamentos. - Hidrocarbonetos de largo espectro glicêmico para explosão, manutenção e duração. - Precursores de recuperação muscular. - pH próximo ao fisiológico garantindo uma rápida absorção pelo organismo. Como Tomar Para melhores resultados em provas de resistência e longa duração é indispensável consumir ENERGEL OUTDOORS 15 minutos antes das provas, fazendo reforço a cada 30 minutos de exercício. Durante provas de aventura, triátlon, ciclismo e modalidades de longa duração, distribuir doses ao longo da competição, de acordo com a orientação técnica. Ingredientes Maltodextrina, Água Tri-filtrada, Frutose, Dextrose, Concentrado Proteico do S ...', 46.5, 46.5, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-824hb-mfrfahjlwfm104', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22294539609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
