INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56301136553', 'Parachoque Traseiro Palio Fire 2001 2002 2003 2004 Texturizado', 'Código do produto: 6172 É um item indispensável para manter o design, originalidade e segurança de seu veículo. Possui material resistente, composto em plástico da mais alta qualidade texturizado com acabamento impecável sem falar no padrão de fabricação igual aos originais que mantem um alinhamento perfeito em seu veículo. Compatível com: Fiat - Palio Fire 2001 - Palio Fire 2002 - Palio Fire 2003 - Palio Fire 2004 Especificações Técnicas - Parachoque central - Texturizado - Material em Plástico ATENÇÃO O valor anunciado referente a Unidade mais o frete por conta do comprador. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 390.67, 390.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-821gh-mgwxke88gutp87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F56301136553', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
