INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10585919460', 'Escova Dental Oral-B Purification Gold Collection 4 Unidades', 'Escova Dental Oral-B Purification Gold Collection 4 Unidades A escova de dentes Oral-B é o complemento ideal para sua família. Ela possui uma cabeça compacta que ajuda a remover a placa que incomoda mesmo em áreas de difícil acesso. Possui cerdas extra macias com minerais de carbono que o ajudarão a limpar gradualmente seus dentes porque sua tecnologia ULTRATHIN ajuda a branquear suavemente seus dentes, além de ter um cabo ergonômico que o ajudará a ter melhor controle ao escovar. Para uma melhor experiência, recomendamos complementar sua rotina de escovação com os produtos que a Oral-B tem para você. • Cerdas extra macias com minerais de carvão • Tecnologia ultrathin que branqueia delicadamente os dentes • Cabeça compacta para remover placas até nas áreas de difícil alcance • Cabo ergonômico para um melhor manuseio * Compre produtos Oral B', 53.89, 50.11, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/de32ea3aeb491749c94d9dd6cf7e96d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F10585919460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
