INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998819263', 'Condicionador Wella Invigo Color Brilliance 1L', 'O Condicionador Wella Professionals Invigo Color Brilliance foi desenvolvido especialmente para cuidar dos cabelos coloridos. Sua fórmula hidratante, possui ativos antioxidantes que lutam contra o desbotamento da cor, e sela os fios para garantir que a coloração permaneça por muito mais tempo. Wella Professionals Invigo Color Brilliance proporciona proteção da cor por até 7 semanas, deixando seus saudáveis, protegidos do desbotamento e com a cor linda. Com perfume amadeirado cítrico floral, traz um delicioso aroma sofisticado, além de não pesar os fios. Resultado: Cabelos tratados com Ph otimizado. Garante 7 semanas de proteção e aumento do brilho da cor do cabelo quando o uso é regular. Ativos: - Caviar de Lima: possui alta concentração de vitaminas e antioxidantes, que ajudam a prolongar a vivacidade da cor e proteger. - Histidina e Vitamina E: ajuda a controlar o processo de oxidação dos fios após a coloração a fim de proteger a cor. - Moléculas Encapsuladas de Cobre: mantêm o tom vibrante. Modo de usar: Aplique no comprimento do cabelo molhado. Distribua o produto igualmente e então enxague bem. Sobre a marca: A Wella é uma das maiores empresas de cosméticos do mundo. Uma empresa especializada em produtos para cabelos, incluindo shampoos, condicionadores, alisantes, colorações e principalmente tratamentos para todos os tipos de cabelo. A Wella já está no mercado há mais de 130 anos e sempre acompanhando as tendências e investindo em tecnologia para oferecer o melhor para você.', 188.99, 188.99, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-823p7-mosd4z7de9e69e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F18998819263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
