INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693890089', 'Lente Espelho Retrovisor Convexo Metalizado Com Base Agile 2009 a 2016 Montana 2011 a 2020', 'A Kyodai Acessórios é a número 1 em variedade e agilidade no segmento automotivo. Aqui você encontra produtos selecionados com a melhor qualidade e o MELHOR custo-benefício do mercado. Tudo pensado para quem exige confiança, eficiência e resultado. PRODUTO 1ª LINHA (NÃO É ORIGINAL) VISÃO GERAL: Lente Para Espelho Retrovisor Externo Para Chevrolet Agile e Montana. Lente Convexa Com Acabamento Metalizado, Acompanha Base e Lente ** Antes de realizar a instalação da lente é necessário remover a base de fixação da lente anterior para realizar a instalação da lente nova que acompanha base de encaixe universal (4 Pinos) ** COMPATÍVEL COM: Chevrolet - Agile 2009 a 2016 Chevrolet - Montana 2011 a 2020 DETALHES DO PRODUTO: Aplicação: Retrovisor Externo Acabamento: Metalizado Modelo: Convexo Acompanha Base e Lente Compre apenas se tiver certeza da aplicação correta e, em caso de dúvidas, entre em contato antes de finalizar. A instalação deve ser feita por um profissional, pois a loja não se responsabiliza por uso inadequado ou montagem incorreta. As imagens são ilustrativas, e o uso de fotos ou vídeos da loja por terceiros não é permitido. Em caso de devolução, siga corretamente o processo dentro do prazo da plataforma e não encerre por conta própria, pois após o vencimento, os custos serão de responsabilidade do comprador.', 49.46, 45.51, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7renq-m8gi6nkh999y81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F23693890089', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
