INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18769890792', 'Cubo Mágico 3x3 Personalizado Vinci Cube Setas Cuber Brasil', 'SOBRE O PRODUTO O Vinci Cube Setas transforma o cubo mágico 3x3 em um puzzle temático, mantendo o funcionamento de um modelo tradicional. A arte é aplicada por impressão UV diretamente nas faces do cubo, sem adesivos. O modelo pode ser resolvido com métodos tradicionais de cubo 3x3, considerando a orientação visual da estampa. DESTAQUES - Tema: Setas - Personalização por impressão UV direta - Cubo 3x3 lubrificado e regulado - Impressão sem adesivos ESPECIFICAÇÕES - Fabricante: Cuber Brasil - Linha: Vinci Cube - Dimensões: 56 x 56 x 56 mm - Peso: 73 g CUIDADOS COM A IMPRESSÃO UV - Não utilizar produtos de limpeza ou álcool - Evitar materiais abrasivos, atrito excessivo e quedas - Transportar em embalagem ou proteção adequada CONTEÚDO DA EMBALAGEM - 1 cubo mágico 3x3 Vinci Cube Setas', 89.9, 89.9, NULL, 'Hobbies & Collections > Toys & Games > Rubik''s Cubes', 'https://cf.shopee.com.br/file/sg-11134201-22120-3l8hsqzjollv7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302271094%2F18769890792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11790755741', 'Kit Tratamento Capilar Skazi Shampoo E Condicionador Mandioca + Mel 01 Litro', 'KitTratamento Capilar Skazi Shampoo E Condicionador Mandioca + Mel 01 Litro Descubra a beleza natural dos seus cabelos com a linha Mandioca + Mel da Skazi Cosméticos. Desenvolvida especialmente para cabelos finos, opacos, porosos e quebradiços, esta linha é o segredo para cabelos radiantes e saudáveis. Benefícios: - PH equilibrado - Cabelo Encorpado - Brilho intenso - O mel é o ingrediente estrela desta fórmula poderosa. Rico em vitaminas e nutrientes, o mel é conhecido por sua capacidade de reter água nos fios, proporcionando uma hidratação profunda desde a raiz até as pontas. Além disso, funciona como um emoliente natural, deixando os cabelos macios, sedosos e cheios de vida. - A mandioca, por sua vez, complementa essa fórmula única, fornecendo nutrientes essenciais que fortalecem a fibra capilar, reduzindo a quebra e promovendo um crescimento saudável dos fios. Juntos, o mel e a mandioca trabalham em harmonia para restaurar a saúde e a vitalidade dos seus cabelos, deixando-os mais fortes, brilhantes e resistentes. - Compre Direto da Fabrica - Parabenos FREE - Livre de crueldade Animal Experimente a linha Mandioca + Mel da Skazi Cosméticos e descubra o poder da natureza para transformar seus cabelos. Informações Necessárias Envio diário! Pedidos confirmados até as 14h são postados no mesmo dia útil. Produto cuidadosamente embalado para chegar até você com total segurança. Compra Segura Com Garantia Shopee 📦⚡ ENVIO RÁPIDO APÓS CONFIRMAÇÃO DE PAGAMENTO ⚡📦', 49.9, 46.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/243cbd130e27228699e8a48bcb6a26d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F725026030%2F11790755741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
