INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898055204', 'Super Gummy Creatina Sabor Amora (60 gomas)', 'CREATINA MONOHIDRATADA Suplemento que otimiza o desempenho físico, fornecendo a quantidade ideal de nutrientes para o corpo. NOVA FÓRMULA Mais saborosa e menos arenosa. Fórmula que contém apenas o essencial, evitando aditivos desnecessários. SABOR DELICIOSO Super Gummy Amora Silvestre, apresenta o equilíbrio perfeito entre o adocicado e o cítrico da fruta. Perfeito para quem busca um sabor natural de fruta! PRATICIDADE Fácil de incluir na sua rotina. Consuma 3 gummies por dia, antes ou após os treinos, acompanhados de água para otimizar a absorção e manter a hidratação. DESEMPENHO FÍSICO A creatina aumenta a energia disponível nos músculos durante exercícios intensos e curtos. QUALIDADE DE VIDA Facilita exercícios e mantém força e resistência, melhorando mobilidade, metabolismo e recuperação, o que beneficia a saúde física geral.', 159.9, 122.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7rfh1-m3cj0j55ztlpc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811938613%2F23898055204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
