INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993842896', 'Kit 2 Sabonete Líquido Íntimo Dermacyd Femina 200ml', 'Sabonete Líquido Íntimo Dermacyd Femina 200ml Sensação de proteção e frescor o dia inteiro, todos os dias. Para ficar protegida e tranquila 24 horas, você conta com o sabonete íntimo Dermacyd pro•bio. Frescor e proteção por até 24 horas. Diferentemente dos sabonetes comuns ou bactericidas, o novo Dermacyd pro•bio tem pH similar ao da região íntima, que limpa sem agredir, mantendo as defesas naturais, prevenindo possíveis odores e trazendo sensação de frescor e proteção por até 24 horas. Modo de Uso: No banho, agite o produto, coloque uma pequena quantidade na palma da mão e aplique na região íntima externa. Em seguida, enxague bem para que não fique nenhum resíduo do produto.', 53.98, 53.98, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-8258o-mqmst00oeyvic9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23993842896', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
