INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43106287907', 'Mochila De Costas Stitch Escolar Infantil Laptop 45x31cm Luxcel', 'Mochila Escolar Infantil Stitch Luxcel com Bolso para Notebook 24L Azul Original A Mochila de Costas Stitch é perfeita para quem busca praticidade, estilo e conforto no dia a dia escolar! Com design moderno e estampas exclusivas do personagem Stitch da Disney, ela une funcionalidade e muita personalidade. Com amplo espaço interno, a mochila conta com compartimento principal espaçoso, bolso frontal com detalhe em paetê, dois bolsos laterais em mesh para garrafas e um compartimento acolchoado para notebook. Além disso, possui puxadores e chaveiro personalizados, garantindo mais charme e praticidade. Ideal para escola, passeios ou viagens curtas, essa mochila oferece conforto ao transportar graças às alças ajustáveis e acolchoadas. Destaques do Produto: - Produto original licenciado Disney - Design exclusivo do personagem Stitch - Compartimento interno acolchoado para notebook - 3 compartimentos no total - Bolso frontal com detalhe em paetê - Bolsos laterais em mesh para garrafinhas - Alças de ombro ajustáveis e acolchoadas - Alça de mão reforçada - Puxadores e chaveiro personalizados - Logo emborrachado na parte frontal - Estilo ideal para escola, lazer ou viagens Especificações Técnicas: Dimensões: 45 cm (A) x 31 cm (L) x 15 cm (P) Capacidade aproximada: 24 litros Peso: Aproximadamente 500 g Material: 100% Poliéster Forro: 100% Poliéster Importador: Luxcel / Maxlog Produto original licenciado Leve todo o encanto do Stitch com você para a escola ou onde quiser! Um modelo resistente, funcional e cheio de estilo.', 299.0, 199.0, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-7ra2b-mbgsi8hpu1p6e5', 'https://shope.ee/an_redir?origin_l