INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693902465', 'Fonte Carregador Automotivo 150a Usina Smart Bat Meter Bivolt Carregador de Bateria 12v', 'A fonte USINA foi criada com o principal objetivo de alimentar o sistema de som do carro sem deixar suas baterias descarregarem, mesmo com o som tocando por várias horas. Pode ser utilizada também como fonte e alimentação direta, alimentando toca-cd, módulos de potência. Especificações: • Tensão de Entrada: Bivolt Automático • AC 127Vca: 100 @ 140Vca • AC 220Vca: 170 @ 250Vca • Consumo 127Vca: 33A (máximo) • Consumo 220Vca: 17A (máximo) • Tensão de Saída: 12V @ 14,4Vcc (+-1%) • Corrente de Saída: 150A @ 12,5Vcc (+-5%)* • Potência de Saída: 2000 Watts (máxima)** • Rendimento: 85% • Potência de entrada (V.A): 3000V.A • Potência de Entrada: 2400 Watts (máxima)** • Cabo de Entrada: 3x2,5mm² - 2P+T • Proteção de Entrada: Disjuntor 32A • Cabo de Saída: 35mm² • Extensão Recomendada: 4mm² (máx 30 metros) Dimensões: (CxLxA): 313mmX195mmX76mm*** • Altura: 7,6 cm • Largua: 19,5 cm • Comprimento: 31,3 cm • Peso: 2,900 Kg', 760.0, 697.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Battery Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mccgbut5gesg03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411081274%2F23693902465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57058027226', '100 Envelopes (700 Figurinhas) Copa do Mundo 2026 - Oficial Panini', 'Copa do Mundo 2026 - Contém 100 Envelopes (700 Figurinhas) Este Kit contém:100 envelopes - cada envelope contém 7 figurinhas. Os envelopes são lacrados e as figurinhas são aleatórias e sortidas Prepare-se para viver a maior Copa do Mundo de todos os tempos! A Coleção Oficial Panini FIFA World Cup 2026T chegou para registrar cada capítulo dessa jornada histórica. Pela primeira vez com 48 seleções e disputada em três países - Canadá, México e Estados Unidos -, esta é a maior coleção já produzida na história dos mundiais! São 112 páginas repletas de adrenalina e 980 figurinhas para colecionar, incluindo figurinhas especiais com efeito metalizado, estádios, cidades-sede e os craques que prometem brilhar nos gramados. Cada envelope agora vem com 7 figurinhas, garantindo ainda mais emoção a cada abertura. Comece agora sua coleção, convoque os amigos para as trocas e complete o guia definitivo do maior espetáculo da Terra! Seja você um colecionador veterano ou um iniciante, a Coleção da Copa 2026 é o seu passaporte para o evento esportivo mais assistido do planeta. Não fique de fora dessa tradição! Tipo de Produto: Figurinhas Segmentos: Colecionáveis, Colecionáveis - Esportes Marcas: Panini Data de Lançamento: Maio/2026 Idioma: Português Condição: Novo/Lacrado', 760.86, 675.0, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/br-11134207-820l5-mmi39hhdlypyda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F57058027226', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49953384375', 'Mangá - Yona - A Princesa do Alvorecer - BIG - Vol. 10 - por Mizuho Kusanagi - Editora JBC', 'Yona - A Princesa do Alvorecer - BIG - Vol. 10 Yona e os quatro dragões continuam a sua viagem pelo País de Kouka, mas os perigos tornam-se cada vez maiores...Após montarem acampamento, Shin-Ah acaba encontrando uma pedra misteriosa que parece libertar um espírito antigo. Logo depois, o dragão azul começa a agir de maneira muito estranha, e Yona e os outros do grupo precisam trabalhar juntos para salvar o seu amigo!Neste volume de Yona - A Princesa do Alvorecer, também temos a volta de Lili, a filha do líder da Tribo da Água, e suas preocupações para cuidar do povo do Reino de Kouka continuam. Yona e seus amigos decidem ajudá-la em sua missão, porém a investigação pela origem da crise da droga nadai revela planos ainda mais nefastos... Autor(es): Mizuho Kusanagi ISBN: 9788545715665, 978-85-457-1566-5 Check-List: Fevereiro/2026 Editora: JBC Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 24/02/2026 Idioma: Português Condição: Novo/Lacrado', 69.9, 69.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/br-11134207-820lh-mn4kcpetfsoxd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F49953384375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
