INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999558360', 'Alicate Sata Corte Diagonal 6P Isolado', 'Características Principais: Marca: SATA Modelo: Corte Diagonal Segmento: Alicate Material: Aço Cromo-Vanádio (Cr-V) Comprimento: 20,50 cm Largura: 9,00 cm Altura: 0,21 cm Peso: 0,21 kg Capacidade de corte: Arame mole até 2,5 mm, Arame duro até 1,6 mm Informações adicionais: Ideal para corte de fios na manutenção elétrica industrial, eletrônica e automotiva. Articulação suave e cabo ergonômico para conforto durante o uso. Utilizar conforme normas NBR 9699 e NR10 para trabalho em instalações elétricas energizadas. Manusear com cuidado para evitar danos físicos. Armazenar em local seco e protegido da umidade. Limpar o cabo em PVC regularmente para manter a higiene e funcionalidade. Fornecedor: APEX TOOL GROUP IND.E COM.LTDA', 55.26, 55.26, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824he-mpibl21ecxsc6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F19999558360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19797980483', 'Cervejeira Metalfrio VN25TP 264 Litros Beer Maxx 250 | Inox', 'Características Principais do Produto:_x000D_ Alimentação: Disponível em 110V ou 220V_x000D_ Marca: Metalfrio_x000D_ Modelo: VN25TP_x000D_ Cor: Inox _x000D_ Altura: 158,5 cm_x000D_ Largura: 52,5 cm_x000D_ Comprimento: 72,6 cm_x000D_ Potência: 285W_x000D_ Frequência: 60Hz _x000D_ Capacidade Total líquida: 228 Litros_x000D_ Selo Inmetro_x000D_ Tipo de Selo Inmetro: Segurança_x000D_ _x000D_ Características Adicionais:_x000D_ Ideal para: Varandas, terraços gourmet, área de lazer, casas de praia e casas de campo._x000D_ Sistema de refrigeração subzero._x000D_ Display Interativo_x000D_ Design Sofisticado_x000D_ Display digital_x000D_ Puxador ergonômico_x000D_ Alta capacidade_x000D_ Desempenho Profissional_x000D_ Faixa de Temperatura Ampliada 2º a -6º_x000D_ Fluxo de ar contínuo, para resfriamento rápido e uniforme de todas as bebidas._x000D_ Função Eco Mode: Apaga as luzes e otimiza o uso do sistema de refrigeração, garantindo o baixo consumo de energia._x000D_ Iluminação interna: Com lâmpada LED melhor visibilidade e destaque dos produtos, durabilidade e economia de energia._x000D_ Prateleiras reguláveis_x000D_ Tanque Termoformado_x000D_ _x000D_ Capacidade:_x000D_ Capacidade Bruta: 264 litros _x000D_ Capacidade Líquida: 228 litros_x000D_ _x000D_ Capacidade de Armazenamento:_x000D_ 216 Latas 350 ml_x000D_ 108 Garrafas 355 ml_x000D_ 75 Garrafas 600 ml_x000D_ _x000D_ Prateleiras: 3 (2 reguláveis + 1 grade de fundo)_x000D_ _x000D_ Dimensões Externas:_x000D_ Altura: 158,5 cm _x000D_ Largura: 52,5 cm_x000D_ Profundidade: 72,6 cm_x000D_ Peso Líquido: 63,65 kg_x000D_ _x000D_ Dimensões Internas:_x000D_ Altura: 114,1 cm_x000D_ Largura: 44,6 cm_x000D_ Profundidade: 52,0 cm_x000D_ _x000D_ Altura Embalado: 162,6 cm_x