INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27188734236', 'Centrífuga de Roupas Britânia 15kg BCR15B', 'Centrífuga de Roupas Britânia BCR15B 15kg – Cesto Inox, Timer e Baixo Consumo A Centrífuga de Roupas Britânia BCR15B é ideal para quem busca praticidade e eficiência no dia a dia. Com capacidade para até 15 kg de roupas molhadas (ou 5 kg de roupas secas), ela é perfeita para agilizar a secagem de peças grandes ou delicadas, sempre com total segurança. Com potência de 170W e baixo consumo de energia, essa centrífuga oferece alto desempenho, ajudando você a economizar tempo e reduzir o uso de varais e secadoras. O timer de até 5 minutos com desligamento automático garante comodidade e evita imprevistos. Além disso, o cesto em inox e a dupla grade de proteção proporcionam mais durabilidade e segurança no uso diário. Benefícios: Capacidade: até 15 kg de roupas molhadas e 5 kg de roupas secas Timer com desligamento automático: até 5 minutos Cesto em aço inox: resistente e durável Alta eficiência e baixo consumo de energia Abertura extragrande: facilita o uso Dupla grade de proteção: mais segurança para suas roupas Porta cordão: mais organização após o uso Sistema de segurança automático Perfeita para o dia a dia, a Centrífuga Britânia BCR15B é sua aliada na hora de cuidar das roupas de forma prática, rápida e eficiente!', 799.0, 799.0, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc9cy5hawd0gff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F576160832%2F27188734236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
