INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53358966791', 'PEDAL ABSOLUTE MTB DUAL ENCAIXE CLIP + PLATAFORMA 9/16', '🚴‍♂️ PEDAL ABSOLUTE DUAL – VERSATILIDADE E PERFORMANCE O Pedal Absolute MTB Dual Encaixe Plataforma 9/16 é ideal para quem busca versatilidade e desempenho no pedal. Com sistema dupla função, permite uso com sapatilha (clip) de um lado e plataforma tradicional do outro, oferecendo praticidade para diferentes situações. Produzido pela Absolute, referência em componentes de ciclismo. 🔧 PRINCIPAIS BENEFÍCIOS • Sistema dual (clip + plataforma) • Mais versatilidade no uso • Excelente fixação com sapatilha • Plataforma para uso comum • Ideal para MTB e urbano 📌 ESPECIFICAÇÕES TÉCNICAS Marca: Absolute Tipo: Pedal dual Sistema: Clip + plataforma Rosca: 9/16 (padrão) Material: Alumínio / aço Aplicação: MTB / urbano 🔗 COMPATIBILIDADE ✔ Bicicletas com rosca 9/16 ✔ Uso com sapatilha padrão MTB ✔ MTB, urbano e ciclismo recreativo 📦 CONTEÚDO DA EMBALAGEM • 1 Par de pedais Absolute dual ❗ INFORMAÇÕES IMPORTANTES • Produto original Absolute • Produto novo e pronta entrega • Acompanha nota fiscal ❓ FAQ – DÚVIDAS FREQUENTES Dá pra usar sem sapatilha? Sim. Possui lado plataforma. Serve em qualquer bike? Sim, com rosca 9/16. É bom para MTB? Sim. Excelente para trilhas e uso misto. Acompanha tacos? Verificar conforme o kit (pode variar). RTM BIKES', 143.74, 135.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-820m4-mn4gygz3qz9edb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102597%2F53358966791', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9473790457', 'Fita de Ginástica Rítmica Cetim Cores Lisas 6M Dicat Sports Verde Bandeira', 'Fita de Ginástica Rítmica Cetim Cores Lisas 6M Dicat Sports Fita Confeccionada em cetim, com 5 cm de largura, com ilhós em uma das extremidades para acoplar ao estilete. Cores variadas. Anúncio se refere apenas a fita. Disponível no tamanho: - 6m Disponível nas cores: - Amarela, Azul Bebê, Azul Royal, Branca, Laranja, Lilás, Pink, Rosa Bebê, Roxa, Verde bandeira, Verde Cítrico, Vermelha Recomenda-se para maior durabilidade do aparelho, sua utilização em tapete específico para prática do esporte. Fabricado em conformidade com as normas da FIG. Conteúdo da Embalagem: 1 Fita de Ginástica Rítmica Cetim Cores Lisas 6M Dicat Sports Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagens Meramente Ilustrativas.', 42.0, 42.0, NULL, 'Stationery > Gift & Wrapping > Ribbons', 'https://cf.shopee.com.br/file/edd020dbdd96acc12c58aa1b6233afc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F9473790457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898671505', 'Trava Tomada Pequena Do Modulo 0001530022', '🔌 Trava da Tomada Pequena do Módulo | Mercedes-Benz | 0001530022 🛠️ Produto Novo | Aplicação Precisa | Fixação Segura para Módulos Eletrônicos A Trava da Tomada Pequena do Módulo A0001530022, também conhecida como trava de segurança para conectores de 15 vias do Modulo MR Antigo PLD em Veiculos Mercedes-Bens Accelo ,Atego, Axor ,Actros, é uma peça fundamental para veículos da linha pesada Mercedes-Benz. Sua função é garantir a fixação estável e segura da tomada elétrica no módulo de controle eletrônico (MR), evitando desconexões e falhas de comunicação que podem comprometer o funcionamento do sistema. ⚙️ Especificações Técnicas: Código da Peça: 0001530022 Tipo de Conector: 15 vias – tomada pequena Aplicação: Módulo eletrônico (ECU) / chicote de motor Material: Plástico de engenharia de alta resistência Função: Trava de segurança para conector elétrico ✅ Aplicações Confirmadas: Compatível com diversos modelos da linha pesada Mercedes-Benz, incluindo: Acello – Todas as versões Atego – Todas as versões Axor – Todas as versões Actros – Todas as versões 1938S / 1938LS 1215C, 1318, 1718C 712C, 715, 914C, 915 🔧 Instalado nos módulos eletrônicos responsáveis pela gestão do motor, sistema de transmissão, freios eletrônicos e outros subsistemas críticos. 📦 Informações Importantes: Produto novo com garantia de 90 dias contra defeitos de fabricação Peça testada antes do envio Não nos responsabilizamos por instalação incorreta Recomendamos instalação por profissional capacitado Imagens reais do produto Enviamos para todo o Brasil 🚛 Dunga Peças – Conectando Qualidade com Segurança Aqui você encontra peças confiáveis para quem exige desempenho e durabilidade. Somos especialistas na linha pesada, e trabalhamos com peças que garantem a continuidade da sua operação, com estoque pronto para envio rápido. Dunga Peças – Qualidade que move o seu caminho.', 48.3, 48.3, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mftz2msnjapwc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1310994553%2F22898671505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
