INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498818415', 'Solução SLB91 Koube 1L Limpeza de Bicos Injetores Flex e Diesel para Cuba de Ultrassom', 'PRODUTO NOVO Você precisa limpar bicos injetores Flex e Diesel de forma profissional e eficiente? Características do Produto – Produto concentrado de uso profissional – Limpeza eficaz em bicos injetores de veículos Flex e Diesel – Uso exclusivo em cubas de ultrassom – Diluição recomendada: 100 mL para cada 1 L de água potável – Volume: 1 litro – Aparência: Líquido viscoso amarelado – pH: 7,00 – 8,00 – Densidade: 0,950 – 1,050 g/mL – Viscosidade: 45 – 55 mm/s Por que escolher este produto – Desenvolvido para limpeza profunda e segura – Alta performance na remoção de resíduos – Fabricado pela Koube, marca reconhecida em produtos automotivos – Aumenta a eficiência do sistema de injeção – Ideal para oficinas e uso profissional Dicas de Uso – Sempre dilua conforme orientação do fabricante – Utilize apenas em cubas de ultrassom – Não use em reservatórios para teste ou retro limpeza – Armazene em local seco e protegido do sol – Utilize EPIs durante a aplicação Perguntas Frequentes – Posso usar em qualquer tipo de motor? Sim, o produto é indicado para veículos Flex e Diesel. – Preciso diluir antes do uso? Sim, dilua 100 mL de SLB91 para cada 1 L de água potável. – Serve para uso doméstico? Não, é um produto de uso profissional para cubas de ultrassom. – Pode ser usado puro? Não, o uso deve ser sempre diluído para garantir segurança e eficácia. Compre agora e garanta uma limpeza profissional dos bicos injetores com a qualidade Koube.', 69.35, 69.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdg5pxf97mxd16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552175911%2F23498818415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
