INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799121905', 'Aspirador de Pó Antiácaro Com Lâmpada UV WAP Mite Cleaner UV', 'Deixe sua casa protegida contra ácaros, fungos e bactérias com o Aspirador de Pó Antiácaro WAP MITE CLEANER UV 3 em 1. Ele Vibra, Aspira e possui Luz UV! O Aspirador Portátil WAP MITE CLEANER acompanha Lâmpada com tecnologia UV-C, Luz Ultravioleta com ação Germicida, que atua inativando vírus e combatendo as bactérias das superfícies. Indicado para quem possui alergias e problemas respiratórios, este incrível aspirador antiácaro tornará qualquer ambiente, muito mais limpo! Pequeno, leve e compacto, o WAP MITE CLEANER UV possui Exclusivo sistema de vibração, que ao entrar em contato com a superfície a ser aspirada, age levantando a poeira não visível acumulada na região, fazendo com que a aspiração seja ainda mais eficiente e profunda, higienizando até 2cm de profundidade. Além disso, é equipado com filtro SS + HEPA, itens que auxiliam na prevenção de alergias, retendo ácaros e devolvendo um ar mais puro ao ambiente. Também possui Luz UV, sendo uma das limpezas mais completas e indicadas para o combate de alergias e doenças respiratórias. A Combinação perfeita entre Dupla Filtragem e LUZ UV com comprimento de onda de 253nm. Alta performance garantida em um modelo fácil de usar e transportar. Utilize o Aspirador de Pó Antiácaro WAP MITE CLEANER UV com lâmpada ultravioleta germicida para limpar sofá, tapete, carro, colchão e outros estofados com rapidez e eficiência. Limpeza superficial, nunca mais!', 739.9, 591.92, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-825am-mfyacf41tbf283', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1515185730%2F23799121905', NULL, NULL, '2026-07-2