INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11785695466', 'Violino 4/4 Vivace Mo44 Kit + Estante + Afinador Completo', 'Somos a Eletromusic Loja Especializada a mais de 10 anos no Mercado. Qual e o nosso diferencial? Buscamos sempre oferecer qualidade com excelencia por isso todos os nossos produtos sao de Fornecedores Nacionais com rigoroso controle de qualidade, possuem nota fiscal eletronica e garantia de fabrica. Voce e bem vindo para fazer parte da nossa historia. O Violino Vivace Mozart MO44 apresenta um otimo custo beneficio, sendo a escolha ideal para aqueles que procuram um violino tamanho 4/4 com um belo acabamento e sonoridade. Com uma boa definicao sonora, este violino e produzido com Tampo em Spruce Plywood e Corpo em Maple Plywood, madeiras de baixa densidade, que garantem o brilho sonoro que voce procura. O Vivace MO44 traz 4 micro afinadores para uma precisa afinacao do instrumento, e conta com arco em crina animal, um belo estojo termico com bolso frontal e breu. Com este Violino, voce tera em boas maos suas melodias e arranjos! Acabamento: Fosco Tampo: Spruce Plywood Corpo: Maple Plywood Espelho: Hardwood Braco: Maple Estandarte: Hardwood Queixeira: Hardwood Arco: Rosewood Cravelhas: Hardwood KIT 01 MO44 VIOLINO 4/4 01 ESTANTE PARTITURA (Marca conforme disponibilidade em estoque) 01 AFINADOR (Modelo e marca conforme disponibilidade em estoque)', 574.28, 574.28, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/151982ff3431c8461cc94df299a7494b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F11785695466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
