INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15694742015', 'Cozinha Completa Madesa Topazio com Armário, Balcão e Tampo - Branco', 'A Cozinha Compacta Topazio é uma cozinha pensada nos mínimos detalhes. Ela combina em ambientes modernos, vintage/retrô ou coloridos. Seu aéreo em vidro agrega beleza e sofisticação ao móvel. Contempla o tampo do balcão de pia, que pode ser removido para a colocação de uma pia com as medidas de até 120 cm x 52 cm. Já o balcão para cooktop possui 60 cm x 52 cm e segue com tampo que pode ser recortado para a colocação do cooktop. Possui rodapés fixos para uma melhor sustentação e pés com regulagem para pequenos desníveis. Medidas: - 240 cm de largura - 52 cm de profundidade no balcão e na torre e 31 cm nos aéreos - 210 cm de altura Itens inclusos: - Uma (1) torre com nichos para forno e micro-ondas, com uma (1) gaveta e duas (2) portas, sendo uma basculante - Um (1) balcão de 120 cm com duas (2) portas - Um (1) tampo de madeira branco para balcão de pia de 120 cm x 52 cm - Um (1) aéreo de 120 cm com portas deslizantes em vidro - Um (1) balcão de 60 cm com uma (1) porta e tampo - Um (1) aéreo de 60 cm com porta basculante Código do produto: G200880909 Obs.: - Imagens meramente ilustrativas. - É obrigatório fixar a torre quente na parede. - A Madesa não disponibiliza serviço de montagem. - O produto segue com manual e todas as ferragens necessárias para a instalação. A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 1669.99, 1369.55, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22110-ed8gzmdszbkv79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F15694742015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12679108081', 'Kit 10 Escovas Dental J&j Reach Access Macia Grande 40', 'O Kit contém: 10 Escovas Dental J&j Reach Access Macia Grande 40 Maior alcance para limpar as partes mais difíceis da boca. Johnson''s Access foi desenvolvida para acessar as partes mais difíceis da boca. Seu cabo angulado proporciona maior alcance e o tufo frontal de suas cerdas é ideal para limpar os dentes do fundo. Além disso, possui cabo emborrachado para maior controle durante a escovação.', 228.39, 228.39, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/d947b5eac921d5a3b0cfaa8e8b729451', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12679108081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898957085', 'CD Guns N'' Roses - The Spaghetti Incident? - Importado', 'CD Guns N'' Roses - The Spaghetti Incident? - Importado Lançado em 1993, The Spaghetti Incident? é o último álbum gravado pelo Guns N'' Roses antes da longa pausa, antecessor do Chinese Democracy. Marca também o fim da era clássica do Guns. A banda Gun''s Roses que, inicialmente, era apenas mais uma de Hard Rock, mostrou que realmente tinha talento e acabou se tornando uma das mais consagradas e influentes bandas em todo o mundo. Nas 12 faixas espetaculares desse álbum, você encontrará muita atitude. Repertório do CD: 1. Since I Don''t Have You 2. New Rose 3. Down On The Farm 4. Human Being 5. Raw Power 6. Ain''t It Fun 7. Buick Makane (Big Dumb Sex) 8. Hair Of The Dog 9. Attitude 10. Black Leather 11. You Can''t Put Your Arms Around A Memory 12.1. I Don''t Care About You 12.2. (silence) 12.3. Look At Your Game, Girl', 99.9, 74.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-81zvt-mmt9ghzxm51c06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F22898957085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
