INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41208287261', 'Extrato de Própolis Verde Alecrim 11% Extrato Sec 20ml –Alta Concentração | Imunidade Natural', 'O Extrato de Própolis Verde com Alecrim da Mel Santa Bárbara é um produto natural, altamente concentrado e ideal para fortalecer a imunidade. Produzido com própolis verde brasileira e alecrim, esse extrato possui ação antioxidante, antibacteriana e anti-inflamatória. Com 11% de extrato seco, é uma excelente alternativa para o cuidado diário da saúde de forma natural. ℹ Benefícios: ✅ Fortalece o sistema imunológico ✅ Ação antioxidante e anti-inflamatória ✅ Contém própolis verde com alecrim ✅ Extrato seco com alta concentração (11%) ✅ Prático de usar – com conta-gotas ✅ Produto natural de origem brasileira ℹ Ficha Técnica: ✅ Produto: Extrato de Própolis Verde com Alecrim ✅ Marca: Mel Santa Bárbara ✅ Conteúdo: 20ml ✅ Concentração: 11% de extrato seco ✅ Aplicação: Uso oral ou diluído ✅ Embalagem: Frasco âmbar com conta-gotas ✅ Origem: Brasil ✅ Glúten: Não contém', 25.73, 25.73, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rdwl-mc3lm4urv0ry59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F41208287261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
