INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259667194', 'Duracell AA Pilha Alcalina', 'As pilhas alcalinas AA Duracell são ideais para dispositivos de alto consumo, como brinquedos, controles remotos e consoles de jogos. Elas fornecem energia confiável e duradoura para o seu dia a dia. * 10x mais duração que as pilhas comuns de zinco-carbono. * Voltagem: 1,5V * Tamanho: Pequena Após o uso, descarte em locais apropriados.', 29.99, 29.99, NULL, 'Food & Beverages > Cooking Essentials > Cooking Paste & Kit', 'https://cf.shopee.com.br/file/sg-11134201-825ay-mqnekpnsfmkg1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554945%2F58259667194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
