INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43781077426', 'Renovador De Plásticos Internos Intense 1,5l Vonixx', '🚗✨ Bem-vindo!! Você está em uma loja especializada em soluções automotivas seguras e confiáveis. Aqui, cada detalhe é pensado para cuidar do que move você: sua família, sua segurança e seus melhores momentos na estrada. 🛡️✨ Intense Vonixx 1,5L - Renovador De Plásticos Internos O Intense Vonixx é um renovador de plásticos internos desenvolvido para restaurar, proteger e valorizar o acabamento interno do veículo. Sua fórmula com proteção UV oferece acabamento natural, toque seco e excelente durabilidade, ajudando a manter painéis e plásticos com aparência de novos por muito mais tempo. Ideal para quem busca praticidade, proteção e um visual sofisticado no interior automotivo. Afinal, painel bonito chama mais atenção que passageiro mexendo no rádio errado. 😄 🔢 Referências Compatíveis: 📌 35345 📌 2009056 📋 Informações do Produto: 🏷️ Marca: Vonixx 🧴 Tipo: Renovador de Plásticos Internos 📦 Volume: 1,5L ✅ Pronto uso 🆕 Condição: Novo 🛡️ Proteção UV ⏳ Durabilidade: Até 6 meses ⚠️ Informações adicionais: • Pode ser utilizado em painéis soft touch • Não recomendado para plásticos externos e couro 🛡️ Garantia: 90 dias ⚠️ Antes de realizar seu pedido, esclareça suas dúvidas. 🚘 Aplicações: ✔️ Painéis automotivos ✔️ Portas e acabamentos internos ✔️ Console central ✔️ Plásticos internos em geral ✔️ Laterais internas ✔️ Borrachas internas ✔️ Superfícies vinílicas ⭐ Principais Características: ✅ Renova o aspecto dos plásticos internos ✅ Acabamento natural e uniforme ✅ Toque seco após aplicação ✅ Não deixa aspecto oleoso ✅ Proteção UV contra desgaste e ressecamento ✅ Realça a aparência original das superfícies ✅ Fácil aplicação e excelente espalhamento ✅ Alto rendimento na embalagem de 1,5L ✅ Ideal para manutenção automotiva profissional e doméstica 🛠️ Modo de Usar: 1️⃣ Certifique-se de que a superfície esteja limpa e seca. 2️⃣ Aplique uma pequena quantidade do produto utilizando um aplicador de microfibra. 3️⃣ Espalhe uniformemente até o completo preenchimento da peça. 4️⃣ Se necessário, repita o processo. 5️⃣ Remova excesso ou manchas com uma toalha de microfibra limpa e seca. 🛒 Adquira agora o Intense Vonixx 1,5L em uma de nossas Lojas Oficiais: 🏪 Camillo Parts | Genuine Automotive | Edumac Parts ✔️ Produto original ✔️ Qualidade garantida ✔️ Envio rápido e seguro ⚖️ Aviso Legal: 🚫 Proibido copiar, alterar ou utilizar imagens e conteúdo deste anúncio. 📜 Material protegido pela Lei 9.610/98.', 112.9, 80.16, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-823oo-moiaogwffl6z5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349667948%2F43781077426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261147007', 'Kit Lavadora de Alta Pressão LAV1300 1200W com Snow Foam 400ml e Acessórios Vonder', 'A Lavadora de Alta Pressão LAV1300 Vonder 1200W é ideal para limpezas domésticas, oferecendo alta eficiência na remoção de sujeiras em pisos, carros, motos, bicicletas e diversas superfícies. Com bico ajustável, permite alternar entre jato leque e concentrado para melhor desempenho em cada tipo de limpeza. O kit ainda acompanha o aplicador Snow Foam 400ml, que gera espuma densa e facilita a limpeza automotiva com mais praticidade e eficiência. Diferenciais: • Lavadora de alta pressão 1200W ideal para uso doméstico • Bico ajustável com jato leque e concentrado • Kit completo com acessórios para uso imediato • Mangueira de alta pressão de 3 metros • Pistola com gatilho ergonômico • Conector engate rápido com filtro lavável • Acompanha Snow Foam 400ml para espuma intensa • Ideal para lavagem de carros, motos, pisos e muros • Maior eficiência na remoção de sujeiras difíceis • Sistema prático e fácil de usar Detalhes Técnicos: **Lavadora de Alta Pressão LAV1300** Modelo: LAV1300 Potência: 1200W Tipo: Lavadora de alta pressão Uso indicado: Doméstico Mangueira: 3 metros de alta pressão Bico: Ajustável (jato leque e concentrado) Pistola: Com gatilho Conector: Engate rápido 1/2" com filtro lavável **Aplicador Snow Foam** Capacidade: 400 ml Material: Plástico resistente Regulagem de espuma: Sim Tipo: Canhão de espuma (foam lance) Indicação: Limpeza automotiva Conteúdo da Embalagem: 1 Lavadora de Alta Pressão Vonder LAV1300 1200W 1 Aplicador Snow Foam Vonder 400ml 1 Acessório para detergente 1 Mangueira de alta pressão 3m 1 Lança com bico ajustável 1 Pistola com gatilho 1 Conector engate rápido 1/2" com filtro interno lavável', 499.45, 419.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820l7-mqm8ofcod1c111', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F58261147007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
