INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599043618', 'Robô Aspirador Philco 3 em 1 Função MOP PAS26P', 'Com design moderno, tecnologia inovadora e alto desempenho, o Robô Aspirador Philco 3 em 1 Função MOP PAS26P oferece máxima praticidade para manter seus ambientes sempre limpos, sem nenhum esforço! Equipado com um reservatório de água de 200ml e um reservatório de pó de 610ml, ele passa pano em todo o ambiente e acumula grande quantidade de sujeira, reduzindo a necessidade de esvaziamento constante. Além disso, sua função MOP permite aspirar e passar pano seco ou úmido, garantindo uma limpeza completa e eficaz. Para facilitar ainda mais o seu dia a dia, o Robô Aspirador Philco conta com sensores antiqueda e anticolisão, desviando automaticamente de obstáculos e evitando quedas em escadas ou desníveis. E quando a bateria estiver próxima do fim, ele retorna sozinho para a base de carregamento, garantindo total autonomia e praticidade. Com até 110 minutos de autonomia, ele limpa diversos cômodos em uma única carga. A tecnologia avançada do filtro HEPA retém até 99,5% de ácaros, poeira e micropartículas, proporcionando um ambiente mais saudável para toda a família. Além disso, o modelo 3 em 1 varre, aspira e passa pano, tornando-se um aliado indispensável para quem busca mais conforto e eficiência na rotina de limpeza. O Aspirador PAS26P oferece diferentes modos de limpeza, como aleatório, cantos, espiral e aspiração guiada pelo controle remoto, garantindo um desempenho superior em qualquer ambiente. Suas duas escovas laterais removem sujeiras de difícil acesso, alcançando cantos e bordas com eficiência. Escolha o Robô Aspirador Philco 3 em 1 Função MOP PAS26P e transforme sua rotina de limpeza! Possui 2 modos de operação: aspirador para resíduos secos e pano úmido* (mop) 2 escovas laterais para limpeza Possui controle remoto independente Sensor antiqueda Sensor de obstáculos Reservatório para sólidos com 610ml Reservatório para líquidos com 200ml 110min de autonomia Tempo de carregamento de 5 horas Base para carregamento automático Bateria de íons de lítio Possui modos de limpeza aleatório, cantos, espiral e aspiração guiada pelo controle.', 929.9, 929.9, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-824iu-mpdzqruopzi9ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F18599043618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899871067', 'Etiqueta escolar Reino Encantado com 12 unidades Pimaco', 'As etiquetas escolares Reino Encantado da Pimaco são ideais para organizar e identificar materiais escolares, como cadernos, livros, estojos e objetos pessoais, com um toque de magia e delicadeza. Cada cartela vem com 12 unidades, prontas para uso imediato. Fabricadas em material adesivo resistente, fixam-se facilmente em superfícies lisas como papel, plástico e vidro, garantindo boa durabilidade. O design temático Reino Encantado, com ilustrações coloridas e encantadoras, torna a organização dos pertences uma tarefa prática e divertida para as crianças. Especificações Técnicas: Produto: Etiqueta escolar Tema: Reino Encantado Quantidade: 12 unidades Material: Adesivo resistente Aplicações: Cadernos, livros, estojos, objetos pessoais e escolares Uso: Organização, identificação e personalização de materiais escolares Organização prática e um toque de encanto para o dia a dia escolar.', 18.66, 14.93, NULL, 'Stationery > Notebooks & Papers > Labels & Stickers', 'https://cf.shopee.com.br/file/sg-11134201-8261x-mlqkfbn0b1fmaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350081126%2F20899871067', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
