INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792954246', 'Sérum Ácido Hialurônico 1,5% 30ml Dermachem', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - DESCRIÇÃO: Sérum Hyaluronic 1,5% DERMACHEM LABORATORY foi desenvolvido com blend de ativos superconcentrados de ácido hialurônico de alta permeabilidade e eficácia, além de ativos dessensibilizantes e que promovem em conjunto luminosidade e uniformidade de todos os tipos de pele, principalmente as mais sensíveis. Pele hidratada e radiante sempre! - - - - - MODO DE USO: ROTINA DIURNA - Pela manhã, limpe bem o rosto com o sabonete de limpeza da Linha DERMACHEM. Aplique de 1-2 gotas do Sérum no rosto, pescoço e colo. Faça uma massagem com movimentos circulares para melhor absorção do produto. Aplique o protetor solar de sua preferência. Ao longo do dia repita esse cuidado. ROTINA NOTURNA -Á noite, com a pele limpa e seca aplique novamente o Sérum. Utilize o Sérum 3x ao dia. Não enxaguar. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 30.0, 17.9, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/br-11134207-820lv-moquocf4bfnqfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F22792954246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
