INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193218652', 'Conjunto Feminino Drapeado Up Glam Planet Girls Rosa', 'O Conjunto Feminino Drapeado Up Glam é a escolha perfeita para mulheres que valorizam o estilo e o conforto. Com um design moderno e sofisticado, ele é confeccionado em tecido de alta qualidade, proporcionando um caimento impecável e um toque suave na pele. DETALHES QUE VOCÊ VAI AMAR SABER: O drapeado valoriza as curvas do corpo e confere um ar de elegância a qualquer look. Use-o para um jantar especial, um encontro com as amigas ou até mesmo no trabalho, e arrase em qualquer ocasião!', 199.99, 199.99, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-824ic-me6tscjetvr943', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F675392510%2F23193218652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23095865595', 'Poltrona Para Sala Recepção Pés Palito Suede Cores', 'Dimensões da poltrona: Altura:82 cm Largura:60 cm Profundidade:55 cm Peso do produto: 9 kg O produto suporta até 100 kg Especificações técnicas: Estrutura: madeira de eucalipto; Encosto: espuma d-23; Modelo dos pés: palito; Material dos pés: madeira de eucalipto; Quantidade de pés: 4 Grampos de aço galvanizados; Chapas de metal para encaixe dos pés; Montagem: somente rosquear os pés; Garantia: 3 meses contra defeitos de fábrica; Acabamento perfeito certificado pelos profissionais. Informações adicionais: - os pés são enviados desencaixados e separados, para evitar que danifique o produto no transporte. Eles podem ser encaixados e rosqueados de forma muito simples no produto. Pedimos que os mesmos sejam rosqueados até o fim para que o produto não apresente defeito. - instruções de limpeza: utilizar um pano levemente umedecido com água, seguido de pano seco. Evitar exposição ao sol, para que não sofra alterações na cor do tecido. Não limpar com escovas ou produtos abrasivos. - a montagem será de total responsabilidade do comprador. - as imagens são meramente ilustrativas, nenhum tipo de objeto contido na imagem além do produto descrito no anúncio acompanhará o produto. - a cor do produto pode sofrer variações, devido ao lote do tecido e/ou a resolução do monitor e/ou iluminação do ambiente. - para futuras compras, não garantimos a mesma tonalidade de cor, pois existe variação a cada lote do fabricante do tecido. - fique atento ao nosso prazo de fabricação, pois todos os nossos produtos são feitos sob encomenda. - confira as dimensões e as descrições do produto para certificar-se de que passará normalmente por supostos elevadores, portas, escadas e/ou corredores de sua residência.', 199.9, 199.9, NULL, 'Home & 