INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252703102', 'Vult Cabelos Choque de Reconstrução Máscara 250g', 'Vult Cabelos Choque de Reconstrução Máscara veio para reparar os fios e combater a quebra logo no primeiro uso. Possui Bioqueratina e Niacinamida, que reduzem os danos e protegem das agressões externas. ¹ Ainda traz a Tecnologia HD, que torna o cuidado mais inteligente e intensivo. E tem uma fragrância Floral Frutal que é puro conforto! Veja o que mais ela tem: - pH 4,0 - 5,0; - Ideal para a etapa de reconstrução do cronograma; - Livre de sal, parabenos e petrolatos; - Vegano; - Pode usar em low e no poo. Nenhum produto Vult é testado em animais, ou seja, este item possui selo Cruelty Free. ¹ Teste de força e de intensidade de áreas danificadas (Microscopia de Fluorescência) em mechas após a primeira aplicação da linha em comparação a mechas tratadas com shampoo sem agentes condicionantes. Resultados obtidos a partir do uso completo da linha Vult Choque de reconstrução. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 29.99, 29.99, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mj4ggwibzxmt6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1675526045%2F58252703102', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
