INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202337872', 'Coqueteleira Profissional 350ml Inox Com Filtro Resistente', 'Coqueteleira Profissional 350ML em Inox com Filtro Resistente Prepare drinks com praticidade, eficiência e um acabamento profissional. Esta coqueteleira de 350ml é ideal tanto para uso doméstico quanto profissional, perfeita para bares, restaurantes, eventos ou para quem gosta de fazer drinks em casa. Fabricada em aço inox de alta qualidade, oferece alta durabilidade, resistência à corrosão e fácil higienização. Seu filtro resistente integrado garante bebidas bem coadas, sem resíduos de gelo ou frutas, proporcionando um resultado mais uniforme e sofisticado. O tamanho de 350ml é ideal para o preparo de doses individuais ou duplas, permitindo agitar com segurança e conforto. O fechamento firme evita vazamentos durante o uso, tornando o preparo mais prático e seguro. PRINCIPAIS CARACTERÍSTICAS: -Capacidade de 350ml -Material: Aço inox resistente -Filtro interno reforçado -Design profissional e funcional -Fácil de limpar e altamente durável Ideal para preparar caipirinhas, drinks clássicos, coquetéis e bebidas diversas com muito mais qualidade e estilo. Produto essencial para quem busca eficiência e um excelente custo-benefício.', 49.99, 27.99, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-81zvq-mikhn4rp6zuq16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1333507062%2F58202337872', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097067071', 'Comédias para se ler na escola', 'A dobradinha não podia ser melhor. De um lado, as histórias de um mestre do humor. Do outro, o olhar perspicaz de uma das mais talentosas escritoras do país, especialista em literatura para jovens. Ana Maria Machado, leitora de carteirinha de Luis Fernando Verissimo, preparou uma seleção de crônicas capaz de despertar nos estudantes o prazer e a paixão pela leitura. O resultado pode ser conferido em Comédias para se ler na escola, uma rara e feliz combinação de talentos, indispensável para a sala de aula. A seleção de textos permite ao leitor mergulhar no universo das histórias e personagens de Verissimo e conhecer os múltiplos recursos deste artesão das letras. A habilidade para os exercícios de linguagem ou de estilo pode ser vista em crônicas como "Palavreado", "Jargão", "O ator" e "Siglas". A competência para desenvolver as comédias de erro está presente em "O Homem Trocado", "Suflê de Chuchu" e "Sozinhos". A mestria para criar pequenas fábulas, com moral não explícita, aparece em "A Novata", "Hábito Nacional" e "Pode Acontecer". A aptidão para resgatar memórias é a marca de "Adolescência", "A Bola" e "História Estranha". E, por fim, o dom para abordagens originais de temas recorrentes revela-se em "Da Timidez", "Fobias" e "ABC".', 73.48, 73.48, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rbkv-ln63j1wbcc8q2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23097067071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
