INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099198584', 'Eudora Siàge Cauterização dos Lisos Shampoo 250ml', 'O shampoo Siàge Cauterização dos Lisos é um produto para limpar os cabelos sem ressecar. Sua fórmula conta com com a exclusiva biotecnologia Affinité 4D, proteína hidrolisada, para absorção rápida e eficiente do tratamento e Amino10-Effex, um blend de 10 aminoácidos que fortalece as fibras capilares e combate o afinamento das pontas. * RESULTADO: Hidratação; Nutrição * SUGESTÕES DE USO: Aplique sobre os cabelos úmidos, massageando suavemente o couro cabeludo até formar espuma. 2. Enxágue abundantemente. 3. Reaplique se necessário. * ITENS INCLUSOS: 1 Eudora Siàge Cauterização dos Lisos Shampoo 250ml', 52.9, 52.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rbk1-lo6yy5rc4pjx9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F19099198584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193220200', 'Cozinha Ambiente Kit Cassia 8 Portas Damasco Off White - Poquema', 'Cozinha Ambiente Kit Cassia 8 Portas Damasco Off White - Poquema Cozinha Kit Cassia 8 Portas Damasco Off White - Poquema Na hora de comprar os móveis para sua cozinha, conte com a gente! Apresentamos a Cozinha Cássia ideal para ambientes compactos, conta com 8 portas para maior praticidade no seu dia a dia, amplo espaço interno para melhor organizar seus utensílios e um lindo design proporcionando modernidade ao ambiente, desenvolvido pela Poquema com materiais de excelentes qualidades pensando em você que não tem muito espaço mas que não abre mão da organização. Não deixe de aproveitar, confira mais sobre esse lindo móvel abaixo! Características Técnicas: - Desenvolvido 100% em MDP - Acabamento em pintura U.V na cor Damasco Off White - Possui 08 Portas - Dobradiças metálicas - 01 Gaveta - Corrediças metálicas - Puxadores na cor Prata Fosco - Divisões - Kit 04 pés plástico - Lindo design Dimensões: Altura: 172 cm Largura: 106 cm Profundidade: 31 cm Obs: Não realizamos a montagem, porém acompanha manual de instruções.', 303.05, 303.05, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-lyp9jyduz1bodb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22193220200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894180374', 'Par de hastes com dobradiças para Notebook Asus X512F', 'Par de hastes com dobradiças para Notebook Asus X512F Estas hastes com dobradiças para notebook são a solução para seus problemas com o movimento de abrir e fechar a tampa do seu computador. O produto é novo, feito em material resistente e a embalagem contém duas unidades para montagem e fixação nos lados direito e esquerdo da carcaça do notebook. Com as hastes e dobradiças novas você soluciona alguns problemas: - Dificuldade ao abrir e/ou fechar o notebook - Tampa do notebook está frouxa e/ou mole - Barulho ao abrir e/ou fechar a tampa - Elevação ou rachadura na carcaça do notebook Atenção! É importante verificar a compatibilidade das hastes e dobradiças com o seu modelo de notebook para que sejam exatamente as peças que seu computador precisa. Garantia: 3 meses de garantia contra defeitos de fabricação Referência: HT059-AS-0002', 184.9, 62.11, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mq644mzcymtpd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22894180374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
