INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297600179', 'Kit 4 Bonecos Vinil Turma do Chaves 12 Cm Chapolin, Girafales, Chiquinha e Bruxa 71 Original', 'O Kit 4 Bonecos Vinil Turma do Chaves é perfeito para colecionadores e fãs da série, reunindo personagens icônicos em versões detalhadas e com aproximadamente 12 cm de altura. Com articulação na cabeça e braços, os bonecos permitem brincadeiras criativas, além de serem ideais para presentear ou completar sua coleção. CARACTERÍSTICAS: - Marca: Líder Brinquedos - Modelo: 3579 - Linha: Bonecos de Vinil - Coleção: Turma do Chaves - Personagens: Chapolin, Professor Girafales, Chiquinha, Bruxa do 71 - Altura aproximada: 12 cm cada - Material: Vinil - Articulação: Sim (cabeça e braços) - Produto oficial: Licenciado - Indicação: Crianças e colecionadores - Conteúdo da caixa: 01 Caixa com 4 Bonecos (Chapolin, Professor Girafales, Chiquinha e Bruxa do 71) - INMETRO: CE‑BRI/IQB 00275552668', 129.99, 129.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwvfolg4ckhreb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F23297600179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292962925', 'Bandeja Balança Dianteira Lado Direito Nakata March Versa', 'Este anúncio contém: 1 (uma) Bandeja dianteira direita (passageiro) original da marca Nakata. Especificações: Possui Buchas: Sim; Possui Pivô: Sim. Código do Fabricante: NBJ6003DP; Código Universal: 7890903080802; Conversão: BJC29016M/NS21032C/545001HK0B. Atenção: Fotos reais do produto, compre apenas tendo certeza que serve para seu veículo. Aplicável nos seguintes veículos: Montadora: Nissan; Veículo: March; Ano de fabricação: 01-2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019 a 12-2020. Montadora: Nissan; Veículo: Versa; Ano de fabricação: 01-2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019 a 12-2020. Sobre o Produto: A bandeja (ou braço oscilante) é um componente do sistema de suspensão dos veículos. Ela trabalha com os demais componentes de suspensão, ligando a roda ao chassi do veículo. Sua construção é formada por sua estrutura estampada, forjada ou fundida, buchas, pivô e mancais. Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, e com garantia; 2 - Produto a pronta entrega; 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma Auto Peças fundada em 1980, atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidor final. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 332.74, 312.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu7ym18psyg04b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F519603839%2F23292962925', NULL, NULL, '2026-07-28T02:11:31.708458+