INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694696973', 'Kit Troca de Óleo e Filtros 5w40 Sintético Volkswagen Saveiro 1.6 8V EA111', 'Conteúdo da embalagem: 04 litros Óleo Motor 5w40 API SN Volkswagen Maxi Performance 5W40 100% Sintético 01 Filtro de óleo - TECFIL PSL560 01 Filtro de combustível - GI50/7 TECFIL 01 Filtro de ar - ART6098 TECFIL 01 Filtro de ar condicionado ACP303 01 Limpa ar condicionado BR BRASIL ( Selecione a Fragrância na variação) 01 Anel vedação Carter 01 Etiqueta controle Óleo **Para garantir agilidade no envio, os filtros podem ser enviados de marcas como TECFIL, WEGA, MAHLE ou MANN, todas com qualidade reconhecida no mercado.** **Produtos à pronta entrega ** Aplicação: VOLKSWAGEN Gol 1.6 8V 104cv 2008 À 2015 G5 / G6 / MI / Power / Imotion / Rallye - mecânicoTotal Flex Saveiro 1.6 8V 104cv 2014 Em diante (Rock in Rio/Surf/Startline/Trendline)Flex Saveiro 1.6 8V 2008 À 2014 G5 Flex Polo 1.6 8V 104cv 2007 À 2013 (G4 e G5 - BlueMotion / Imotion / Sportline) - automático / manualTotal Flex Voyage1.6 8V 105cv VHT 2008 À 2015 (CL/ Trendline/ Confortline/ Highline/ I-motion)Flex Obs: Motor EA111 Indicado para veículos Volkswagen Total Flex que utilizam as especificações VW 508 88 e VW 509 99 (Conforme o manual do proprietário). MAXI PERFORMANCE foi formulado para proporcionar o máximo desempenho e proteção ao seu motor Volkswagen. A sua formulação REO - Robust Engine Oil possui aditivos específicos para ser uma proteção adicional contra combustíveis de qualidade variável e assegurar sempre a máxima lubrificação do motor Pode ser usado em motores Flex, Gasolina, Etanol, GNV e diesel. Especificações: API SN ACEA A3/B4 VW 509 99 VW 508 8 Autostilemotors.', 345.3, 345.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh2a9x0kju9z7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954990910%2F22694696973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54308349540', 'Chinelo Kenner Summer Tropical Masculino', 'A Kenner Summer Vôlei deixa o comum de lado e te faz experimentar o mundo do conforto Kenner. Sua tira em gel garante o toque macio na pele, a palmilha texturizada traz a sensação de conforto, e o solado com ondas tridimensionais, proporciona a aderência ideal para pisos molhados. Peça já!', 129.9, 99.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-820lh-mmrfzz4nxs78a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F54308349540', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20057877537', 'Balcão Cozinha com Rodapé Gabinete Pia 120 cm 2 Portas 1 Gaveta Veneza GB Multimóveis MP2117 Preto', 'O Balcão Cozinha com Rodapé Gabinete Pia 120 cm 2 Portas 1 Gaveta Veneza Multimóveis tem um excelente custo benefício e um amplo espaço interno. Produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), rodapés, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. O balcão possui tampo removível (compatível com pia de 120 cm). Para deixar sua cozinha mais bonita e organizada, possui compartimento especial para utensílios mais altos. Conteúdo da Embalagem: 1 (um) balcão com tampo 120cm 1 (um) kit com rodapés Dimensões do produto montado: Altura: 84cm | Largura: 120cm | Profundidade: 53cm (balcão com tampo) *Você pode consultar as medidas internas na imagem técnica do produto. Disponível nas cores: Branco - Preto Acetinado Texturizado *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 709.9, 549.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvfz-li0gli1ww43e5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F20057877537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14295227832', 'Cozinha Completa de Canto Veneza GB Multimóveis MP2051 com Armário e Balcão Preta', 'A Cozinha Completa de Canto Veneza Multimóveis MP2051 com Armário e Balcão tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos de canto podem ser montados dos dois lados (esquerdo ou direito), conforme a sua preferência. Esta cozinha conta, ainda, com balcão com tampo removível (compatível com pia de 120 cm), com 1 gaveta e 2 portas. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. Para deixar sua cozinha mais bonita e organizada, possui vidro reflecta e compartimento especial para utensílios mais altos. Conteúdo da Embalagem: 1 (um) paneleiro 62cm 1 (um) armário aéreo de canto 90cm 1 (um) armário aéreo com portas de vidro 120cm 1 (um) armário aéreo 70cm 1 (um) balcão com tampo de canto 90cm 1 (um) balcão com tampo 120cm Dimensões do produto montado: Altura: 203cm | Largura: 152 x 242cm | Profundidade: 32cm (aéreos) - 53cm (balcão com tampo e paneleiro) *Você pode consultar as medidas internas na imagem técnica do produto. Disponível nas cores: Branco - Preto Acetinado Texturizado *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem..', 2659.9, 1869.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvdz-li0gh8tn5wvu70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F14295227832', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
