INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257496990', 'Tapete Automotivo Universal Impermeável Emborrachado Jogo com 4 Peças Ruchi', 'O Tapete Automotivo Universal Ruchi foi desenvolvido para oferecer proteção eficiente ao interior do veículo, unindo resistência, funcionalidade e fácil manutenção. Produzido em Borracha, proporciona maior durabilidade e proteção contra sujeira e umidade no uso diário. O conjunto é composto por quatro peças, sendo dois tapetes dianteiros e dois traseiros, com formato universal que se adapta a diversos modelos de veículos. O material é anti-alérgico, sem odor e ecologicamente correto, contribuindo para um ambiente interno mais limpo e confortável. Características do produto: Jogo com 4 peças (2 dianteiros e 2 traseiros) Aplicação universal Material: Borracha Anti-alérgico Sem odor Alta durabilidade Produto 100% ecológico Marca: Ruchi Modelo: Tapete Automotivo Universal Validade: Indeterminada Produto fabricado no Brasil', 29.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/br-11134207-820lt-mmsyocf0gdflf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946086188%2F58257496990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493630182', 'BICO INJETOR FIAT FREEMONT 2.4 16V GASOLINA 04891577AC', 'Descrição: BICO INJETOR ORIGINAL - 04891577AC Marca: ORIGINAIS Conteúdo da Embalagem: 1 Bico Injetor Código Original: 04891577AC ATENÇÃO*IMPORTANTE confirmar a numeração antes da compra, e se a mesma bate com o CÓDIGO ORIGINAL do carro. Código igual peça correta, caso seja diferente entre em contato conosco para confirmação do mesmo e para tirar suas dúvidas. >>> Peça Nova de Excelente Qualidade com Garantia e Nota Fiscal >>> Caso seu veículo não esteja na lista de compatibilidade, verifique a própria descrição do anúncio, imagens, código e lista de veículos contidos na descrição. Se a dúvida ainda persistir, utilize o campo de perguntas para esclarecimentos -- Tem alguma dúvida? Podemos ajudar! -- Confira as informações abaixo: • Todos os produtos anunciados estão disponíveis em estoque e são enviados com extrema rapidez. • O frete pode ser simulado antes de efetuar a compra, basta clicar em “ver custos de envio”. • A NF é emitida automaticamente com os mesmos dados cadastrados em sua conta do Mercado Livre (CPF ou CNPJ). • Verifique o endereço de entrega cadastrado e atualize caso necessário. • Confirme se a peça é correta para o seu modelo de veículo. • Para peças automotivas, recomendamos a instalação por um profissional especializado. --Caso possua outras dúvidas, entre em contato. Equipe WS Parts.Aplicação: FIAT FREEMONT EMOTION 2.4 L 16V DOHC L4 (2011 a 2016) FREEMONT PRECISION 2.4 L 16V DOHC L4 (2011 a 2016)', 218.9, 218.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7ra3u-m4zkjp50rdkw6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297577243%2F23493630182', NULL, NULL, '202