INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392585988', 'Tapete Higiênico Pet P/ Cães Ultra Espaço De Bicho Lavanda 80x60 90unid', 'O Tapete Higiênico Pet Like Ultra Espaço de Bicho Lavanda é um excelente tapete compacto, indicado para cães de todos os portes. Com tecnologia Floc Gel americana e sistema de absorção japonesa. Simples e prático, é elaborado com matérias que garantem uma super absorção. Com barreiras nas laterais de proteção, evita que o xixi vaze. O seu design garante uma melhor distribuição do xixi. Super leve e fino, o produto ainda é capaz de neutralizar o mau cheiro, conservando um ambiente higienizado. Além disso o tapete possui um atrativo canino, facilitando o treinamento do seu pet seja ele filhote ou adulto. Características: - Indicado para cães; - Com atrativo canino; - Melhor distribuição do xixi; - Barreiras que evitam o vazamento; - Com fita adesiva, melhor fixação; Cuidados: - Colocar o tapete distante da alimentação do cão; - Manter em local arejado e longe do alcance de crianças; - Caso o cão rasgue o tapete, jogue-o no lixo; - Produto descartável. Composição: - Filme de polietileno, tecido não-tecido, celulose, papel, polímero super absorvente, atrativo. Especificações: - Marca: Petlike - Acessórios para pets - Modelo: Ultra Pads - Tapete higiênico - Unidades na embalagem: 90 un - Medidas: 80x60cm', 390.0, 179.9, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnglhkg3smoc1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F823664460%2F23392585988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098193848', 'Pistola Pressão Co2 Gamo Red Alert Rd-1911 4,5mm', 'A Pistola de Pressão CO2 Gamo Red Alert RD-1911 4,5mm é uma opção robusta e leve, feita de polímero de alta densidade com cano em metal, garantindo durabilidade e resistência. Com uma empunhadura texturizada e uma trava de segurança manual, ela proporciona conforto e segurança ao usuário. Com velocidade média de 130 m/s, sua performance é otimizada para precisão, enquanto seu magazine acomoda até 20 esferas de aço, permitindo maior continuidade em suas práticas. Ideal para prática de tiro esportivo, a Red Alert RD-1911 apresenta funcionamento semi-automático e mira fixa, tornando-a uma escolha eficiente para iniciantes e usuários experientes. Seu design de 22 cm de comprimento facilita o manuseio em diversas situações. Ficha Técnica - Marca: Gamo. - Modelo: Red Alert RD-1911. - Ação: CO2 12g. - Funcionamento: Semi Automático. - Ação: Simples. - Calibre: 4,5 mm. - Peso: 450g. - Munição: Esferas de aço. - Miras: Fixas. - Capacidade do Magazine: 20 esferas de aço. - Comprimento total: 22 cm. - Velocidade Aproximada: 130 m/s. - Material: Polímero com metal. - Blowback: Não. - Trava de Segurança: Manual. - Itens que acompanham: 01 Pistola Red Alert RD-1911 4,5mm, 01 Magazine 20 esferas de aço, 01 chave para ajustes, Nota Fiscal e Manual. - Observação: Não necessita de CR para compra.', 1279.9, 1279.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/9e40db7bb71648cbdb2583abd4977449', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F22098193848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
