INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598319948', 'Fresh Whey - 450g Pistache e Chocolate Branco - Dux Nutrition', 'O nosso FreshWhey é uma linha única de proteínas, feita com ingredientes naturais, frutas e nuts de verdade, que proporcionam sabores reais que surpreendem. Combina 3 tipos de proteína do soro de leite - concentrada, isolada e hidrolisada - trazendo o melhor de cada uma delas: Sabor, pureza e qualidade. São 20 g de proteína por porção em uma fórmula clean label, com aromas e adoçantes naturais, e um perfil de aminoácidos completo. Como Tomar Misture 1 scoop de Fresh Whey com água, misture e aproveite! FreshWhey pode ser consumido a qualquer hora do dia, como um lanche saudável e saboroso, podendo ser misturado em preparações doces ou salgadas, quentes ou frias. Ingredientes Proteína de soro do leite concentrada, proteína de soro do leite isolada, creme de pistache em pó, pasta de pistache liofilizada em pó, proteína de soro do leite hidrolisada, espirulina, aromatizantes naturais, edulcorantes glicosídeos de esteviol de Stevia rebaudiana Bertoni e taumatina e corante curcumina. ALÉRGICOS: CONTÉM DERIVADOS DE SOJA, LEITE E PISTACHES. PODE CONTER TRIGO, AVEIA, AMENDOIM, AMÊNDOA, AVELÃS, CASTANHA- DE-CAJU E CASTANHA-DO-PARÁ. CONTÉM LACTOSE. CONTÉM GLÚTEN. ...', 251.35, 251.35, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-824h0-mfonajlvpslla4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F19598319948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46363527395', 'Cola Instantânea Líquida MP93 100g Mundial Prime', 'Cola Instantânea Líquida MP93 100g Mundial Prime CARACTERÍSTICAS: - Garantia: 3 Meses - Viscosidade: Média, ideal para preenchimento de pequenas folgas e superfícies irregulares. - Tempo de Secagem: Rápida, fixando em 5 segundos (média) a 12 segundos, dependendo do material. - Aplicações: Adere borracha, plástico, compostos de borracha (EPDM, nitrílica, Neoprene, EVA, Viton), metais, madeira e cerâmica. - Embalagem: 100g (industrial/grande volume), com bico antientupimento que evita desperdícios. - Resistência: Alta performance de adesão. - Restrições: Não recomendado para polietileno (PE), polipropileno (PP), polímeros fluorados, superfícies siliconadas, tecidos ou EPS. INSTRUÇÕES DE USO: - Para melhores resultados, limpe e seque bem as superfícies (livre de óleo e sujeira). - Aplique uma fina camada de adesivo, pressione as partes entre 2 a 12 segundos e limpe o bico após o uso.', 19.9, 18.7, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/sg-11134201-82591-mqc82vldclcffa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F46363527395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
