INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18098883022', 'Esmalte Dailus Jelly Pop Bubble Gum', 'Lembra do pirulito com chiclete? Um verdadeiro clássico! O esmalte BUBBLE GUM, da coleção limitada JELLY POP, representa exatamente ele. Um tom de roxo imperdível que além de translúcido, pra garantir o acabamento “gelatina” do momento, vem com uma surpresa: Tem efeito holográfico! Use sozinho ou por cima de outras cores da coleção pra turbinar ainda mais suas nails! Demais, né? O esmalte ainda possui brilho intenso, secagem rápida, longa duração e tudo isso com uma fórmula vegana e cruelty-free. Bora garantir o seu? Aproveite pra conhecer também os outros 4 tons da coleção! Por que amamos? - Top coat holográfico com efeito gelatina - Multiuso: Sozinho ou por cima de outros esmaltes - Brilho intenso - Secagem rápida - Longa duração - Fórmula vegana - Cruelty-free', 37.48, 37.48, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkuxiiblxwdkce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18098883022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
