INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998885795', 'Esmalte Risqué Cremoso Bali', 'Toda a linha de esmaltes Risqué Cremoso, além de apresentar textura única e cores marcantes, acompanha as tendências da moda, possibilitando diversas composições de looks e maximizando a beleza da sua maquiagem e acessórios. Com secagem rápida, use a sua imaginação e crie lindas nails art que farão sucesso aonde quer que você vá. Com fórmula especial, livre de componentes que costumam causar alergias, o Esmalte Risqué é perfeito para os cuidados diários. Apaixone-se pela cor, presencie a longa duração e viva a beleza de suas unhas de forma única com os Esmaltes Risqué. Modo de usar: Com as unhas limpas, aplique uma ou duas camadas do esmalte, de acordo com a intensidade desejada.', 16.63, 16.63, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7r98o-lkuy9zf6iixze4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F19998885795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204491144', 'Pegador em Madeira de Faia Beachwood Cuisinart ® - CTG-BEW-TNG', 'Pegador em Madeira de Faia Beachwood Cuisinart ® - CTG-BEW-TNG Natural, elegante e funcional, o Pegador em Madeira de Faia Cuisinart® Beachwood CTG-BEW-TNG é ideal para quem busca praticidade, cuidado com os utensílios e um toque sustentável na cozinha. Produzido em madeira de faia premium, ele combina firmeza e suavidade, garantindo conforto no manuseio sem soltar farpas ou resíduos durante o preparo dos alimentos. Com acabamento em óleo natural não tóxico, o pegador é totalmente seguro para uso em panelas com revestimento antiaderente, preservando a superfície e evitando riscos. Sua estrutura permite segurar e virar alimentos com precisão, sendo ideal para o preparo e o serviço de diversos tipos de receitas. Além da funcionalidade e do design naturalmente elegante, o Pegador Beachwood é uma escolha consciente: fabricado em madeira de faia, é naturalmente biodegradável ao final da vida útil. Integrante da linha premium GreenGourmet®, ele alia desempenho, estética e responsabilidade ambiental para o dia a dia na cozinha. Principais Benefícios - Madeira de faia premium: elegante, firme e macia - Seguro para antiaderentes: não risca nem danifica as superfícies - Acabamento em óleo natural: proteção não tóxica e segura - Não solta farpas ou resíduos: uso confiável ao cozinhar - Biodegradável: opção sustentável e consciente - Linha GreenGourmet®: utensílios premium eco-friendly Ficha Técnica Marca: Cuisinart ® Modelo: Pegador em Madeira de Faia Beachwood Cuisinart ® - CTG-BEW-TNG Material: Madeira de faia Acabamento: Óleo natural protetor Compatibilidade: Panelas antiaderentes Sustentabilidade: Biodegradável Dimensões: 7.62 X 36.83 X 6.36 cm Peso: 100g Garantia: 3 Meses Imagens meramente ilustrativas.', 65.9, 39.92, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-82630-mk858fx8nrph42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507016444%2F58204491144', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
