INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16889351847', 'Aditivo para radiador concentrado 1l delphi rl10008', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia. CARACTERÍSTICAS: Produto novo de ótima qualidade Composição: ecológico (base de monoetilenoglicol com tecnologia orgânica) Tipo: concentrado (precisa ser diluído em água) ESPECIFICAÇÕES TÉCNICAS: O líquido de arrefecimento deverá ser substituído a cada 5 anos ou 150.000 km ou completado o quanto antes se necessário. o trabalho de substituição do líquido de arrefecimento deverá ser executado por uma concessionária ou oficina autorizada Chevrolet, pois é necessário eliminar todo ar do sistema durante o reabastecimento. MODO DE USO: 1 - Siga as recomendações do fabricante do veículo ao adicionar aditivo para radiadores. 2 - Drenar completamente e lavar com água limpa o sistema de arrefecimento do veículo. 3 - Adicionar 50% de água desmineralizada para 50% do aditivo concentrado. 4 - Em uso, verificar o nível periodicamente e completar com solução arrefecedora Delphi pronto para uso, se necessário. 5 - Armazenar em local fechado, seco e sob temperatura ambiente. IMPORTANTE: Garantia de 3 meses Não nos responsabilizamos pelo mau uso do produto Atende / supera normas nbr 15.297, nbr 13.075, astm d-3306, astm d-4340.', 47.0, 47.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-22110-3gr37e87bnjv09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F16889351847', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
