INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093615834', 'Kit 2 Porta Temperos Saleiro E Condimentos Bambu Natural Gourmet', 'Kit com 2 Saleiros esférico de bambu. Por ter um estilo diferente dos saleiros e pimenteiros comuns, ele pode ser confundido como peça decorativa - e também pode ser, né? Formato esférico, ele encaixa direitinho na palma da mão na hora de temperar a comida. Seu formato é todo redondo, mas na parte debaixo tem uma base com dupla função - deixar seu saleiro em pé e também repor o que tem dentro. O bambu é um material resistente e com propriedades que evitam a proliferação de bactérias. Material: Bambu Medidas: Altura - 6,2cm Largura - 7cm Comprimento - 7cm Lavar com detergente neutro, esponja macia, guardar em local seco e arejado. Garantia do fornecedor de 90 dias contra defeitos de fabricação.', 73.49, 73.49, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3whvcmdsgd70d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F775496126%2F22093615834', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
