INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898951167', 'Depilador descartável Soleil Rosa e Roxo 2 unidades Bic', 'O Depilador BIC Soleil foi desenvolvido visando proporcionar uma depilação rente e suave. Suas 3 lâminas promovem um excelente desempenho. Sua cabeça móvel desliza facilmente pelos contornos da mulher. Conta com fita lubrificante com Leite de Coco. Possui cabo ergonômico decorado, desenvolvido especialmente para as mulheres. Acredite na sua própria beleza com os Depiladores BIC Soleil. Aproveite! Detalhes: - 2 unidades nas cores rosa e roxo; - 3 lâminas em cada cartucho com cabeça móvel; - Cabo ergonômico decorado; - Dupla fita lubrificante com Leite de Coco.', 25.97, 21.9, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-820no-mnwwe3u3mt5046', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616550287%2F22898951167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
