INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792666138', 'Canelito Penalty Storm T 33-38', 'O Meião Canelito Penalty Storm é uma peça essencial para atletas que buscam desempenho e conforto durante suas atividades esportivas. Com uma composição de alta qualidade, proporciona durabilidade, elasticidade e conforto. É uma Meião sem a parte dos pés, podendo escolher sua Meia Penalty favorita. Benefícios: Conforto aos pés. Ajuste perfeito. Respirável. Alguns diferenciais técnicos : O Meião Canelito Penalty Storm combina com estilo, tecnologia e funcionalidade, sendo a escolha ideal para atletas que valorizam qualidade e desempenho em seus treinos e competições.', 23.9, 23.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7rd5b-lu41osz1tshv28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F23792666138', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
