INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298024798', 'Sandália Vizzano Básica Salto Bloco Médio Feminina', 'Com designs super atualizados, as sandálias conquistam os looks mais frescos com charme e praticidade. E para quem não abre mão de um bom salto, a idéia é apostar naqueles com um mood mais comfy, como os saltos blocos, pois deixam o visual elegante na medida certa, sem abrir mão do conforto. A Vizzano traz em seus modelos versátilidade para suas composições. Elaboradas em material resistente, possuem bico arredondado, palmilha macia, salto médio, solado emborrachado e acabamento prespontado. Must have absoluto, não pode ficar de fora da sua fashion list. Garanta já a sua!', 149.9, 129.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134201-820lz-mqxdl5ze8qv838', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F21298024798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
