INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998185311', 'Tênis Fila Winner Clay Masculino - Preto e Laranja', 'O Winner Clay é a escolha ideal para atletas intermediários que buscam melhorar a performance nas quadras de saibro. Com cabedal em micromesh e engineering mesh, oferece resistência e respirabilidade. A tecnologia CAGE, com placa antitorção no mediopé e retropé, garante estabilidade e segurança. A entressola em EVA proporciona conforto, enquanto a sola EVER-GRIP assegura tração superior e durabilidade, garantindo desempenho ideal nas partidas. Garanta já o seu!', 679.9, 599.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rath-ma37s4xyfu02f9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F20998185311', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
