INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22121204906', 'Desinchá Apple Cider + Desinchá Laranja Moro', '- 01 Desinchá Apple Cider (30 sachês); - 01 Desinchá Laranja Moro (30 sachês); Modo de Preparo: Desinchá Apple Cider e Desinchá Laranja Moro Esquente 200 ml de água. Antes de começar a ferver, já pode desligar.Depois basta me colocar dentro da água quente, tampar e esperar por 5 minutinhos. E pronto!Prefere me tomar gelado? É só fazer tudo igualzinho e, no final, adicionar gelo.Fica bom por aproximadamente 24 horas, guardando na geladeira.', 142.8, 142.8, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/sg-11134201-23020-ne8br9xdv1mv90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811938613%2F22121204906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197377179', 'Batedeira Philco PBT450P Crome Case 550W', 'Dê atenção aos detalhes de cada receita! A Batedeira Philco PBT450P Crome Case 550W possui Case Acoplada é perfeita para preparar pequenas receitas. Ideal para preparar claras em neve, bolos pudins, mousses, chantili, maionese, variados cremes de forma rápida e eficiente. Conta com alça ergonômica e confortável para o uso no dia a dia. • 4 velocidades + Turbo; • Potência de 550W • Unidade motora usada como portátil; • Botão ejetor dos batedores; • Batedeira Portátil; • Acompanha 1 par de batedores para massas leves; • Case acoplada para guardar os batedores quando não estiver em uso; • Decoração em aço inox;', 229.9, 109.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-7rcf1-lsbsne5925876b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F22197377179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
