INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207010976', 'Pasta Diasin 14g Homeopatia Diarreia Aguda Cães/gatos', 'A LeluPets nasceu de uma paixão e dedicação de aproximadamente 20 anos de experiência nessa área tão incrível. Desde o início de nossa história, já são mais de 100 mil clientes atendidos. Estamos aqui determinados em fazer a diferença, democratizando e simplificando o cuidado com o seu pet para oferecer a melhor experiência para você e seu amiguinho. Mantemos nossas orelhas em pé, atentos às novidades do mundo pet para trazê-las até você. Nós somos apaixonados por pets! O seu pet é também da nossa família! Diasin 14g Homeopatia Pasta Diarreia Aguda Cães e Gatos Diasin um composto homeopático em pasta, indicado para cães e gatos que apresentam deficiências intestinais, onde estejam expondo sintomas de diarreia, também diarreia aguda. Na maioria dos casos se tem solução em apenas uma aplicação. Com fácil aplicação, sem riscos de intoxicação e/ou contaminação. Expõem formula gerada de matéria prima natural, um composto com ausência total de toxidez. - Indicado para cães e gatos; - homeopático; - No tratamento de diarreias; - Formula natural; - Pasta; - Fácil aplicação - Atente-se à Diasin bula e/ou informações da embalagem; - Consulte um médico veterinário de sua confiança para o uso apropriado deste produto; - Disponível em seringa dosadora com 14 gramas', 142.9, 142.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-8261f-mlwc3qg5zfus69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760624219%2F58207010976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
