INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205164026', 'Kit Farol Milha Neblina Gol Voyage G6 2013 2014 2015 Promoçã', 'Kit De Farol Milha Gol G6 + 4 Brindes! Kit Contém: - 2 Faróis De Milha - 2 Molduras - 1 Chicote - 1 Relê - 1 Botão Modelo Original - 2 Lâmpadas Halógena ( Comum - Brinde ) - 2 Pingões T10 - 8 Leds Para Lanterna/Meia Luz ( Brinde ) *Imagens ilustrativas Do Produto Sobre O Kit: - Botão: Modelo Original - Encaixe De Lâmpada: H11 - Suporta Xênon E Led? Sim! O KIT SUPORTA TANTO O XÊNON QUANTO O SUPER LED E TAMBÉM SUPORTA LÂMPADAS DE ATÉ 55w Sobre Os Faróis: - Material Da Lente: Acrilíco - Lente: Lisa - Material Da Carcaça: Plástico - Marca: Suits - Modelo E Ano Do Veículo: Gol / Voyage / Saveiro G6 No Que O Kit De Farol De Milha Ajuda? O Kit De Farol De Milha É Muito Importante Para Seu Veículo! Além De Deixa-lo Mais Completo, Os Faróis Lhe Auxiliam Em Ruas, Estradas E Rodovias! Seu Objetivo É Clarear O Máximo Para Frente E Para Os Lados, Podendo Lhe Fornecer Uma Maior Visibilidade Na Via, Garantindo A Sua Segurança! *Garanta Já Seu Kit E Aproveite O Nosso Preço Promocional! Obs: A Garantia Do Kit De Farol De Milha É De 3 Meses Contra Qualquer Tipo De Problema De Fabricação, As Lâmpadas Halógeneas ( Comum ) + Os Pingões São Brindes E Não Acompanham Garantia! Aguardamos A Sua Compra! Será Um Prazer Tê-Lo Como Nosso Cliente! Qualquer Dúvida Estamos A Disposição! Boas Compras! Garantia do vendedor: 3 meses Garantia de fábrica: 90 dias', 229.99, 229.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-81zw2-mn07eanszv2d69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1310462644%2F58205164026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297635213', 'Power Tire 500ml Protelim - Pretinho Selante Pneus Resistencia Agua', 'PRODUTO COM NOTA FISCAL E PRONTA ENTREGA !!! O Power Tire Protelim 500ml é um revitalizador de pneus de alto rendimento, desenvolvido para promover proteção e brilho intenso nas laterais dos pneus. Sua fórmula balanceada possui alto poder de fixação, formando um filme protetor que deixa o pneu com aspecto de novo, além de resistente à água e à sujeira. Conta com agentes condicionantes que hidratam e evitam o ressecamento precoce da borracha, prolongando a vida útil dos pneus. Pode ser utilizado também em plásticos e borrachas externas, promovendo acabamento de showroom. Benefícios: - Alto brilho com efeito molhado - Protege contra ressecamento e rachaduras - Alta resistência à água e sujeira - Hidratante para pneus e borrachas - Fácil aplicação e alto rendimento Diluição: Pronto uso. Modo de Uso: - Limpe bem o pneu antes da aplicação. - Aplique uma pequena quantidade do Power Tire em um aplicador de espuma. - Espalhe uniformemente sobre toda a lateral do pneu. - Aguarde a secagem. Caso queira, pode aplicar uma segunda camada para maior brilho. IMPORTANTE: Não aplicar em motos. Utilize Equipamento de Proteção Individual (EPIs). __________________________________________________ Em caso de dúvidas entre em contato conosco através do campo de perguntas.', 84.9, 73.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Brighteners', 'https://cf.shopee.com.br/file/br-11134207-820mb-mp1evpg0zr4020', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F999160347%2F20297635213', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9632613264', 'Spell 2.0 Brilho e Proteção instantâneos 500ML Vonixx', 'Spell é um selante sem toque, à base de sílica, que age imediato ao ser aplicado. Promove hidrorrepelência imediata, criando um filme de brilho e proteção UVA e UVB na pintura plástico, vidros e rodas. MODO DE USO: Após a lavagem e com a pintura ainda molhada, pulverize o produto de maneira uniforme em no máximo 1/4 do veículo. Utilize um jato de alta pressão para ativar o produto e promover hidrorrepelência imediata. Continue o processo até a finalizar todo o veículo. Seque o veículo por completo com ajuda de um compressor de ar ou soprador empurrando a água de cima para baixo. Obs: Caso deseje, utilize uma toalha de secagem. IMPORTANTE: Produto não pode ser usado em superfícies secas.', 35.9, 35.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvypqmlk1kfp20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410524587%2F9632613264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299907863', 'Kit 4 Calotas Central Pro Star Weld Kr C09 Alumínio Copo Grande', 'Kit 4 Calotas Centrais KRMAI Pro Star C09 Alumínio Polido Copo Grande + Adesivos Resinados – Qualidade e Estilo Garantidos Principais Benefícios: ✅ Design Exclusivo Pro Star KR C09 Desenvolvido sob medida para rodas KRMAI modelo C09 (copo grande), garantindo encaixe perfeito e visual original. ✅ Alumínio Polido Premium Material leve, resistente e com brilho intenso, que valoriza ainda mais o conjunto das rodas. ✅ Adesivos Resinados de Alta Qualidade Adesivos duráveis, resistentes ao tempo e com acabamento de alto brilho. ✅ Fácil Instalação Encaixe preciso e seguro, sem necessidade de adaptações. Características Técnicas: - Marca: KRMAI – KR Wheels - Modelo: Pro Star C09 (Copo Grande) - Material: Alumínio Polido - Acabamento: Polido com adesivo resinado -Compatibilidade: Somente para rodas KRMAI modelo C09 - Quantidade: 4 calotas + 4 adesivos resinados ✅ Medidas: -Diâmetro: 63 mm -Altura: 97 mm -Aba de encaixe: 72 mm Itens Inclusos no Pacote: ✅ 4 Calotas Centrais KRMAI Pro Star C09 em Alumínio Polido ✅ 4 Adesivos Resinados de alta qualidade Sobre a CERIOLLI SHOP: ✅ Mais de 16 anos de experiência no mercado automotivo ✅ Envio rápido e seguro com embalagem reforçada ✅ Atendimento técnico personalizado ✅ Compra com nota fiscal e garantia total', 289.25, 289.25, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Wheel Cover', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfwo4diylh5108', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F19299907863', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45311390660', 'Mini Nobreak Portátil 36W Para Roteador Wi-Fi E Modem Com USB', 'No-Break Multifuncional Portátil 36W USB Proteção Sobrecarga Garanta a segurança e o funcionamento ininterrupto dos seus dispositivos eletrônicos com o Nobreak. Ideal para residências, escritórios e ambientes profissionais, este nobreak oferece proteção contra quedas de energia, surtos e picos, assegurando que seus equipamentos funcionem corretamente e evitando perdas de dados e danos hardware. Ele protege contra surtos, picos, variações de tensão, sobrecargas e curtos-circuitos, prolongando a vida útil dos seus equipamentos eletrônicos. Além de facilita o monitoramento do status da bateria, da carga e das condições de operação através de indicadores LED claros e intuitivos, ele também ocupa pouco espaço e possui um design que se adapta facilmente a qualquer ambiente. Dimensões: 16x10x3cm (CxLxA) Peso: 0,400g Principais Recursos: - Tipo de bateria: Lítio integrada - Garantia de confiabilidade: Controlador de microprocessador - Funcionalidade: Inicialização automática - Recurso de segurança: Proteção contra sobrecarga de curto-circuito - Interruptor de desligamento: Manual - Recurso de indicação: LEDs indicadores de funcionamento - Seletor de tensão: 15V/24V DC - Recurso adicional: Carregador USB de 5V DC - Utilização recomendada: Roteador, modem, smartphone, sistema de vigilância por vídeo Especificações: - Entrada: 80-265V/50/60Hz - Saidas: USB 5V/2A, DC 5V/2A, DC 9V/2A, DC 12V/2A, POE 15V/1A, POE 24V/1A - Potência de saída (máx): 36W - Capacidade de bateria: 4x 2600mAh - Temperatura operacional: 0 a 45°c - Umidade operacional: 10 a 90% RH - Composição: Plástico e componentes eletrônicos. Itens inclusos: 1x No-Break Portátil 1x Cabo de energia AC 1x Cabo de energia DC macho para macho (1 para 1) 1x Cabo de energia DC macho para macho (1 para 2) 1x Manual do usuário Manufacturer:Outros Model Name:No Registration ID:7894561323', 318.0, 176.99, NULL, 'Home Appliances > Electrical Circuitry & Parts > Others', 'https://cf.shopee.com.br/file/br-11134207-820lw-mov8oioq5uklf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1232299933%2F45311390660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46211317194', 'Suporte Monitor Articulado Gamer NB A5 Pistão Gás 17 A 32 Pol Até 9kg', '⚡ SUPORTE DE MONITOR NORTH BAYOU A5 | MOLA MECÂNICA ERGONÔMICA | 17-32 POLEGADAS | ATÉ 9KG! ⚡ Olá! Quer transformar seu espaço de trabalho ou jogo em um ambiente mais ergonômico e organizado? O Suporte de Monitor North Bayou A5 é a solução perfeita! Com design articulado, ajustes precisos e sistema de mola mecânica, ele permite posicionar seu monitor na altura e ângulo ideais, reduzindo a tensão no pescoço e nas costas. ✅ PRINCIPAIS VANTAGENS E RECURSOS: Design ergonômico para saúde: Ajuste a altura, inclinação e rotação do monitor para alinhar com seus olhos, prevenindo dores e fadiga durante longas horas de uso. Mola mecânica de alta precisão: Permite ajustes suaves e sem esforço em qualquer posição, mantendo o monitor estável sem oscilações. Rotação total de 360°: Inclinação de +90°/-25°, rotação de ±90° e giro de ±90°, permitindo usar o monitor na horizontal ou vertical, e compartilhar a tela com facilidade. Economia de espaço na mesa: Libera até 80% do espaço ocupado pelo suporte original do monitor, deixando sua mesa mais limpa e funcional. Sistema de gerenciamento de cabos integrado: Esconde os cabos dentro do braço articulado, mantendo seu setup organizado e sem fios bagunçados. Instalação rápida e fácil: Inclui todos os acessórios necessários, instalação em menos de 5 minutos sem ferramentas complicadas. ⚙️ ESPECIFICAÇÕES TÉCNICAS: Modelo: North Bayou A5 Tipo: Suporte de monitor de mesa articulado Tamanho compatível: 17 a 32 polegadas Capacidade de carga: 2 a 9 kg Padrão VESA: 75x75 mm e 100x100 mm Ajustes de ângulo: Inclinação: +90° / -25° Rotação (vertical/horizontal): ±90° Giro lateral: ±90° Altura máxima de ajuste: 420 mm Alcance máximo horizontal: 520 mm Instalação: Grampo de mesa (compatível com espessura de 20 a 80 mm) Material: Aço carbono + Plástico de alta qualidade Cor: Preto 📦 ITENS INCLUSOS NO KIT: 1 Suporte de monitor North Bayou A5 completo 1 Grampo de mesa ajustável 1 Kit completo de parafusos e acessórios 1 Manual de instruções ❓ PERGUNTAS FREQUENTES (FAQ): Compatível com quais tamanhos de monitor? Compatível com monitores de 17 a 32 polegadas, desde que tenham furos de fixação VESA de 75x75 mm ou 100x100 mm na parte traseira. Qual o peso máximo que suporta? Suporta monitores com peso entre 2 e 9 kg. Verifique o peso do seu monitor sem o suporte original antes de comprar. É fácil de instalar? Sim! A instalação é muito simples e rápida. Basta fixar o grampo na mesa, conectar o braço e instalar o monitor com os parafusos inclusos. Posso girar o monitor para a posição vertical? Sim! A rotação de ±90° permite transformar seu monitor em modo vertical, ideal para leitura de documentos, códigos ou redes sociais. Tem sistema para organizar os cabos? Sim! O braço possui canais internos para passar os cabos de energia e vídeo, mantendo sua mesa limpa e organizada. Custom Product:No Condition:Novo Quantity:1', 349.0, 151.99, NULL, 'Computers & Accessories > Others', 'https://cf.shopee.com.br/file/br-11134207-820lr-moscox7zwy6b05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1232299933%2F46211317194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28881614919', 'Cesto Organizador Infantil Retangular 25L - Jacki Design', '""Cesto Organizador Infantil Retangular 25,7L – Jacki Design O Cesto Organizador Infantil Retangular 25,7L da Jacki Design é a solução perfeita para manter o quarto das crianças sempre arrumado e funcional. Ideal para armazenar brinquedos, roupas e acessórios, ele combina praticidade e design moderno, trazendo mais leveza ao ambiente. Fabricado em tecido de algodão e linho, o cesto possui acabamento sofisticado e resistente. Sua alça lateral reforçada garante um manuseio fácil e seguro, permitindo que seja transportado sem esforço. Parte da coleção PICCOLINO, ele conta com estampas lúdicas e cores vibrantes, tornando a organização mais divertida para os pequenos. Além disso, seu formato retangular otimiza o espaço, encaixando-se perfeitamente em nichos, prateleiras ou cantos do quarto. Diferenciais: ✔ Capacidade de 25,7 litros, ideal para brinquedos, roupas e acessórios ✔ Formato retangular, facilitando o armazenamento e aproveitamento de espaço ✔ Alça lateral reforçada para fácil transporte ✔ Material durável e leve em algodão e linho ✔ Estampas lúdicas e cores vibrantes, perfeitas para quartos infantis ✔ Dobrável, podendo ser guardado quando não estiver em uso Especificações: Material: Algodão e linho Dimensões: 38 cm (C) x 26 cm (L) x 26 cm (A) Coleção: Piccolino Marca: Jacki Design Explore a coleção completa PICCOLINO e torne a organização do quarto das crianças mais prática e encantadora!"', 62.9, 47.3, NULL, 'Home & Living > Home Organizers > Laundry Bags & Baskets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc98u5p5qrq882', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F530578890%2F28881614919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
