INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10197673346', 'Kit Revisão Fz25 250 Abs 2018-2026 Óleo Yamalube 20w50 + Filtros + Vela Ngk', 'Aumente a vida útil de sua moto. Praticando uma manutenção rigorosa do sistema de lubrificação, trocando o óleo e o filtro de óleo regularmente você estará estendendo a vida do motor, evitando desgaste excessivo das partes móveis, aumentando o desempenho e reduzindo o consumo de combustível. Compatível com: YAMAHA FAZER 250 2018 FAZER 250 2019 FAZER 250 2020 FAZER 250 2021 FAZER 250 2022 FAZER 250 2023 FZ25 250 ABS 2018 FZ25 250 ABS 2019 FZ25 250 ABS 2020 FZ25 250 ABS 2021 FZ25 250 ABS 2022 FZ25 250 ABS 2023 FZ25 250 ABS 2024 FZ25 250 ABS 2025 FZ25 250 ABS 2026 Conteúdo da Embalagem: 02 Litros de Óleo Yamalube 20w50 Mineral 01 Filtro de Óleo C/ Oring 01 Filtro de Ar 01 Vela de Ignição NGK 01 Filtro de Combustivel Especificações do Óleo Yamalube: - Tipo de Óleo: Mineral - Viscosidade: 20W50 - Classificação: API SL; - JASO MA2 - Número de Registro ANP: 7184 Vantagens: - Protege o motor; - Prolonga sua vida útil; - Proporciona segurança; - Permite uma lubrificação mais eficaz; - Proporciona melhor rendimento do motor e precisão de funcionamento; - Contribui na economia de combustível; - Contribui para a redução de emissão de poluentes na atmosfera. Dados Técnicos da Vela: - Modelo: DR8EA - Eletrodo Centro: níquel - Diâmetro da rosca: 12mm - Diâmetro do soquete: 18mm - Comprimento da rosca: 19mm - Folga: 0,7mm - Eletrodo Terra: Níquel Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 279.9, 251.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8260n-mj6yk1lzsr9i0e', 'https://shope.ee/an_redir?origin_