INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693000298', 'Disco de Freio Dianteiro Pcx 150 2019 A 2024', 'Disco de Freio Dianteiro Compatível com: HONDA PCX 150 2019 PCX 150 2020 PCX 150 2021 PCX 150 2022 PCX 150 2023 Características: - Espessura: 3 mm - Produzidos no padrão Original; - Excelente frenagem e equilíbrio; - Discos ventilados que evitam o superaquecimento; - Alta resistência ao desgaste; - Aumenta a frenagem mesmo em terrenos úmidos - Bom funcionamento do sistema de freios IMPORTANTE: - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. OEM é a sigla de Original Equipment Manufacturer , ou “Fabricante Original do Equipamento”. Em resumo, o produto é produzido com as mesmas características de um produto PADRÃO ORIGINAL DE FÁBRICA, garantindo assim o encaixe e funcionamento perfeito.', 119.9, 113.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rd3t-lv3cs05k4j7e80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F23693000298', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293900726', 'Par Adesivos Gti Golf Lateral 1994 Ate 1997 Prata Refletivo', 'Adesivo Genérico._x000D_ Os adesivos automotivos além de determinar, em muitos casos, o modelo do veículo, também personalizam o seu carro e protegem a pintura. Os adesivos são produzidos em vinil automotivo autocolante importado, dispensando a utilização de produtos para a fixação. Resina de alta qualidade, testada e aprovada na Flórida-USA. Possui a durabilidade de até 5 anos sem amarelar ou endurecer._x000D_ Par De Adesivos Gti Golf Lateral 1994 1995 1996 1997 Prata Refletivo ResinadoCaracterísticas: 2 Adesivos GTI / Fabricado em Vinil Prata Refletivo / Dimensões: 10,9 x 2,6 cm1 Par De Adesivos Refletivos Resinados GTI Para Golf Antigo _x000D_ Observações:Material autocolante.Resistente à chuva e raios UV.Embalagem segura para o transporte.Vinil importado._x000D_ Instruções Para Aplicação:1 - Limpe e remova qualquer impureza na área de aplicação do produto.2 - Limpe as mãos e remova o protetor do liner. Procure ter o mínimo de contato com a face adesiva.3 - Centralize o produto no local da aplicação. Após esse posicionamento,pressione o produto gradativamente, sempre do centro para as bordas.Procure retirar todas as bolhas.4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,pois isso danificará o produto._x000D_ OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo.Recomendamos que a aplicação seja feita por um profissional._x000D_ Garantia de 1 ano.', 23.47, 22.07, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7ren6-m859bpblkahh79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F22293900726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
