INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256658715', 'Maybelline Instant Age Rewind Eraser 150 - Corretivo Líquido 3,2ml', 'Corretivo líquido. Maybelline Instant Age Rewind Eraser conta com uma fórmula concentrada que disfarça as irregularidades da pele, uniformizando marcas e olheiras com alta cobertura e toque seco. O Corretivo Maybelline Instant Age Rewind Eraser também é enriquecido com ativos que tratam bolsas, olheiras e linhas finas a longo prazo. Sua composição ativa com Haloxyl reduz a aparência de inchaço deixando o olhar radiante e revigorado, para resultado Instant Age. Seu aplicador inovador "apaga" instantaneamente aquilo que você deseja disfarçar na pele, além de facilitar a aplicação do produto. Com acabamento natural e super fixação, não há necessidade de finalizar o Corretivo Maybelline Eraser com pó. Fórmula cruelty free. Como usar: Gire o aplicador do seu Corretivo Eraser Maybelline, concentrando o corretivo na direção das setas até que ele seja visível na esponja (pode demorar algumas voltas no primeiro uso). Em seguida, passe diretamente na área abaixo dos olhos, misturando em um movimento para fora. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 117.9, 117.9, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-82634-mlntmva7uk27d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58256658715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
