INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197125508', 'Kit 4 Fralda Cremer Magic Care Grandinhos Pacote Jumbo 14 Unidades Descartáveis', 'A nova fralda Cremer agora está mais fina e mais confortável, com proteção até 12h contra vazamentos! Além disso a fralda conta com um novo sistema antivazamento, composto por uma nova fita abre e fecha mais flexível e orelhas maiores que se ajustam ao corpinho do bebê, e uma camada super absorvente que distribui rápido o xixi pela fralda e evitando o retorno do líquido e garantindo que a pele do bebê fique bem sequinha. A nova Cremer traz proteção para noites tranquilas e dias mágicos, ainda mais confortáveis. • 12 horas de proteção para um bebê sempre sequinho e tranquilo; • Combinação de gel e barreiras altas que proporcionam absorção rápida e maior proteção contra vazamentos; • Camada superabsorvente que distribui rápido o xixi pela fralda e evita o retorno do líquido, garantindo que a pele do bebê fique sempre bem sequinha; • Nova fita mais flexível que abre e fecha quantas vezes for necessário sem estragar a fralda e orelhas maiores para mais conforto do bebê; • Cobertura externa macia e confortável como um tecido; • Cheirinho Encantador; • Dermatologicamente Testado.', 83.56, 83.56, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-823qc-moobypjo3soya4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18197125508', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259446820', 'Lasanha Bolonhesa Sadia', 'A Lasanha Bolonhesa Sadia é a combinação perfeita de praticidade e sabor para suas refeições! * Preparo rápido no forno ou micro-ondas. * Feita com ingredientes selecionados e um delicioso molho de carne. Modo de Preparo: 1. Remova totalmente a película plástica da bandeja. 2. Coloque a bandeja sobre um suporte adicional para assar. Leve a lasanha ao micro-ondas, forno elétrico ou a gás, de acordo com as indicações de tempo e temperatura: * Micro-ondas (potência alta 100%): Congelado 11 minutos, descongelado 7 minutos. * Forno elétrico (posição assar 210°C): Congelado 45 minutos, descongelado 25 minutos. * Forno a gás (forno médio 200°C): Congelado 50 minutos, descongelado 25 minutos. Alérgicos: Contém ovo e derivados, derivados de trigo, derivados de leite e derivados de soja. Pode conter centeio, cevada e aveia. Contém lactose. Contém glúten.', 19.49, 19.49, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-825bd-mqnekv30phc31a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F58259446820', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
