INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394987551', 'Trava Roscas Alto Torque W742 - Média Viscosidade WURTH', 'O Trava roscas corresponde às exigências do bloqueio de rosca. Com os métodos convencionais (por exemplo mola de pressão ou contraporca), as forças de separação são absorvidas em apenas 40% das superfícies sob pressão. O bloqueio das instalações roscadas com o uso do ?Trava Rosca? tem, por outro lado, uma resistência superior à obtida por meios mecânicos; - O Trava Roscas, quando no estado líquido, preenche os espaços e nas espirais das roscas, assegurando 100% de contato entre as faces, impedindo ao mesmo tempo a corrosão. Características: - Simples e fácil aplicação; - A força máxima é atingida após 24hs da aplicação do produto, porém a trava inicial ocorre 60 minutos após a aplicação; - Não necessita de qualquer tipo de mistura ou dosador para realizar a aplicação; - Embalagem especial que evita desperdícios; - Qualidade superior à maioria dos produtos convencionais utilizados nas montagens e vedações; - Resolve problemas com vedações difíceis; - Não necessita montar juntas convencionais. Principais Vantagens: - Travamento, vedação, retenção e selagem de juntas e roscas; - Ideal para a manutenção, produção e construção; - Cura rápida; - Pronto para aplicar, livre de solventes e à prova de vibrações; - Cura em contato com metais e na ausência de ar; - Reduz o tempo de aplicação/ montagem e os custos de produção.', 26.83, 26.83, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-822yp-mog1yx5481704a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1036817611%2F23394987551', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
