INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198845645', 'Pote Hermético Ou Quadrado 1L Linha Duo Lock', 'ATENÇÃO, NÃO VENDEMOS PARA CNPJ Detalhes do produto • Dupla vedação hermética que mantém os alimentos frescos por mais tempo • Design modular e empilhável que otimiza o espaço nos armários • Ideal para organizar e armazenar alimentos na cozinha • Tecnologia e inovação para uma rotina mais prática e funcional e sem desperdício Informações Técnicas Altura:15 cm Largura:10 cm Comprimento:10 cm Peso:0.165 kg Material:PS+PP+SILICONE Capacidade:1L O Pote Hermético da Linha Duo Lock é a solução ideal para quem busca organização e praticidade na cozinha. Com tecnologia de dupla vedação hermética na tampa, garante alimentos frescos por mais tempo e muito mais segurança no armazenamento. Seu design permite que os potes sejam modulares e empilháveis, otimizando o espaço nos armários. Perfeito para conservar grãos, snacks ou temperos, une funcionalidade, tecnologia e inovação para facilitar sua rotina e deixar sua cozinha sempre organizada. Cuidados Sugere-se higienizar com sabão neutro e esponja macia, evitando produtos abrasivos no processo de limpeza. Conteúdo da embalagem 1 pote hermético Ou quadrado 1L Linha Duo Lock', 45.9, 45.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdwd-mdkcsqicegus62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1477305422%2F22198845645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
