INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12706256815', 'Jogo Trunfo Dinossauros 01402 - Grow', 'DESCRIÇÃO DO PRODUTO Super Trunfo Dinossauros traz 32 cartas com ilustrações e informações sobre os maiores seres vivos que já habitaram a Terra. Em qual item o dinossauro da sua carta é o melhor? Será em altura? Em peso? Ou você tem o Super Trunfo? Escolha, compare e vença esta emocionante disputa! CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: 32 cartas, 1 caixa plástica e 1 regra Dimensões da Aproximadas da Embalagem: 16 x 10 x 2 cm (Altura x Largura x Comprimento/Profundidade) Material/Composição: Plástico e Papel Idade Mínima Recomendada: A partir de 7 anos Participantes: A partir de 1 pessoa Alimentação: Não se aplica Marca: Grow Referência: 01402 Garantia: 3 meses contra defeitos de fabricação Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto 100% original, lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 28.47, 25.05, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/acb62b31fcddda186fef88c8dcf18529', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F12706256815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207015578', 'Fritadeira Air Fryer 4,2L Kian AF107 Preta 127V', 'A Air Fryer Kian AF-107 4,2L 1350W Preta é a escolha ideal para quem busca praticidade, rapidez e refeições mais saudáveis no dia a dia. Com tecnologia de circulação de ar quente, ela prepara alimentos crocantes por fora e macios por dentro sem precisar usar óleo, mantendo o sabor e reduzindo gordura nas receitas. Com capacidade de 4,2 litros, é perfeita para preparar porções generosas para toda a família. Seu controle de temperatura ajustável e timer com desligamento automático permitem preparar diferentes tipos de alimentos com facilidade — desde batatas fritas e nuggets até carnes, legumes e sobremesas. O cesto com revestimento antiaderente evita que os alimentos grudem e facilita muito a limpeza após o uso, enquanto o design moderno e compacto combina com qualquer cozinha. Principais vantagens Capacidade de 4,2 litros ideal para famílias Preparo sem óleo, mais saudável Controle de temperatura ajustável para várias receitas Timer com desligamento automático Cesto removível antiaderente, fácil de limpar Tecnologia de circulação de ar quente para alimentos mais crocantes Especificações Marca: Kian Modelo: AF-107 Capacidade: 4,2 L Potência aproximada: 1350 W Tipo: Fritadeira elétrica sem óleo Cor: Preta Prepare batatas, frango, peixe, pão de queijo, legumes e muito mais de forma rápida e prática, com menos gordura e mais sabor!', 219.9, 217.99, NULL, 'Home Appliances > Kitchen Appliances > Air Fryers', 'https://cf.shopee.com.br/file/sg-11134201-8258q-mr1ykyx14emf76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412968566%2F58207015578', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43468072354', 'Par de Lâmpadas Super Led Mini Headlight S14 Nano 6000K para Carros Luz Branca Potente e Longa Vida Útil - Shocklight', '# Auto Equip # Seja bem-vindo(a)!!!--- Descrição Lâmpada Super Led Mini S14 Nano Headlight Shocklight Equipar o farol do carro com lâmpadas de LED é o desejo de muitos motoristas, porém nem sempre é tão simples. A maioria dos LEDs do mercado possui tamanho maior do que a lâmpada original em seu modelo de encaixe equivalente, dificultando o encaixe e a vedação do farol. A lâmpada de LED para farol ShockLight S14 Nano tem tamanho equivalente a lâmpada original, tornando simples a instalação de LED em qualquer farol. Além do tamanho, a disposição dos LEDs no corpo da lâmpada também é equivalente a posição do filamento da lâmpada halógena original, fazendo com que este lâmpada tenha um excelente foco de acordo com o projeto do farol original. Especificações técnicas: - Voltagem: DC9V-12V - Potência: 32W - Lumens: 3600LM - IP Rate: IP68 - Chip COREANO - Temperatura de Cor: 6000K - Dissipador: ALUMINIO S/COOLER - Temperatura de Operação: -40?C ~ +80?C - Feixe de Luz: 360° - VIDA ÚTIL: 30.000 HORAS Conteúdo da embalagem: - Par Lâmpadas Importante - Garantia de 12 meses; - Pedidos aprovados até 12h00 de segunda a sexta será enviada no mesmo dia; - Enviamos em até 24h úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - Imagens meramente ilustrativas; - A cor do produto pode variar de acordo com a tela do seu smartphone ou computador; - Utilize o campo de "Perguntas e respostas" e esclareça suas dúvidas com nosso suporte técnico. - Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor A Auto Equip recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 84.9, 74.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-824hq-meeboea3p3b743', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F43468072354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898184139', 'Guarda Roupa Casal 3 Portas Doha Carraro Ripado Branco', 'Guarda-Roupa Casal Doha O Roupeiro de Casal Doha é a escolha perfeita para quem busca sofisticação, praticidade e organização no quarto. Com um design moderno e funcional, ele mantém suas roupas sempre organizadas, otimizando o espaço de forma inteligente. Equipado com 3 portas de correr, proporciona acesso fácil e eficiente, tornando o dia a dia mais prático. Suas portas reversíveis oferecem a versatilidade de dois acabamentos em um único móvel, permitindo que você escolha entre diferentes estilos para harmonizar com a decoração do ambiente. Os puxadores metálicos conferem um toque de elegância e sofisticação, destacando a qualidade do design. Renove seu quarto com um móvel que alia beleza, funcionalidade e conforto, criando um espaço aconchegante e moderno para seus momentos especiais. Especificações do Guarda-Roupa: Medidas totais: Largura: 170 cm | Altura: 206 cm | Profundidade: 46,0 cm Peso total: 83,4 Kg Garantia: Os produtos possuem garantia de 03 meses (se utilizado em condições normais), contra defeito de fabricação, ou componentes utilizados. Esta garantia não cobre defeitos por uso inadequado ou abusivo, falta de cuidados e desbotamento natural dos revestimentos. Condições de perda da garantia: - Mau uso ou manuseio incorreto. - Desbotamento causado pela exposição direta da luz solar. - Danos causados por agentes da natureza, como inundações ou acidentes de qualquer espécie. - Uso indevido de produtos abrasivos para realizar a limpeza. - Decurso do prazo estabelecido. Recomendações para uma boa conservação: - Dicas para limpeza e conservação do seu produto, você encontrará no esquema de montagem que o acompanha. Informações importantes: - Trabalhamos para apresentar imagens fiéis ao produto real. Porém, as cores podem sofrer variações de acordo com o monitor, iluminação do ambiente em que se encontram e até por sua percepção visual comparado ao ambiente residencial. - Desta forma, as imagens são meramente ilustrativas. - Todos os objetos decorativos não acompanham o produto. - O produto é enviado desmontado. - O produto acompanha manual com instruções para a montagem. - A empresa Móveis Carraro não realiza o serviço de montagem. PERGUNTAS FREQUENTES - Existem outras cores disponíveis? Sim, este produto possui outras cores disponíveis em outros anúncios. - Vocês entregam para todas as regiões do Brasil? De que forma é feita a entrega? Sim, entregamos para todas as regiões do Brasil. E a entrega é realizada por transportadoras parceiras. - Este produto é novo ou usado? Todos os nossos produtos são novos. E acompanham nota fiscal e certificado de garantia. - Recebo o produto montado? Não, este produto é enviado desmontado. Junto com ele é enviado manual com instruções para a montagem. - Vocês realizam a montagem do produto? Não possuímos o serviço de montagem.', 1619.99, 1032.59, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rbko-m5yj696ua5wraa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952014476%2F23898184139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198695538', 'Armário de Cozinha Completa com Balcão Atlanta Essence Carraro Amêndoa', 'Cozinha Modulada Compacta Atlanta Essence Móveis Carraro 225cm Amêndoa com Torre Quente e Balcão Renove sua cozinha com mais organização, beleza e praticidade. A Cozinha Modulada Atlanta Essence da Móveis Carraro é ideal para quem busca um ambiente moderno, funcional e com excelente aproveitamento de espaço. Com acabamento na cor Amêndoa, ela combina facilmente com diferentes estilos de decoração e valoriza o ambiente com um visual elegante. Principais benefícios: - Cozinha modulada compacta, ideal para apartamentos, casas e cozinhas menores - Design moderno e funcional - Excelente aproveitamento de espaço - Cor Amêndoa, sofisticada e fácil de combinar - Estrutura resistente e durável para o uso diário Composição do produto: - 2 armários aéreos - 1 nicho incluso - 1 balcão de 105 cm com gaveteiro - 1 torre quente com espaço para 2 fornos Destaques da cozinha: - Armários aéreos que ajudam na organização dos utensílios - Nicho funcional para acomodar itens decorativos ou de uso diário - Balcão com gavetas para facilitar a rotina na cozinha - Torre quente com espaço para 2 fornos - Puxadores em ABS - Pés em ABS - Dobradiças metálicas - Corrediças metálicas Informações técnicas: - Material: MDP - Cor: Amêndoa - Peso total: 71 kg Medidas totais: - Largura: 225 cm - Altura: 190 cm - Profundidade: 44 cm Ideal para quem procura: - Cozinha modulada compacta - Cozinha pequena completa - Armário de cozinha moderno - Cozinha com torre quente - Balcão de cozinha com gavetas - Móvel de cozinha funcional - Cozinha Carraro Informações importantes: - Produto enviado desmontado - Acompanha manual de montagem - Acompanha manual de limpeza e conservação - A Móveis Carraro não realiza o serviço de montagem - Objetos decorativos não acompanham o produto - As cores podem variar conforme o monitor, iluminação do ambiente e percepção visual - A entrega não é realizada na parte interna da residência ou condomínio - É necessário ter uma pessoa no endereço para receber a entrega Garantia: - 3 meses contra defeitos de fabricação, mediante uso em condições normais Condições de perda da garantia: - Mau uso ou manuseio incorreto - Desbotamento por exposição direta ao sol - Danos causados por agentes da natureza ou acidentes - Uso de produtos abrasivos na limpeza - Após o prazo de 3 meses Perguntas frequentes: - Tem outras cores disponíveis? Sim, este produto possui outras cores disponíveis em outros anúncios. - Entregam para todo o Brasil? Sim, entregamos para todas as regiões do Brasil por meio de transportadoras parceiras. - O produto é novo? Sim, todos os nossos produtos são novos, acompanham nota fiscal e certificado de garantia. Aproveite para transformar sua cozinha com a qualidade, praticidade e o design da Móveis Carraro.', 1099.99, 967.37, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-mbsjuey089ce2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952014476%2F23198695538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493050686', 'Como Falar em Público e Encantar as Pessoas | Dale Carniegie', 'Do consagrado autor de Como fazer amigos e influenciar pessoas. Os ensinamentos de Dale Carnegie ganharam fama mundial e continuam a inspirar milhões de leitores não por apresentarem truques engenhosos, mas por valorizarem uma verdadeira conexão entre as pessoas. “Dale Carnegie mudou a minha vida” – Warren Buffett “Talvez você pense que falar em público é um perigo a ser evitado. Quando terminar de ler este livro, você saberá que é uma oportunidade que deve ser aproveitada com alegria e da melhor forma possível. Sua capacidade de se expressar com sinceridade e energia terá se transformado em um grande trunfo para sua carreira. O que você está prestes a aprender surtirá um efeito drástico não só na sua forma de se comunicar, mas também na forma como vê a si mesmo.” – Dale Carnegie Neste livro, Dale Carnegie vai ajudar você a preparar e organizar uma apresentação, seja ela de apenas cinco minutos diante de um grupo pequeno ou de meia hora para um auditório lotado. Você vai descobrir o que é fundamental não apenas para entreter seus ouvintes, mas também para informá-los, persuadi-los e inspirá-los a agir motivados pela sua mensagem. E talvez o mais importante de tudo: este livro vai lhe mostrar como perder o medo das apresentações orais de uma vez por todas. Especificações do livro: Título: Como fazer amigos e influenciar pessoas Título original: Stand and Deliver Autor(es): Dale Carniegie Ano de Edição: 2020 Capa: Brochura Acabamento: Laminação Fosca Miolo: Soft Polém Páginas: 208 Dimensões: Altura: 23 cm Largura: 16 cm Profundidade: 2 cm Peso: 0,700 k.g ISBN: 9786555640762 Editora: Sextante', 46.82, 46.82, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfgm-ma046a83kvn06e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23493050686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21659077550', 'Bamoer 925 Silver Beads Devil Olhos E Cruz Série Pendurada Pingente Da Moda Para Acessórios BSC313', '❤ Bem-vindo à Bamoer Official Shop, onde nos esforçamos para fornecer aos nossos clientes produtos que satisfaçam a demanda por qualidade e eficiência. Comprar não pode ser mais fácil do que isso, então comece hoje! ✨ Imformação do Produto ✨ •Material: Prata esterlina 925 • Peso: 2g • Tamanho: 3,5 * 2 cm, abertura: 0,4 cm • Origem: China •Função: E Colar, Presentes, Lembranças, Coleção, Acessórios de moda. ✨ Instruções de armazenamento ✨ •Não Deixe o produto entrar em contato com cosméticos e produtos químicos •Limpe O produto regularmente com creme dental diluído ou líquido de lavar louça e depois enxágue com água e seque. • Armazenar em uma caixa ou uma bolsa quando não estiver em uso ✨ Nota ✨ • Evite golpes pesados, fogo e produtos químicos corrosivos • O produto é seguro para a pele usar. •Devido À diferença na exibição do terminal, pode haver ligeira diferença de cor entre a imagem do produto e o produto real. • Estoque 100% pronto • Novo e de alta qualidade ❤ Estas joias são requintadamente embaladas e estão prontas para presentear. Compre agora uma surpresa. ❤ Obrigado por escolher a Loja Oficial Bamoer!', 106.99, 72.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/sg-11134201-22100-3k7565j0m2ivfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325735487%2F21659077550', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20107532620', 'Ética Cristã | Norman L , Geisler', 'Ética CristãOpções e questões contemporâneas Lançada pela primeira vez no Brasil em 1984 Ética Cristã chega agora em sua 2 ª edição revisada e ampliada abordando questões recentes No mundo de hoje os cristãos são diariamente bombardeados por uma série de dilemas éticos que nos indicam que os caminhos apontados pela sociedade atual ou pela cultura vigente não raro são bem diferentes daqueles apontados pela ética cristã Fica então a dúvida Como devemos lidar com questões como aborto eutanásia biomedicina pena de morte guerra desobediência civil homossexualismo casamento divórcio controle de natalidade ecologia direito dos animais drogas pornografia entre tantos outras? O propósito deste livro é justamente fornecer aos cristãos os fundamentos bíblicos para responder a essas questões tão frequentes e complexas Geisler analisa profundamente cada questão tanto do ponto de vista filosófico como bíblico e nos mostra de forma clara e precisa como vencer cada um desses dilemas com argumentos sólidos e bastante coerentes Veja a seguir alguns dos novos tópicos acrescentados Infanticídio questões biomédicas desobediência civil homossexualidade casamento e divórcio; Drogas apostas e jogos de azar pornografia controle de natalidade e etc Título Ética Cristã Subtitulo Opções e questões contemporâneas Autor Michael Green Páginas 528 Formato 23 x 16 x 1 cm Peso 0 772 kg ISBN 9788527504485 Editora Vida Nova', 114.99, 114.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/1a64ea354acf96ae1e52fd0ad89caed4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20107532620', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
