INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55511939247', 'Noções Básicas do Hebraico Bíblico | Rosemary Vita e Teresa Akil', 'Noções Básicas do Hebraico Bíblico | Rosemary Vita e Teresa Akil Para Ler e Traduzir Rosemary Vita, Teresa Akil Este livro apresenta um método simples e direto para quem deseja dar os primeiros passos na língua hebraica bíblica. Com abordagem progressiva, a obra conduz o leitor pelo alfabeto, sinais vocálicos, princípios de leitura e fundamentos gramaticais necessários para compreender o idioma original do Antigo Testamento. Desenvolvido para quebrar a barreira que torna o hebraico bíblico distante e inacessível para muitos estudantes da Bíblia, o livro oferece um caminho seguro para adquirir autonomia na leitura e tradução de textos bíblicos. Esta terceira edição revisada e atualizada preserva a clareza didática que tornou a obra referência, aprimorando sua precisão técnica para facilitar o estudo individual e o uso em sala de aula. Método progressivo que permite começar a ler e traduzir textos bíblicos em poucas liçõesAbordagem didática que vai do alfabeto hebraico aos fundamentos gramaticais e sistema verbalLinguagem acessível para iniciantes absolutos e estudantes que desejam revisar conteúdoAmplamente utilizada em seminários, cursos de teologia e programas de formação bíblicaAutoras especialistas: Rosemary Vita (mestre em Língua Hebraica pela USP) e Teresa Akil (doutora em Teologia)Ideal para pastores, professores, pregadores e estudantes da Bíblia que desejam avançar na exegese bíblica e acessar o texto hebraico com maior profundidade. Uma ferramenta indispensável para transformar o hebraico de obstáculo em instrumento vivo para o estudo sério das Escrituras. Especificações do livro Noções Básicas do Hebraico Bíblico | Rosemary Vita e Teresa Akil: Título: Noções Básicas do Hebraico Bíblico | Rosemary Vita e Teresa Akil Subtítulo: Para Ler e Traduzir Autores(es): Rosemary Vita, Teresa Akil Ano de Edição: 2025 Capa: Brochura Acabamento: Laminação Fosca Miolo: Offset Páginas: 176 Dimensões: 23 x 15,7 x 1 cm Peso: 273 g ISBN: 9788577426935 Idioma: Hebraico, Português Editora: Editora Hagnos Família: Livros Assunto: Estudo, Língua Hebraica', 31.89, 31.89, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823rs-mp9s1ft8fqj245', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F55511939247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14586305193', 'Livro Mais aventuras de Sherlock Holmes | Arthur Conan Doyle', 'Mais aventuras de Sherlock Holmes Sherlock Holmes é um detetive britânico enigmático e pedante do final do século XIX e início do século XX. Ele utiliza a metodologia científica e a lógica dedutiva para solucionar seus casos e conta com a ajuda de seu fiel amigo e parceiro dr. Watson. Neste livro estão reunidos seis breves, mas não pouco enigmáticos, casos policiais brilhantemente narrados pelo doutor Watson, e que somente com a perspicácia e genialidade de Sherlock Holmes puderam ser solucionados. Título , Mais ,aventuras ,de ,Sherlock ,Holmes Coleção , Sherlock ,Holmes Autor , Arthur ,Conan ,Doyle Páginas , 208 Formato , 23 ,x ,16 ,x ,1 ,cm Peso , 237g ISBN , 9788594318589 Editora , Ciranda', 11.38, 11.38, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/8d1cc9432e2447ad13ccbbaf2857616a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F14586305193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
