INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793104218', 'PNEU 100/80 - 18 METZELER ME STREET 59P M/C TL REINF TRAS', 'O novo integrante da família Metzeler para motocicletas de baixa cilindrada, com visual superesportivo. A marca Metzeler foi fundada em 1892, na Alemanha. A Metzeler desenvolve pneus para motos com a preocupação constante em garantir o melhor produto. Os pneus Metzeler são pneus duráveis, com alto nível de conforto e segurança, tornando-se uma das opções preferidas na hora de substituir os pneus originais de motos de alta cilindrada, pois não deixam nada a desejar em relação ao pneu original de fábrica. A Metzeler vem ampliando a sua gama para atender a variados tipos de motocicletas, com um pneu barato e de altíssima qualidade. APLICAÇÕES: DAFRA: APACHE 150, APACHE 200 HAOJUE: DK 150, DK 150 CBS, DK 150 FI HONDA: CG 160 TITAN FLEX DÚVIDAS FREQUENTES… Faturamento para CNPJ? Não faturamos para CNPJ Contribuinte. Apenas para CNPJ Isentos de Inscrição Estadual; Os produtos são novos? Possuem Garantia? Sim, todos os produtos são novos e possuem garantia de fábrica, de 5 anos, contra defeito de fabricação. Acompanha Nota Fiscal? Sim, todas nossas vendas são realizadas com emissão de Nota Fiscal. A mesma, é enviada junto aos produtos do pedido. Posso retirar os produtos na loja? Não. As entregas são realizadas via transportadora para o endereço indicado no cadastro do comprador. Vocês aceitam outro produto como troca? Aceitam Usados? Não. Trabalhamos somente com a venda de produtos novos, sem troca. Esses Pneus são Remold? Não, trabalhamos apenas com produtos Novos e Originais. Ao receber os produtos, devo conferir? Sim, sempre deve ocorrer a conferência dos produtos no momento da entrega. Se tiver alguma divergência, não receba os mesmos. Preciso realizar a troca e/ou devolução? Em relação a trocas e/ou devoluções, salientamos que deve observar o prazo para realizar a mesma. Os itens devem estar obrigatoriamente, no mesmo estado em que recebeu e com suas etiquetas. NÃO ACEITAMOS DEVOLUÇÕES DE PNEUS QUE JÁ FORAM MONTADOS E/OU USADOS. Ainda tenho algumas dúvidas. Se você ainda tem dúvidas, utilize o campo de perguntas para falar com os nossos consultores. E atenção, só clique no botão comprar após ter certeza de que as condições descritas acima estão de acordo.', 491.8, 491.8, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd4y-lwsr9n59katr46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819034845%2F23793104218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597457885', 'Sirene Mecânica Rotativa Twister 127V - 0,3A A 0,5A -DNI 3715', 'Sirene Mecânica Rotativa Twister 127V - 0,3A A 0,5A -DNI 3715Obtenha uma sinalização com som exclusivo e contínuo do tipo viatura utilizando a Sirene Mecânica Rotativa Twister, da DNI. Ideal para ser instalada como sirene para alarme em escolas, indústrias, viaturas e relógios de ponto, possui base móvel que facilita a sua instalação em diferentes ambientes. Características do Produto:Marca: DNI Modelo: DNI 3715 Toque: Som Contínuo Rotativo Tensão: 127V Corrente: 0,3 a 0,5A Pressão Sonora: 117dB Cor: Preta Dimensões: 9,0 x 6,5 x 11cm Com a Sirene Mecânica Rotativa Twister, você terá a garantia de um produto de qualidade, fabricado pela renomada marca DNI. Seu design compacto e eficiente proporciona uma sinalização sonora clara e potente, tornando-a ideal para diversas aplicações de segurança e alerta. A sinalização contínua e rotativa oferecida por este modelo garante que a mensagem de alerta seja claramente audível em ambientes diversos, garantindo a segurança e a eficácia do sistema de alarme. Além disso, sua instalação versátil e base móvel facilitam a adaptação em diferentes locais, tornando-a uma escolha prática e funcional para suas necessidades de sinalização sonora. Invista na segurança e eficiência do seu sistema de alarme com a Sirene Mecânica Rotativa Twister DNI 3715. Adquira já a sua e garanta uma sinalização sonora confiável e de alta qualidade!', 289.29, 289.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rd6r-ltzm2lqd4pzf2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F23597457885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
