INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698340404', 'Esmerilhadeira Angular STANLEY SBG700M2K 125mm 20V Com 2 Baterias, Carregador e Maleta 110V', 'A Esmerilhadeira Angular STANLEY SBG700M2K 125mm 20V Com 2 Baterias, Carregador e Maleta é ideal para trabalhos de corte e desbaste em diferentes materiais, oferecendo mobilidade e praticidade graças ao sistema sem fio. Indicada para manutenção, instalações, reformas e aplicações profissionais, proporciona desempenho consistente para atividades que exigem precisão, produtividade e liberdade de movimento em oficinas, serralherias e canteiros de obra. Seu grande diferencial é o motor sem escovas (BRUSHLESS), que entrega maior eficiência e contribui para a redução dos custos de manutenção. O design ergonômico e leve proporciona mais conforto durante o uso prolongado. Conta com guarda de proteção sem chave para ajustes rápidos, caixa de engrenagem em alumínio para maior durabilidade, interruptor com trava de segurança e empunhadura lateral de 3 posições, aumentando o controle e a segurança durante as aplicações. Principais características • MOTOR SEM ESCOVAS (BRUSHLESS): maior eficiência e menor necessidade de manutenção • VELOCIDADE DE 8.000 RPM: desempenho para cortes e desbastes diversos • GUARDA SEM CHAVE: ajuste rápido conforme a aplicação • CAIXA DE ENGRENAGEM EM ALUMÍNIO: maior resistência e vida útil • INTERRUPTOR COM TRAVA: mais segurança durante a operação • EMPUNHADURA 3 POSIÇÕES: maior conforto e controle no manuseio • BLOQUEIO DO EIXO: facilita a troca de discos Acessórios inclusos • 2 Baterias 4,0Ah (SB204) • 1 Carregador Bivolt • 1 Maleta Robusta, eficiente e confiável, a Esmerilhadeira Angular STANLEY SBG700M2K é ideal para quem busca potência, praticidade e segurança em trabalhos de corte e desbaste, contando com a conveniência do sistema sem fio e a durabilidade da linha profissional STANLEY.', 1799.0, 1799.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820m8-mq24j6emz8jm9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1475272551%2F23698340404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
