INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299204342', 'Sapatilha Feminina Flat Piccadilly 250132', 'A sapatilha feminina Flat Piccadilly 250132 é perfeita para mulheres que buscam conforto e elegância em seus calçados. Com um design clássico e moderno, essa sapatilha é feita com materiais de alta qualidade, proporcionando durabilidade e conforto ao longo do dia. Ideal para acompanhar o ritmo da mulher contemporânea, essa sapatilha é versátil e combina com diferentes estilos e ocasiões. Sua palmilha macia e solado antiderrapante garantem conforto e segurança para os seus pés. Adquira agora mesmo a sua sapatilha Flat Piccadilly e sinta-se ainda mais confiante e estilosa em todos os momentos. . MODELO: A0080132 REFERENCIA: 250132 MARCA: Piccadilly MATERIAL DA PALMILHA: PU MATERIAL DA SOLA: TR MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado GÊNERO: Female GRUPO DE IDADE: Adult TIPO DE SALTO: Flat MATERIAL DO SAPATO: Napa MEDIDA DO SALTO: 2 cm aproximadamente', 143.99, 143.99, NULL, 'Women Shoes > Flats > Ballet Flats', 'https://cf.shopee.com.br/file/sg-11134201-821g8-mgzwdnsixsej2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F22299204342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18308206279', 'Camiseta Lycra Mormaii Masculina Manga Longa Extraline Surf', 'CAMISETA MANGA LONGA MASCULINO EXTRALINE SURFE MORMAII 2022 DESCRIÇÃO DO PRODUTO Nossa roupa conta com uma modelagem anatômica e costura overlock, costura flexível e de construção dupla. nós da mormaii prezamos sempre pelo conforto e praticidade em nossas roupas. aliando tecnologias inovadoras, estudos de modelagem e testes de usabilidade, desenvolvemos cada roupa pensando em uma maior funcionabilidade da mesma e na melhoria do desempenho de cada atleta. assim, conforto, durabilidade e desempenho andam juntos com nossas roupas. CARACTERÍSTICA DO PRODUTO 50+ uv protection Elastano de alta qualidade, garantindo ao atleta alta flexibilidade e desempenho, bloqueando até 98% dos raios uv de acordo com as normas da arpansa, entidade australiana que é referência mundial na mensuração de fpu dos tecidos Tecnologia: modelagem anatômica Mormaii Composição: 84% poliamida e 16% elastano MORMAII: A história da Mormaii começa nas belas praias da região sul do litoral brasileiro no início dos anos 70, fundada pelo então médico e surfista Morongo. Surge, assim, uma marca com raízes no surfe, mas com um objetivo maior: a busca pela qualidade de vida. Atualmente, a marca é reconhecida por mais de uma centena de produtos que atendem as categorias Surf, Mergulho, Skate, Fitness, Moda Praia, Bicicletas, além de produtos como óculos, relógios e chinelos, entre outros, tornando a Mormaii a maior e mais querida marca de esportes livres do Brasil.', 309.9, 245.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Swimming Attire', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfd2t5ai6n0g4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F18308206279', NULL, NULL, '2026-07-