INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41781233504', 'KIT 4 PNEU MAGGION CARRO FUSCA 5.60-15 FC F2 FALCO 4LONAS C/C', 'KIT Pneu Industrial FC F2 Falco 4L 5.60-15 2x Maggion O KIT de Pneus 5.60-15 FC F2 Falco 4L da Maggion é indicado para uso em veículos de passeio e aplicações industriais leves que utilizem essa medida. Desenvolvido para rodagem em asfalto, oferece resistência, estabilidade e desempenho compatível com as especificações originais. A Maggion atua há quase 90 anos no mercado brasileiro, fornecendo pneus com certificações de qualidade reconhecidas por órgãos nacionais e internacionais. A marca é referência em durabilidade e segurança dentro das categorias em que atua. Especificações técnicas: Medida 5.60-15 Modelo FC F2 Falco 4L Categoria passeio Tterreno asfalto Índice de carga 79 (até 440 kg por pneu) Índice de velocidade P (até 150 km/h) Largura aproximada 148 mm e diâmetro aproximado 650 mm. O anúncio refere-se a 4 pneus novos, originais de fábrica. Não acompanha roda/aro nem câmara de ar. Todos os produtos são enviados com nota fiscal. Recomenda-se que a montagem seja realizada por profissional qualificado, utilizando ferramentas adequadas e respeitando as especificações de calibragem e aplicação indicadas pelo fabricante para garantir segurança e desempenho adequado.', 1841.9, 1547.2, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-823rc-moqvrw499wxt8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F41781233504', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894811652', 'Ventilador Mesa Mallory 30Cm Turbo Compact Pr/Gr', 'O Ventilador de Mesa Turbo Compact Mallory combina potência e eficiência em um design compacto e moderno, ideal para quem busca conforto e economia de energia. Com grade em sistema especial TS e hélice de 6 pás, ele garante o maior fluxo de ar na sua categoria de 30cm. Com eficiência energética A nas 3 velocidades, o ventilador proporciona menor consumo de energia, permitindo que você se refresque sem pesar na conta de luz. Sua oscicação horizontal, inclinação vertical ajustável, e grade removível tornam a limpeza fácil e prática. A nova linha de ventiladores Mallory foi projetada para oferecer o máximo desempenho com funcionamento silencioso, tornando-o perfeito para qualquer ambiente, seja na sua casa ou no escritório. Escolha o Ventilador Turbo Compact Mallory para um fluxo de ar poderoso, eficiência energética e praticidade no seu dia a dia. Características: • Grade especial em sistema TS, máxima vazão e mínimo ruído. • Silencioso • Hélice de 6 pás • Oscilação horizontal • Inclinação vertical • Alça para transporte • Comprimento do cabo de 1,30m', 149.99, 149.99, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/br-11134275-81ztc-mjk2xqrbrzlu13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1668969306%2F22894811652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
