INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298946704', 'Kit Suspenção Dianteira Onix Prisma Cobalt Spin Original Nakata 2013 2014 2015 2016 2017 2018 2019', 'Descrição O KIT DE SUSPENSÃO DIANTEIRA NAKATA – COMPATÍVEL COM VEÍCULOS GENERAL MOTORS – FOI DESENVOLVIDO PARA GARANTIR DURABILIDADE, CONFORTO E SEGURANÇA. CONTÉM BIELETAS, PIVÔS, AXIAIS E BANDEJAS, TODOS PRODUTOS NOVOS E ORIGINAIS NAKATA, ASSEGURANDO ALTO DESEMPENHO, RESISTÊNCIA AO DESGASTE E PERFEITA COMPATIBILIDADE COM O SISTEMA DE SUSPENSÃO. IDEAL PARA QUEM BUSCA ESTABILIDADE, SEGURANÇA E CONFIABILIDADE NA REPOSIÇÃO AUTOMOTIVA. KIT COMPLETO DE SUSPENSÃO – DIANTEIRO BIELETA NOME DO PRODUTO: Bieleta CÓDIGO DO PRODUTO: N93036 MARCA: Nakata PIVÔ DE SUSPENSÃO NOME DO PRODUTO: Pivô de Suspensão CÓDIGO DO PRODUTO: N99035 MARCA: Nakata AXIAL NOME DO PRODUTO: Axial CÓDIGO DO PRODUTO: N93077 MARCA: Nakata PIVÔ DE SUSPENSÃO NOME DO PRODUTO: Pivô de Suspensão CÓDIGO DO PRODUTO: N93024 MARCA: Nakata BANDEJA DE SUSPENSÃO DIREITA NOME DO PRODUTO: Bandeja Dianteira Direita CÓDIGO DO PRODUTO: NBJ3016D MARCA: Nakata BANDEJA DE SUSPENSÃO ESQUERDA NOME DO PRODUTO: Bandeja Dianteira Esquerda CÓDIGO DO PRODUTO: NBJ3016E MARCA: Nakata ITENS INCLUSOS 02 (DUAS) BIELETAS N93036 02 (DOIS) PIVÔS N99035 02 (DOIS) AXIAIS N93077 02 (DOIS) PIVÔS N93024 01 (UMA) BANDEJA DIANTEIRA ESQUERDA NBJ3016E 01 (UMA) BANDEJA DIANTEIRA DIREITA NBJ3016D APLICAÇÃO GENERAL MOTORS COBALT – 2012 A 2019 – DIANTEIRO GENERAL MOTORS JOY – 2013 A 2021 – DIANTEIRO GENERAL MOTORS JOY PLUS – 2013 A 2021 – DIANTEIRO GENERAL MOTORS ONIX – 2013 A 2021 – DIANTEIRO GENERAL MOTORS PRISMA – 2013 A 2021 – DIANTEIRO GENERAL MOTORS SPIN – 2013 A 2024 – DIANTEIRO BENEFÍCIOS DO KIT MAIOR SEGURANÇA E ESTABILIDADE NA CONDUÇÃO REDUÇÃO DE RUÍDOS E MELHOR ABSORÇÃO DE IMPACTOS COMPATIBILIDADE COM AS ESPECIFICAÇÕES ORIGINAIS (OEM) DURABILIDADE E RESISTÊNCIA SUPERIOR PRODUTOS NOVOS E ORIGINAIS NAKATA DÚVIDAS FREQUENTES Este produto é novo? SIM, TRABALHAMOS SOMENTE COM PRODUTOS NOVOS. O produto é original? SIM, TODOS OS COMPONENTES SÃO ORIGINAIS NAKATA. Possuem garantia? Qual o prazo de garantia? SIM, TODOS NOSSOS PRODUTOS POSSUEM NO MÍNIMO 90 DIAS DE GARANTIA CONTRA DEFEITOS DE FABRICAÇÃO OU CONFORME O PRAZO DO FABRICANTE. O produto é idêntico à foto? SIM, TODAS AS FOTOS SÃO FIÉIS AO PRODUTO QUE VOCÊ IRÁ RECEBER. Este produto é compatível com o meu veículo? PARA CONFIRMAR, ENVIE A PLACA OU O CHASSI DO SEU VEÍCULO. Em quanto tempo recebo minha compra? INSIRA SEU CEP NO CALCULADOR DE FRETE DO ANÚNCIO PARA CÁLCULO DO PRAZO. Posso retirar? SIM, OPÇÃO DE RETIRADA DISPONÍVEL EM NOSSA LOJA FÍSICA NA PENHA, SÃO PAULO. PEDIMOS A GENTILEZA NÃO AVARIAR A EMBALAGEM ORIGINAL (NÃO PASSE FITA ADESIVA, COLE ETIQUETAS OU RASGUE A EMBALAGEM). ANTES DE EFETUAR DEVOLUÇÃO OU ABRIR RECLAMAÇÃO, ENTRE EM CONTATO CONOSCO PARA QUE POSSAMOS AJUDAR. ATENÇÃO A EMPRESA NÃO SE RESPONSABILIZA POR MAU USO OU INSTALAÇÃO INCORRETA. RECOMENDAMOS INSTALAÇÃO POR PROFISSIONAL ESPECIALIZADO. PALAVRAS-CHAVE: KIT SUSPENSÃO NAKATA GENERAL MOTORS ONIX PRISMA COBALT JOY SPIN BIELETA PIVÔ AXIAL BANDEJA DIANTEIRA SEGURANÇA ESTABILIDADE DURABILIDADE REPOSIÇÃO AUTOMOTIVA ORIGINAL OEM', 999.99, 949.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-824ht-mf1kapm91pfu09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F640634560%2F22298946704', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20472953117', 'Livro Capa dura Um balão flutua até a lua', 'Aconchegue-se, você está quase dormindo, seguro, terno e tranquilo. Relaxe para desfrutar de um sonho lindo, acalentado por um amor profundo. Esta bela história de ninar usa técnicas incríveis de relaxamento, para ajudar seu pequeno na hora de dormir, levando-o a um estado de sono tranquilo e profundo. Prepare-se para embarcar numa viagem linda e mágica rumo ao luar!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2023_x000D_ Autor: Becky Davies_x000D_ Ilustrador: Jennica Lounsbury_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 26.00 x A 26.00 x E 0.97_x000D_ ISBN: 9786526102398_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda Cultural - Ficção infantil_x000D_ Faixa Etária: 0-3 anos_x000D_ Assuntos (tags): Literatura infantil, Criança, Sonho, Sono, 4 anos, Dormir, Magia_x000D_ BISAC: Literatura Infantil / Fantasia & Magia_x000D_ Linha de Produto: Capa dura_x000D_ Encadernação: Capa dura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 64.9, 64.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-23020-dt77opxtndnv1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F20472953117', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
