INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11513496493', 'Livro - Otelo - Capa comum - Principis', 'Dentro da ampla galeria de personagens que ao longo das obras de Shakespeare corporificaram as paixões mais universais e comuns que movem a natureza humana, Otelo passou a representar o homem destruído pelo ciúme. No entanto, apesar de esta característica permanecer na memória coletiva como a mais famosa da obra, este é apenas o ápice visível do tema crucial e mais geral: a desconfiança. Movido pelo veneno que se espalha por meio de seus diálogos e permeia as relações entre casais, entre homens e mulheres, entre chefes e subordinados, Otelo continua a ser, hoje como ontem, uma leitura contundente e poderosa pela perfeição da sua trama e pelo desenvolvimento cerrado dos mecanismos que, tendo como fonte principal Iago, o mais cínico e perigoso diabo humano da literatura, articulam inexoravelmente a ação e acabam por precipitar a tragédia. Editora: Principis Edição: 1, 2021 Autor: William Shakespeare Idioma: Português Páginas: 128 Dimensões: L 15.50 x A 22.60 x E 1.00 ISBN: 9786555521825', 19.9, 19.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/13e12492cafc2014e8fe33a7c593f579', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11513496493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
