INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13188876464', '10 Cake Board 32cm BRANCO Base Para Bolo Suplat Para Confeitaria de Alta Resistência e Impermeável', 'CAKE BOARD BRANCO (BASES LAMINADAS PARA BOLO), LINHA PREMIUM, 10 unidades BRANCO Bases laminadas para bolos, pudins e tortas, produzidas com papelão especial que passa por um processo de dupla laminação. A frente é laminada com filme de poliéster metalizado e o fundo, branco, é laminado com filme transparente, resultando num produto bonito e de melhor qualidade. A dupla laminação proporciona ainda proteção contra umidade, facilidade de higienização e maior resistência à refrigeração. RESISTENTES, COM PROTEÇÃO CONTRA UMIDADE, MAIS HIGIÊNICAS E PODEM SER REFRIGERADAS', 63.15, 63.15, NULL, 'Stationery > Gift & Wrapping > Gift Wrappers', 'https://cf.shopee.com.br/file/3062763ef0e8ac7c74fab4127bb6f6df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F13188876464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4277566435', 'Taça de Vidro Deliss M, Taça de Sobremesa 2pcs, 280ml - Ruvolo', 'Realce suas receitas com a Taça de Vidro Deliss M Para Sobremesa 280ml, ideal para servir mousses, gelatinas, sorvetes e diversas outras opções. Com 280ml de capacidade, a Taça garante a porção perfeita para valorizar cada preparo. Prática e versátil, a Taça de Sobremesa transforma qualquer sobremesa em um momento especial, seja em jantares, encontros ou no dia a dia. Uma escolha certa para quem deseja unir sabor e boa apresentação em cada detalhe. Uso: Cerveja. Material: Vidro. Diâmetro: 154mm. Altura: 125mm. Capacidade: 280ml. Conteúdo da Embalagem: 2 Peças. - Peça medida com o volume máximo até a boca - Diâmetro é medido pela largura maior da peça. - Pode sofrer variação de até 10% de seu volume. Dica de uso e preservação: • Recomendamos que a limpeza da peça seja feita a mão para evitar quebras ou danos. • Limpe a sujeira utilizando uma esponja macia, tire o resíduo de sabão e seque bem. • Não utilize abrasivos ou utensílios pontiagudos. • Evite impactos e não exponha o vidro a mudanças bruscas de temperatura pois poderá causar choque térmico e danificar seu produto. • Para realçar ainda mais o brilho da peça, limpe-a com uma flanela que não solte fiapos, levemente umedecida com álcool.', 71.99, 71.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9zve1kvo35ud8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373594761%2F4277566435', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
