INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19533106663', 'CAIXA SOM AUTOMOTIVO TRIO 1 ALTO FALANTE 12 POLEGADAS MDF 15 MM (L: 61 X A: 33 X P: 36 CM)', 'Conhecidas pelo alto padrão de acabamento e qualidade acústica, as caixas Nandin Sound são confeccionadas com que há de melhor no mercado e todo o processo de corte da madeira é realizado por Router CNC, garantindo encaixes perfeitos e um acabamento inigualável. Todos os projetos são desenvolvidos pelos melhores profissionais da área de som automotivo do Brasil. Conhecida como “caixa trio” ou “caixa de som automotivo” é ideal para quem busca um som com qualidade e potência, desenvolvida em MDF 15 mm com acabamento em carpete resinado. Especificações: - Madeira: MDF 15 mm; - Acabamento: Carpete resinado; - Litragem: 41,6 litros; - Diâmetro do alto falante: 12 polegadas (Informar após a compra o tipo de carcaça "chapa ou alumínio" ); - Dimensões com duto vertical (Largura x Altura x Profundidade): 61 x 33 x 36 cm; - Dimensões duto: Abertura 9 cm x Comprimento 24,5 cm; *Só aceite receber a mercadoria após verificar se a mesma coincide com a que consta no pedido e se está em perfeito estado;', 184.99, 184.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-22100-wtmk3xvmdtiv03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406280808%2F19533106663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
