INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994189082', 'Colchão Casal Gazin Com Molas Ensacadas Rubi 138x188x32cm Cinza/preto - Suporta Até 120kg Por Pessoa Cinza', 'Colchão Casal Gazin Com Molas Ensacadas Rubi 138x188x32cm Cinza/preto - Suporta Até 120kg Por Pessoa Cinza Transforme suas noites de sono com o Colchão de Casal Rubi, ideal para quem busca qualidade e bem-estar. Com capacidade para até 120 kg por pessoa, ele combina design moderno com materiais de alta durabilidade. Seu revestimento superior em matelassê malha, oferece resistência e uma sensação de maciez ao toque, e possui pillow que é uma camada extra de conforto. Além disso, as Molas ensacadas de alta qualidade garantem suporte firme e confortável, tornando suas noites ainda mais relaxantes. Perfeito para quem não abre mão de conforto e elegância! MEDIDAS: A = 32 cm L = 138 cm P = 188 cm PESO: 25,2 Kg PESO SUPORTADO: 120 kg por pessoa MODELO: Colchão Casal Com Molas Ensacadas Rubi 138x188x32cm Suporta Até 120 Kg Por Pessoa MARCA: Gazin COR: Cinza/Preto REVESTIMENTO SUPERIOR: Tecido de malha cinza floral (matelassê) com fibra siliconada REVESTIMENTO LATERAL: Tecido 100% poliéster, por ser sintético não é propenso ao acúmulo de poeira e materiais orgânico, além de ser de fácil higienização REVESTIMENTO INTERIOR: Molas Ensacadas aliada com espuma D60, permitindo que o colchão suporte até 120 kg por pessoa MOLAS: Molas ensacadas de alta qualidade, que proporcionam maior suporte ao corpo POSSUI EPS: Sim PILLOW: Sim, oferecendo ainda mais sensação de conforto ITENS INCLUSOS: 1 Colchão de 1,38m INSTRUÇÕES E CUIDADOS: Utilizar em local seco com passagem de ar, não dobrar, fazer giro quinzenalmente no sentido pés/cabeceira GARANTIA: 12 Meses pelo Fabricante A Esplanada Móveis se responsabiliza pela dos produtos adquiridos até a porta de entrada ou portaria do