INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41252611647', 'Haikyu!! Vol. 16 - Big - JBC', 'Atsumu Miya, do Inarizaki, encontrou um alvo favorito para atacar! Enquanto acumula pontos de serviço, Atsumu continua atacando... Nishinoya?! Mesmo com o Karasuno se afundando cada vez mais durante o segundo set, o time segue lentamente minando o avanço do Inarizaki. Conseguiria o Karasuno virar o jogo e manter vivo o sonho da Batalha do Lixão? Com o Inarizaki mantendo o ritmo, bem quando os gêmeos Miya consideram que pegaram o Karasuno de jeito, seu ataque é interrompido pela última pessoa que qualquer um poderia imaginar!', 52.49, 52.49, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rav0-madh8poqavtc1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F41252611647', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
