INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19323257636', 'Calça E Camisa Insane In Black Todos Os Tamanhos', 'Kit Composto por: 1 Calça; 1 Camisa. A Calça Pro Tork Insane In Black é produzida em poliéster 600 fios e elastano. Ela conta com apliques emborrachados estrategicamente posicionados, regulagem na cintura, fechamento por zíper e mais dois botões, costura dupla reforçada, forração interna ventilada, placa de tecido antichama, modelagem anatômica com 13 painéis e articulações elásticas nos joelhos para maior mobilidade. Especificações: - Modelo: Insane In Black; - Confeccionada em Poliéster 600 fios e elastano; - Apliques emborrachados estrategicamente posicionados; - Regulagens na cintura; - Fechamento por zíper e mais dois botões conferindo o ajuste ideal; - Costura dupla reforçada; - Forração interna ventilada; - Placa de tecido antichama na região interna dos joelhos, oferece proteção contra a alta temperatura do motor; - Modelagem ergonômica com 13 painéis; - Articulações elásticas nos joelho; -Tamanhos disponíveis: 38, 40, 42, 44, 46, 48, 50, 52, 54, 56; - Marca: Pro Tork. Dicas: - Recomendamos optar por um número maior, do que o seu utilizado casualmente, para maior conforto. Exemplo (Se seu número de calça jeans é 38 adquirir o tamanho 40). A Camisa Pro Tork Insane In Black é fabricada em tecido 100% poliéster. Possui cauda alongada em relação à cintura do piloto, fazendo com que a camisa não saia de dentro da calça. Especificações: - Modelo: Insane In Black; - Cor: Preta; - Disponível nos tamanhos: P, M, G, GG e XG; - Grafismos sublimados; - Modelagem com gola V; - Etiqueta interna aplicada em termo transferência, que permite que o atleta identifique suas informações no produto; - Marca: Pro Tork. Dicas: - Recomendado optar pelo mesmo tamanho utilizado para camisas casuais.', 347.16, 199.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sets', 'https://cf.shopee.com.br/file/sg-11134201-22100-h08m062ra4ivf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F19323257636', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19877744968', 'Protetor De Carenagem Pro Tork Armor Com Pedaleira Retrátil Xre 190', 'O Protetor de Motor e Carenagem Armor é essencial para quem utiliza a moto diariamente. Pois protege a moto em caso de eventuais quedas, muito comuns nos grandes centros urbanos devido ao grande fluxo de veículos, evitando assim maiores prejuízos. Possui também encaixe para sliders (não incluso) e pedaleira de descanso, agregando muito mais conforto e estilo para sua moto. Características: - Modelo: Armor; - Marca: Super Adventure - Material: Aço Tubular; - Cor: Preto; - Acompanha pedaleira de descanso (Já instalada); - Possui suporte para slider (Não incluso). Aplicação: - XRE 190 2016; - XRE 190 2017; - XRE 190 2018; - XRE 190 2019; - XRE 190 2020; - XRE 190 2021; - XRE 190 2022. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 242.0, 179.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvd9-lffrzotkaojpbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F19877744968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
