INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692886645', 'Cartão de Memória MicroSd Sandisk 256gb Micro Sd Ultra 100Mbs', 'Cartão de Memória MicroSD Sandisk 256GB Ultra Velocidade de 100Mbs alta capacidade Armazenamento Gravação e Reprodução de Vídeos Full HD e Fotos de Alta Resolução Design Compacto - No Brasil Aumente a capacidade do seu smartphone, câmera ou outro dispositivo com o Cartão de Memória MicroSD Sandisk 256GB Ultra. Com 256GB de armazenamento, você tem amplo espaço para suas fotos, vídeos, músicas e documentos de trabalho; Este cartão MicroSD oferece velocidade de transferência de até 100Mbs, proporcionando transferências de arquivos rápidas e eficientes entre seus dispositivos. Isso significa que você pode passar menos tempo esperando e mais tempo desfrutando do seu conteúdo; O cartão de memória também é otimizado para a gravação e reprodução de vídeos Full HD. Portanto, você pode capturar e preservar seus momentos favoritos em alta qualidade sem se preocupar com espaço ou velocidade; O Cartão de Memória MicroSD Sandisk 256GB Ultra apresenta um design compacto e discreto. Pequeno o suficiente para caber em qualquer bolso ou estojo de transporte, tornando-o perfeito para viagens ou uso diário; Finalmente, este cartão é fácil de usar. Basta inseri-lo no slot MicroSD de seu dispositivo e você estará pronto para começar a armazenar e acessar seus arquivos. Garantia: 90 dias.', 598.85, 598.85, NULL, 'Mobile & Gadgets > Accessories > Memory Cards', 'https://cf.shopee.com.br/file/br-11134201-7r98o-maehopo5z115ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163364765%2F23692886645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297986157', 'Torquês Armador Tramontina 12"', 'O Torquês Armador Tramontina 12" 41052 é uma ferramenta indispensável para profissionais e entusiastas da marcenaria e carpintaria, proporcionando fixação firme e controle preciso em diferentes tipos de trabalhos. Desenvolvido para oferecer resistência e confiabilidade, é ideal para prender, ajustar e montar peças com segurança. Fabricado em aço forjado e temperado com acabamento oxidado, garante maior durabilidade e proteção contra desgaste, mantendo o desempenho mesmo em uso contínuo. Com peso de 500 g e dimensões de 25 cm de comprimento, 10 cm de largura e 5 cm de altura, apresenta equilíbrio perfeito entre força e manuseio, facilitando operações precisas sem esforço excessivo. Perfeito para uso em marcenaria, carpintaria e trabalhos manuais, permite que o profissional realize ajustes e fixações com segurança e praticidade, sendo uma ferramenta confiável para o dia a dia. Principais características: Torquês armador de 12" (30 cm) Aço forjado e temperado para alta resistência Acabamento oxidado, resistente ao desgaste Peso: 500 g – leve e ergonômico Dimensões: 25 cm (comprimento) x 10 cm (largura) x 5 cm (altura) Ideal para marcenaria, carpintaria e trabalhos manuais', 97.9, 68.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rep2-m2idk88dqzb7d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F19297986157', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
