INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693474001', 'CD Imagine Dragons - Mercury - Acts 1 & 2 (Brillian Box International / 2CD Deluxe) - Importado', 'CD Imagine Dragons - Mercury - Acts 1 & 2 (Brillian Box International / 2CD Deluxe) - Importado Produção Executiva de Rick Rubin Mercury – Acts 1 & 2, o álbum deluxe com 2 CDs lançado em 01 de julho de 2022 pela KIDinaKORNER/Interscope Records O ato 1 já está disponível, incluindo os hits “Follow You” “Wrecked” e “Enemy” ft. JID. Act 2 apresenta 18 músicas adicionais, incluindo o novo single “Bones.” Repertório dos CDs: Disc 1 - Act 1: 1. Enemy (Feat. J.I.D) 2. My Life 3. Lonely 4. Wrecked 5. Monday 6. #1 7. Easy Come Easy Go 8. Giants 9. It''s Ok 10. Dull Knives 11. Follow You 12. Cutthroat 13. No Time For Toxic People 14. One Day Disc 2 - Act 2: 1. Bones 2. Symphony 3. Sharks 4. I Don''t Like Myself 5. Blur 6. Higher Ground 7. Crushed 8. Take It Easy 9. Waves 10. I''m Happy 11. Ferris Wheel 12. Peace Of Mind 13. Sirens 14. Tied 15. Younger 16. I Wish 17. Continual (feat. Cory Henry) 18. They Don''t Know You Like I Do', 109.9, 82.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8261q-mkmqxq3l493b23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F23693474001', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
