INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298248433', 'Kit Porta de Madeira 210x82cm Batente 16cm Lisa Primer Uniportas Abertura Esquerda Esquerda', 'A porta Lisa Primer é a escolha ideal para quem busca versatilidade na decoração, pois permite pintura em diversas cores, oferecendo total liberdade para personalização de acordo com sua preferência. Sua estrutura é fabricada em madeira de reflorestamento, com preenchimento em colmeia Honeycomb, uma tecnologia americana. O acabamento prévio de fundo para pintura, na cor branca, facilita o processo de pintura, reduzindo o número de demãos necessárias e garantindo uma cobertura mais uniforme e lisa. O batente, que complementa o kit de porta, é confeccionado em madeira maciça de pinus e revestido com fundo para pintura. O kit inclui uma fechadura do modelo roseta Modena, da marca MGM, na cor aço escovado. Estilo: Tradicional Peso (kg): 22 Elétrica: Não Garantia: 06 Meses Altura (cm): 210 Largura (cm): 82 Espessura (cm): 3 Possui Grade: Não Possui Vidro: Não Cor do Batente: Branco Tipo de Batente: Fixo Tipo de Madeira: HDF Acompanha Trinco: Não Escala de Brilho: Fosco Imune à Corrosão: Não Lado de Abertura: Esquerda Textura da Porta: Lisa Acompanha Batedor: Não Acompanha Batente: Sim Acompanha Puxador: 1 Origem do Produto: Nacional Tipo de Dobradiça: Simples Ambiente Principal: Interno Largura do Batente: 16 Acompanha Dobradiça: 3 Acompanha Fechadura: Sim Acompanha Guarnição: Não Material do Batente: Madeira Necessita Instalação: Não Material da Dobradiça: Metalica Resistência à Maresia: Não Resistência à Umidade: Não Acompanha Ficha Técnica: Sim Abertura para Ventilação: Não Possui Isolamento Acústico: Não Possui Fechamento Automático: Não Acompanha Manual de Instalação: Sim Dimensão da Maquina da Fechadura: 40 Acabamento (Construção e Acabamento): Primer Material Principal Construção e Acabamento: Madeira Marca: Uniportas Itens Inclusos: Folha, Batente, Fechadura, Dobradiças Tamanho do Produto: 210cm x 82cm Medida do Vão (A x L): 215cmx89cm', 949.61, 949.61, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-820np-mnu5r3qu988y49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22298248433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
