INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797604008', 'O Melhor do Folclore Brasileiro', 'Quem nunca ouviu falar do Saci-Pererê, da Mula sem Cabeça e do Curupira? São histórias que fazem parte do conjunto de mitos e lendas que traduzem o follclore brasileiro. Passadas oralmente de geração para geração, muitas dessas passagens antigas e populares transmitem valores de cunho moral e reafirmam a identidade de diversos povos, tornando-se uma parte essencial da cultura do nosso País. Aqui você acompanha história de alguns dos personagens lendários mais conhecidos, contadas de forma divertida e ricamente ilustrada.', 29.99, 28.5, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd6p-lwt4bdetfs5v0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F22797604008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
