INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998567223', 'Sofá Retrátil Sem Caixa 3 Lugares Solomons Velosuede Grafite 230 cm', 'Que tal o Sofá Retrátil sem Caixa Solomons? Aconchegante e receptivo, o Sofá Retrátil sem Caixa Solomons tem tudo para deixar sua casa mais confortável. Estruturado em materiais resistentes, ele tem assento e encosto com enchimento em espuma e almofadas soltas em plumante de silicone, conferindo muito bem-estar e aconchego a quem está usando. Além de ser acolhedor e se transformar também em sofá-cama, o móvel é ideal para ambientes menores, pois é do tipo sem caixa, que otimiza o espaço disponível no cômodo e libera mais área de circulação. Tudo isso é arrematado com um design clean e elegante que destaca a cor atemporal e com certeza vai deixar seu cantinho impecável, digno de muitos elogios.', 3339.96, 2943.33, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rd4n-m7tfiueqzjtg7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F22998567223', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897706928', 'REDE ELASTICA PARA CAPACETE 35x35 ou 42x42 - ( PRETA / VERMELHA )', 'REDE ELASTICA PARA CAPACETE 42X42 - ( PRETA / VERMELHA ) Produto resistente de tamanho 42 cm x 42 cm nas cores PRETO e VERMELHO. Contém 6 ganchos que podem ser tirados e colocados da forma que precisar.', 12.99, 12.99, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lyp5x9wbjd459b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207146999%2F22897706928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
