INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18598697117', 'Kit 3 Creme Dental Closeup Dentes mais Brancos 90g', '• Creme Dental Closeup Dentes + Brancos* foi desenvolvido com ingrediente que deixa os dentes mais brancos em 2 semanas • Protege contra as cáries • Fórmula com sabor refrescante de menta, com um toque único de notas de anis e eucalipto • O creme dental para branqueamento ajuda na remoção de manchas da superfície dos dentes • Closeup Dentes + Brancos* contém flúor na sua formulação que contribui para a saúde bucal • Fórmula que ajuda a remover a placa** O Creme Dental Closeup Dentes + Brancos* possui em sua fórmula o benefício de deixar seus dentes mais brancos e saudáveis. Sua fórmula atua no esmalte dos dentes, ajudando na redução de manchas acumuladas com o tempo sobre a superfície dental, manchas essas provenientes de alimentos e bebidas como o café. Closeup Dentes + Brancos contribui para a sua saúde bucal, protegendo os seus dentes contra as cáries por conter flúor em sua fórmula. O sabor menta refrescante, apresenta notas de menta específicas (peppermint menthol), acrescentadas de uma combinação única de notas de anis e eucalipto, com um toque sutil de maçã. Experimente o Closeup Dentes + Brancos para você ter confiança de chegar mais perto! O creme dental para branqueamento está disponível no tamanho de 90g e 130g. Ao escovar seus dentes todos os dias após as refeições com o creme dental Close Up e escova de dente, você cuida da sua saúde bucal e garante um hálito fresco. Branqueamento em 2 semanas, seguindo recomendações de uso. Com escovação regular.', 13.47, 13.47, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-825b4-mqmqbfj8v3m491', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18598697117', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
