INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52159319074', 'Mini Brands Fill The Fridge Mini Minis', 'Crie a cozinha dos sonhos em miniatura com o Mini Brands Fill The Fridge – Série 1. Cada cápsula traz miniaturas detalhadas de mais de 60 itens, incluindo snacks, bebidas, produtos de mercearia e clássicos de cozinha. Cada cápsula ainda contém um mini surpresa, garantindo emoção a cada descoberta. Perfeito para fãs de miniaturas, brincadeiras criativas e colecionáveis, o Mini Brands Fill The Fridge permite montar seu playset de geladeira e explorar infinitas combinações de itens em miniatura. Alguns minis são raros e criáveis, permitindo personalizar e adicionar seu toque especial à coleção. Com atenção aos detalhes, cada item reproduz fielmente produtos do cotidiano, tornando a brincadeira divertida e realista. Além disso, a linha é feita com plástico reciclado certificado, garantindo diversão sustentável. Descubra, organize e preencha sua geladeira com Mini Brands Fill The Fridge, o brinquedo ideal para crianças, fãs de miniaturas e colecionadores que apreciam surpresa, criatividade e diversão em um só produto.', 99.99, 99.99, NULL, 'Hobbies & Collections > Collectible Items > Idol Collectibles', 'https://cf.shopee.com.br/file/sg-11134201-823rs-mohbkui2ocnh0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F52159319074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
