INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394315657', 'Aquabeads Shiny Bead Pack - Epoch', 'O Conjunto Aquabeads Shiny Beads Refil da Epoch é uma adição brilhante à coleção de qualquer entusiasta de artesanato. Com uma variedade de contas cintilantes em cores deslumbrantes, este conjunto permite que você crie obras de arte únicas e reluzentes usando o método de aquabeads. Dê vida à sua imaginação e crie deslumbrantes obras de arte com o Conjunto Aquabeads Shiny Beads Refil da Epoch. Com sua seleção de contas cintilantes e cores deslumbrantes, este conjunto é a escolha perfeita para criar peças de arte brilhantes e reluzentes que irão encantar e impressionar! Fabricante: Epoch Ref.: 31995 Código Barras: 5054131319956 Idade recomendada: Acima de 4 Anos Dimensões da Embalagem (AxLxC)24X27X5cm Garantia do Vendedor: 7 dias Garantia do Fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 199.99, 199.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdewkcqgoo1lec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F23394315657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
