INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253120985', 'La Roche-Posay Cicaplast Baume B5+ - Hidratante Multirreparador 40ml', 'Hidratante multirreparador para peles sensibilizadas. La Roche-Posay Cicaplast Baume B5+ acelera e melhora a reparação da barreira cutânea, fornecendo um cuidado eficaz com resultados efetivos. O Hidratante Multirreparador La Roche-Posay Cicaplast Baume B5+ colabora para a prevenção de assaduras e trata lábios fragilizados, descamações, sensação de queimaduras solares e ressecamento intenso. Seu uso é extremamente indicado após procedimentos dermatológicos e desconfortos na pele. Como usar: Aplicar duas vezes ao dia na pele limpa e seca. Pode ser aplicado no corpo, rosto e lábios. Evitar o contorno dos olhos. Não ingerir. Manter fora do alcance das crianças sem supervisão. Não aplicar na pele com feridas abertas. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 108.9, 108.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-825zu-mjec6t7jvawwd4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253120985', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257060134', 'Isdin Hydration Ureadin Calm - Óleo de Banho 200ml', 'Óleo de banho. Isdin Hydration Ureadin Calm aumenta até 44% da hidratação da pele após o banho, já que promove uma limpeza suave e duradoura. O Óleo de Banho Isdin Hydration Ureadin Calm forma uma barreira protetora, hodratando e limpando sem agredir a pele, graças a fórmula ProComfort rica em Ômega 3 e 6. Como usar: Pode ser utilizado em todo o rosto e corpo, sete dias por semana, na ducha ou em banho de imersão (banheira). **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 114.9, 114.9, NULL, 'Beauty > Skincare > Facial Oil', 'https://cf.shopee.com.br/file/sg-11134201-8261i-mlxl76z1dudh47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58257060134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
