INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797835726', 'SR. BOAVENTURA', 'SR. BOAVENTURA Sr. Boaventura é uma história contada por J.R.R. Tolkien aos seus filhos pequenos na década de 1930. Além de escrever tudo à mão, Tolkien também fez as ilustrações que compõem o livro. Considerado um conto de excentricidade, seu enredo e desenhos são comparados a clássicos da literatura infantil como As Aventuras de Alice no País das Maravilhas, de Lewis Carrol, Pedro Coelho, de Beatrix Potter, e A Book of Nonsense, de Edward Lear.Sr. Boaventura é um sujeito metódico, que gosta de usar chapéus altos e está acostumado a uma vida pacata em sua casa de cômodos também altos, na companhia de Girafoelho, seu excêntrico bicho de estimação, que quase só acorda para comer. Um dia, Sr. Boaventura decide comprar um carro e visitar seus amigos, os Broncos. A partir de então, ele se mete em grandes enrascadas, envolvendo seus amigos e conhecidos nelas.Apesar de ser uma história bem diferente do restante da obra de Tolkien, mais voltada a crianças pequenas, Sr. Boaventura já tem alguns traços típicos do autor, como a sua crítica à modernidade e toques de insólito. O resultado é uma divertida história, cheia de ação e peripécias que garantem boas risadas a crianças e adultos.. Informações Adicionais Autor: TOLKIEN, J.R.R. Data Publicação: 30/12/1899 Tipo de capa: CAPA DURA Condição do Item: Novo Subtitulo: SR. BOAVENTURA Idioma: INDEFINIDO Páginas: 112 Edição: 1 ISBN-13: 9788595085688 ISBN-10: 8595085684', 74.9, 56.18, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbne-lpjaygkoc32fad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23797835726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997556991', 'Escorredor Louca Secador Porta Talheres Não Enferruja Preto', 'Escorredor Louca Secador Porta Talheres Não Enferruja Preto Nossa eterna gratidão à quem inventou os escorredores! Sempre sobram pratos, talheres e copos após nossas refeições, mas com o escorredor podemos agilizar as tarefas na cozinha. O Escorredor Aramado vai deixar sua rotina doméstica muito mais prática. Basta considerar o tamanho da sua pia e as necessidades da família para encontrar o modelo perfeito! O Escorredor de Pratos devidamente projetado para a vida moderna. Com desenho sofisticado, esse modelo é funcional tanto para uma cozinha pequena quanto para uma cozinha grande, otimizando espaços de forma a comportar até mesmo um volume maior de louças em 2 bandejas. A base coletora de água evita molhar a pia, fazendo com que os pratos sequem com mais agilidade. Além disso, evita os danos que a umidade pode causar, como proliferação de bactérias, fungos e acúmulo de sujeiras. A base permite regulagem de altura para escorrer diferentes tipos de louças. Vantagens: • Escorredor Adaptável; • Base coletora de água; • Praticidade;• Otimização de espaços; • Porta copos adaptável; • Porta talheres removível; • Acabamento resistente à umidade; • Não enferruja; • Grades ajustáveis com regulagem de altura. DetalhesAmbientes recomendados para uso: • Cozinha; • Bancada da cozinha; • Pia da cozinha. Comprimento x Largura x Altura 41 cm x 23.5 cm x 26 cm', 79.9, 45.9, NULL, 'Home & Living > Kitchenware > Kitchen Racks', 'https://cf.shopee.com.br/file/sg-11134201-823op-moigrphkbjlv61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F421977782%2F22997556991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
