INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798016017', 'KIT PAR DE LÂMPADAS TRASEIRA PARA LANTERNA E FREIO SETA RÉ UNIVERSAL COMPATÍVEL COM DIVERSOS CARROS', 'KIT LÂMPADAS TRASEIRA HALÓGENAS LANTERNA FREIO SETA RÉ UNIVERSAL Mantenha-se seguro e visível em qualquer situação com o Kit de Lâmpadas Universais. Compatíveis com diversos veículos, são essenciais para garantir sua sinalização sempre em dia, evitando riscos e possíveis multas. Esteja preparado para qualquer eventualidade e dirija com a tranquilidade de quem está sempre protegido. Especificações: Lâmpada para Sinalização Alta durabilidade Excelente Visibilidade Tensão de Operação: 12v Potência de Saída: 21W Conteúdo da Embalagem: 2 Lâmpadas 1 Polo - Seta (Ambar) 2 Lâmpadas 2 Polo - Freio/ Lanterna (Cristal) 2 Lâmpadas 1 Polo - Ré (Cristal) 2 Lâmpadas T10 - Farolete (Cristal) 2NTV160.2N195.2N161.2N209', 29.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7repo-m2b1yghik2qy69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F23798016017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
